import type { AlignmentAction, AlignmentPosition } from "./alignment-control-state";

/** A layer's box, in your canvas's units. */
export type AlignmentRect = { id: string; x: number; y: number; width: number; height: number };
export type AlignmentBounds = Omit<AlignmentRect, "id">;

/** The box around every rect. */
export function boundsOf(rects: AlignmentBounds[]): AlignmentBounds {
  const left = Math.min(...rects.map((rect) => rect.x));
  const top = Math.min(...rects.map((rect) => rect.y));
  const right = Math.max(...rects.map((rect) => rect.x + rect.width));
  const bottom = Math.max(...rects.map((rect) => rect.y + rect.height));
  return { x: left, y: top, width: right - left, height: bottom - top };
}

const place = (start: number, size: number, span: number, at: AlignmentPosition["x"]) =>
  at === "start" ? start : at === "end" ? start + span - size : start + (span - size) / 2;

/**
 * Applies an action to the selected rects, in their original order. One rect aligns to `parent`,
 * several to their own bounds. Distributing keeps the outer two in place and evens the gaps between all of them.
 */
export function alignRects<T extends AlignmentRect>(rects: T[], action: AlignmentAction, parent?: AlignmentBounds): T[] {
  if (rects.length === 0) return rects;
  if (action === "distribute-horizontal" || action === "distribute-vertical") {
    if (rects.length < 3) return rects;
    const horizontal = action === "distribute-horizontal";
    const start = (rect: AlignmentRect) => (horizontal ? rect.x : rect.y);
    const size = (rect: AlignmentRect) => (horizontal ? rect.width : rect.height);
    const sorted = [...rects].sort((a, b) => start(a) - start(b));
    const first = start(sorted[0]);
    const last = Math.max(...sorted.map((rect) => start(rect) + size(rect)));
    const gap = (last - first - sorted.reduce((sum, rect) => sum + size(rect), 0)) / (sorted.length - 1);
    const moved = new Map<string, number>();
    let cursor = first;
    for (const rect of sorted) {
      moved.set(rect.id, cursor);
      cursor += size(rect) + gap;
    }
    return rects.map((rect) => ({ ...rect, [horizontal ? "x" : "y"]: moved.get(rect.id)! }));
  }
  const bounds = rects.length === 1 && parent ? parent : boundsOf(rects);
  return rects.map((rect) => {
    switch (action) {
      case "left":
        return { ...rect, x: bounds.x };
      case "center":
        return { ...rect, x: place(bounds.x, rect.width, bounds.width, "center") };
      case "right":
        return { ...rect, x: place(bounds.x, rect.width, bounds.width, "end") };
      case "top":
        return { ...rect, y: bounds.y };
      case "middle":
        return { ...rect, y: place(bounds.y, rect.height, bounds.height, "center") };
      default:
        return { ...rect, y: place(bounds.y, rect.height, bounds.height, "end") };
    }
  });
}

/** Moves a rect to a grid position inside its parent. */
export function positionRect<T extends AlignmentBounds>(rect: T, position: AlignmentPosition, parent: AlignmentBounds): T {
  return { ...rect, x: place(parent.x, rect.width, parent.width, position.x), y: place(parent.y, rect.height, parent.height, position.y) };
}

/** Where a rect sits in its parent, or null when it is not at one of the nine positions. */
export function positionOf(rect: AlignmentBounds, parent: AlignmentBounds, tolerance = 0.5): AlignmentPosition | null {
  const axis = (start: number, size: number, from: number, span: number) =>
    (["start", "center", "end"] as const).find((at) => Math.abs(place(from, size, span, at) - start) <= tolerance) ?? null;
  const x = axis(rect.x, rect.width, parent.x, parent.width);
  const y = axis(rect.y, rect.height, parent.y, parent.height);
  return x && y ? { x, y } : null;
}

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactElement, type RefObject, forwardRef, useRef } from "react";
import { type AlignmentControlMessages, type AlignmentPosition, defaultMessages } from "./alignment-control-state";
import { cn } from "@/lib/utils";

const axis = ["start", "center", "end"] as const;
const cells = axis.flatMap((y) => axis.map((x) => ({ x, y })));
const same = (a: AlignmentPosition | null, b: AlignmentPosition) => !!a && a.x === b.x && a.y === b.y;

export type AlignmentGridProps = Omit<ComponentPropsWithoutRef<"div">, "defaultValue" | "onChange"> & {
  /** Where the layer sits in its frame; null when it is between positions or a selection differs. */
  value: AlignmentPosition | null;
  /** Called with the position picked. Your app moves the layer. */
  onValueChange: (position: AlignmentPosition) => void;
  disabled?: boolean;
  /** Name each cell in a tooltip on hover, such as "Top left". On by default. */
  tooltips?: boolean;
  /** Tooltip entrance transitions. Reduced motion is always honored. */
  motion?: boolean;
  tooltipClassName?: string;
  /** Class for each cell and for the mark inside it. */
  cellClassName?: string;
  markClassName?: string;
  messages?: Partial<Pick<AlignmentControlMessages, "grid" | "position">>;
};

/**
 * Nine positions for a layer in its frame, as one radio group: arrow keys move across and down,
 * and the current position holds the tab stop.
 */
export const AlignmentGrid = forwardRef<HTMLDivElement, AlignmentGridProps>(function AlignmentGrid(
  { value, onValueChange, disabled = false, tooltips = true, motion = true, tooltipClassName, cellClassName, markClassName, messages: messagesProp, className, onKeyDown, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  const root = useRef<HTMLDivElement | null>(null);
  // With no position, the centre takes the tab stop.
  const focusable = value ?? { x: "center", y: "center" };
  return (
    <div
      ref={(node) => {
        root.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      role="radiogroup"
      aria-label={messages.grid}
      aria-disabled={disabled || undefined}
      data-disabled={disabled || undefined}
      data-mixed={value === null || undefined}
      className={cn(
        "grid size-[calc(var(--uicoolkit-field-height,2.5rem)*2-0.5rem)] shrink-0 grid-cols-3 grid-rows-3 rounded-md border border-input bg-muted p-0.5 dark:bg-input/40 data-disabled:opacity-50",
        className,
      )}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || disabled) return;
        const from = (event.target as HTMLElement).dataset;
        if (!from.x || !from.y) return;
        const step = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[event.key];
        if (!step) return;
        event.preventDefault();
        const x = axis[Math.min(2, Math.max(0, axis.indexOf(from.x as AlignmentPosition["x"]) + step[0]))];
        const y = axis[Math.min(2, Math.max(0, axis.indexOf(from.y as AlignmentPosition["y"]) + step[1]))];
        onValueChange({ x, y });
        event.currentTarget.querySelector<HTMLElement>(`[data-x="${x}"][data-y="${y}"]`)?.focus();
      }}
      {...props}
    >
      <Tooltip.Provider delay={400}>
        {cells.map((cell) => {
          const button = (
            <button
              key={`${cell.y}-${cell.x}`}
              type="button"
              role="radio"
              data-x={cell.x}
              data-y={cell.y}
              aria-checked={same(value, cell)}
              aria-label={messages.position(cell)}
              disabled={disabled}
              tabIndex={same(focusable, cell) ? 0 : -1}
              onClick={() => onValueChange(cell)}
              className={cn(
                "group/cell grid place-items-center rounded-sm outline-none focus-visible:bg-foreground/10 disabled:cursor-not-allowed",
                cellClassName,
              )}
            >
              {/* A dot for each spot; the current one becomes the layer, and hovering previews it. */}
              <span
                aria-hidden
                className={cn(
                  "size-1 rounded-full bg-muted-foreground/50 transition-all duration-150 motion-reduce:transition-none",
                  "group-enabled/cell:group-hover/cell:size-2 group-enabled/cell:group-hover/cell:rounded-[2px] group-enabled/cell:group-hover/cell:bg-muted-foreground",
                  "group-aria-checked/cell:size-2.5 group-aria-checked/cell:rounded-[3px] group-aria-checked/cell:bg-foreground",
                  markClassName,
                )}
              />
            </button>
          );
          // A cell's name on hover, as with the toolbar's buttons; disabled cells skip it.
          return tooltips && !disabled ? (
            <CellTip key={`${cell.y}-${cell.x}`} label={messages.position(cell)} container={root} motion={motion} className={tooltipClassName}>
              {button}
            </CellTip>
          ) : (
            button
          );
        })}
      </Tooltip.Provider>
    </div>
  );
});

type CellTipProps = { label: string; container: RefObject<HTMLDivElement | null>; motion: boolean; className?: string; children: ReactElement };

/** A cell's name on hover, portalled into the grid so it keeps the grid's theme. */
function CellTip({ label, container, motion, className, children }: CellTipProps) {
  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={children} />
      <Tooltip.Portal container={container}>
        <Tooltip.Positioner side="top" sideOffset={6} positionMethod="fixed" className="z-50">
          <Tooltip.Popup
            className={cn(
              "rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md",
              motion &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
              className,
            )}
          >
            {label}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

"use client";

import { type ComponentPropsWithoutRef, type MutableRefObject, type Ref, createContext, useContext } from "react";

/** The six align actions and the two distribute actions. */
export type AlignmentAction = "left" | "center" | "right" | "top" | "middle" | "bottom" | "distribute-horizontal" | "distribute-vertical";

/** What an align action lines layers up against: the parent frame for one layer, the selection's bounds for several. */
export type AlignmentTarget = "parent" | "selection";

/** A spot in a 3×3 grid: where a layer sits in its frame on each axis. */
export type AlignmentPosition = { x: "start" | "center" | "end"; y: "start" | "center" | "end" };

/** Replaceable text, for example to translate. */
export type AlignmentControlMessages = {
  toolbar: string;
  actions: Record<AlignmentAction, string>;
  /** Shown in the tooltip of an action that needs more layers selected. */
  needs: (count: number) => string;
  grid: string;
  position: (position: AlignmentPosition) => string;
};

const words = { start: { x: "left", y: "Top" }, center: { x: "centre", y: "Middle" }, end: { x: "right", y: "Bottom" } } as const;

export const defaultMessages: AlignmentControlMessages = {
  toolbar: "Alignment",
  actions: {
    left: "Align left",
    center: "Align horizontal centres",
    right: "Align right",
    top: "Align top",
    middle: "Align vertical centres",
    bottom: "Align bottom",
    "distribute-horizontal": "Distribute horizontal spacing",
    "distribute-vertical": "Distribute vertical spacing",
  },
  needs: (count) => (count === 1 ? "Select a layer" : `Select ${count} or more layers`),
  grid: "Position in frame",
  position: ({ x, y }) => (x === "center" && y === "center" ? "Centre" : `${words[y].y} ${words[x].x}`),
};

/** How many layers each action needs. */
export const minimumFor = (action: AlignmentAction) => (action.startsWith("distribute") ? 3 : 1);

export type AlignmentControlProps = Omit<ComponentPropsWithoutRef<"div">, "onChange"> & {
  /** How many layers are selected. One aligns to its parent; distribute needs three or more. */
  selectionCount: number;
  /** Called with the action and what it aligns to. Your app moves the layers. */
  onAlign: (action: AlignmentAction, detail: { target: AlignmentTarget }) => void;
  /** Shortcut text shown in each action's tooltip, such as "Alt+A". Your app binds the keys. */
  shortcuts?: Partial<Record<AlignmentAction, string>>;
  disabled?: boolean;
  /** Tooltip transitions. Reduced motion is always honored. */
  motion?: boolean;
  messages?: Partial<AlignmentControlMessages>;
};

export type AlignmentControlContextValue = {
  selectionCount: number;
  align: (action: AlignmentAction) => void;
  shortcuts: Partial<Record<AlignmentAction, string>>;
  disabled: boolean;
  animated: boolean;
  messages: AlignmentControlMessages;
  /** The action that holds the toolbar's single tab stop. */
  active: AlignmentAction | null;
  setActive: (action: AlignmentAction) => void;
  rootRef: MutableRefObject<HTMLDivElement | null>;
};

export const AlignmentControlContext = createContext<AlignmentControlContextValue | null>(null);

export function useAlignmentControl() {
  const context = useContext(AlignmentControlContext);
  if (!context) throw new Error("Alignment Control parts must be used inside <AlignmentControl>.");
  return context;
}

export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<T | null>).current = node;
    }
  };
}

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactNode, forwardRef, useEffect, useRef, useState } from "react";
import {
  type AlignmentAction,
  type AlignmentControlContextValue,
  type AlignmentControlProps,
  AlignmentControlContext,
  defaultMessages,
  mergeRefs,
  minimumFor,
  useAlignmentControl,
} from "./alignment-control-state";
import { cn } from "@/lib/utils";

const actionSelector = "[data-align-action]";

/**
 * Align and distribute buttons for the selected layers, as one toolbar: arrow keys move between
 * the buttons and Tab leaves it. The control reports the action; your app moves the layers.
 */
export const AlignmentControl = forwardRef<HTMLDivElement, AlignmentControlProps>(function AlignmentControl(
  { selectionCount, onAlign, shortcuts = {}, disabled = false, motion = true, messages: messagesProp, className, onKeyDown, children, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp, actions: { ...defaultMessages.actions, ...messagesProp?.actions } };
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [active, setActive] = useState<AlignmentAction | null>(null);

  // Give the tab stop to the first button until one is focused, and again if that button goes away.
  useEffect(() => {
    const buttons = [...(rootRef.current?.querySelectorAll<HTMLElement>(actionSelector) ?? [])];
    if (buttons.some((button) => button.dataset.alignAction === active)) return;
    const first = buttons[0]?.dataset.alignAction as AlignmentAction | undefined;
    if (first) setActive(first);
  }, [active, children]);

  const context: AlignmentControlContextValue = {
    selectionCount,
    align: (action) => {
      if (disabled || selectionCount < minimumFor(action)) return;
      onAlign(action, { target: selectionCount === 1 ? "parent" : "selection" });
    },
    shortcuts,
    disabled,
    animated: motion,
    messages,
    active,
    setActive,
    rootRef,
  };

  return (
    <AlignmentControlContext.Provider value={context}>
      <Tooltip.Provider delay={400}>
        <div
          ref={mergeRefs(ref, rootRef)}
          role="toolbar"
          aria-label={messages.toolbar}
          aria-disabled={disabled || undefined}
          data-disabled={disabled || undefined}
          className={cn("flex flex-wrap items-center gap-1.5", className)}
          onKeyDown={(event) => {
            onKeyDown?.(event);
            if (event.defaultPrevented) return;
            const buttons = [...event.currentTarget.querySelectorAll<HTMLElement>(actionSelector)].filter((button) => !button.hasAttribute("disabled"));
            const index = buttons.indexOf(document.activeElement as HTMLElement);
            if (index < 0) return;
            const next =
              event.key === "ArrowRight" || event.key === "ArrowDown"
                ? buttons[(index + 1) % buttons.length]
                : event.key === "ArrowLeft" || event.key === "ArrowUp"
                  ? buttons[(index - 1 + buttons.length) % buttons.length]
                  : event.key === "Home"
                    ? buttons[0]
                    : event.key === "End"
                      ? buttons[buttons.length - 1]
                      : null;
            if (!next) return;
            event.preventDefault();
            next.focus();
          }}
          {...props}
        >
          {children}
        </div>
      </Tooltip.Provider>
    </AlignmentControlContext.Provider>
  );
});

/** A boxed set of buttons, such as the horizontal aligns. */
export const AlignmentControlGroup = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function AlignmentControlGroup({ className, ...props }, ref) {
  return (
    <div
      ref={ref}
      role="group"
      className={cn("flex h-8 items-center gap-0.5 rounded-md border border-input bg-muted p-0.5 dark:bg-input/40", className)}
      {...props}
    />
  );
});

// Each icon is a guide line with two layers against it, drawn on a 16-unit grid.
const bar = (x: number, y: number, width: number, height: number) => <rect x={x} y={y} width={width} height={height} rx={1} fill="currentColor" />;
const line = (x1: number, y1: number, x2: number, y2: number) => <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" />;
const glyphs: Record<AlignmentAction, ReactNode> = {
  left: [line(2, 2, 2, 14), bar(4.5, 4, 8, 3), bar(4.5, 9, 5, 3)],
  center: [line(8, 2, 8, 14), bar(3, 4, 10, 3), bar(5, 9, 6, 3)],
  right: [line(14, 2, 14, 14), bar(3.5, 4, 8, 3), bar(6.5, 9, 5, 3)],
  top: [line(2, 2, 14, 2), bar(4, 4.5, 3, 8), bar(9, 4.5, 3, 5)],
  middle: [line(2, 8, 14, 8), bar(4, 3, 3, 10), bar(9, 5, 3, 6)],
  bottom: [line(2, 14, 14, 14), bar(4, 3.5, 3, 8), bar(9, 6.5, 3, 5)],
  "distribute-horizontal": [line(2, 2, 2, 14), line(14, 2, 14, 14), bar(6.5, 4, 3, 8)],
  "distribute-vertical": [line(2, 2, 14, 2), line(2, 14, 14, 14), bar(4, 6.5, 8, 3)],
};

/** The icon for an action, for menus or custom buttons. */
export function AlignmentIcon({ action, className }: { action: AlignmentAction; className?: string }) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden className={cn("size-4 shrink-0", className)}>
      {Array.isArray(glyphs[action]) ? (glyphs[action] as ReactNode[]).map((part, index) => <g key={index}>{part}</g>) : glyphs[action]}
    </svg>
  );
}

type ButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  action: AlignmentAction;
  /** Class for the tooltip. */
  tooltipClassName?: string;
};

/**
 * One action. It stays focusable when the selection is too small for it, and its tooltip says what it needs.
 */
export const AlignmentControlButton = forwardRef<HTMLButtonElement, ButtonProps>(function AlignmentControlButton(
  { action, tooltipClassName, className, onClick, onFocus, ...props },
  ref,
) {
  const control = useAlignmentControl();
  const minimum = minimumFor(action);
  const unavailable = control.selectionCount < minimum;
  const label = control.messages.actions[action];
  const shortcut = control.shortcuts[action];
  const button = (
    <button
      ref={ref}
      type="button"
      data-align-action={action}
      aria-label={label}
      aria-keyshortcuts={shortcut}
      aria-disabled={unavailable || undefined}
      disabled={control.disabled}
      tabIndex={control.active === action ? 0 : -1}
      onFocus={(event) => {
        onFocus?.(event);
        control.setActive(action);
      }}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) control.align(action);
      }}
      className={cn(
        "grid size-7 shrink-0 place-items-center rounded-sm text-muted-foreground outline-none transition-[color,background-color,box-shadow,transform] select-none",
        "hover:bg-background hover:text-foreground hover:shadow-xs active:scale-95 focus-visible:bg-foreground/10 focus-visible:text-foreground",
        "aria-disabled:opacity-40 aria-disabled:hover:bg-transparent aria-disabled:hover:text-muted-foreground aria-disabled:hover:shadow-none aria-disabled:active:scale-100",
        "disabled:pointer-events-none disabled:opacity-40",
        className,
      )}
      {...props}
    >
      <AlignmentIcon action={action} />
    </button>
  );
  if (control.disabled) return button;
  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={button} />
      <Tooltip.Portal container={control.rootRef}>
        <Tooltip.Positioner side="top" sideOffset={6} positionMethod="fixed" className="z-50">
          <Tooltip.Popup
            className={cn(
              "flex items-center gap-2 rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md",
              control.animated &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
              tooltipClassName,
            )}
          >
            <span>{unavailable ? `${label} · ${control.messages.needs(minimum)}` : label}</span>
            {shortcut && !unavailable && <kbd className="font-sans text-background/60">{shortcut}</kbd>}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
});

"use client";

export {
  type AlignmentAction,
  type AlignmentTarget,
  type AlignmentPosition,
  type AlignmentControlProps,
  type AlignmentControlMessages,
  useAlignmentControl,
} from "./alignment-control-state";
export { AlignmentControl, AlignmentControlGroup, AlignmentControlButton, AlignmentIcon } from "./alignment-control-toolbar";
export { AlignmentGrid, type AlignmentGridProps } from "./alignment-control-grid";
export { type AlignmentRect, type AlignmentBounds, alignRects, boundsOf, positionRect, positionOf } from "./alignment-control-geometry";

"use client";

import { type PointerEvent as ReactPointerEvent, useEffect, useRef, useState } from "react";
import { type TimelineEdge, type TimelineItem, type TimelineTrack, itemEdges, itemEnd, itemStart, moveItems, resizeClip, roundTime, sameItems, snapDelta } from "./animation-timeline-math";
import { type AnimationTimelineDetail, useIsomorphicLayoutEffect } from "./animation-timeline-state";

type Options = {
  items: TimelineItem[];
  tracks: TimelineTrack[];
  selection: string[];
  duration: number;
  currentTime: number;
  snap: boolean;
  snapInterval: number;
  pixelsPerSecond: number;
  minClipDuration: number;
  scrollerRef: { current: HTMLDivElement | null };
  namesRef: { current: HTMLDivElement | null };
  laneRef: { current: HTMLDivElement | null };
  isEditable: (item: TimelineItem) => boolean;
  setLive: (items: TimelineItem[] | null) => void;
  onSelectionChange: (ids: string[]) => void;
  onItemsChange?: (items: TimelineItem[], detail: AnimationTimelineDetail) => void;
  onItemsCommit: (items: TimelineItem[], detail: AnimationTimelineDetail) => void;
};

type Drag = {
  pointerId: number;
  id: string;
  edge?: TimelineEdge;
  ids: string[];
  shift: boolean;
  wasSelected: boolean;
  armed: boolean;
  moved: boolean;
  alt: boolean;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  startOffsetY: number;
  startTime: number;
  startItems: TimelineItem[];
  last: TimelineItem[];
  targets: number[];
  edges: number[];
  stop: () => void;
};

const touchHold = 250;
const touchSlop = 8;
const dragThreshold = 3;
const snapPixels = 6;
const edgeZone = 32;
const edgeSpeed = 10;

/** Press and drag items. Touch waits for a short hold so scrolling never moves a clip. Escape cancels. */
export function useTimelineDrag(options: Options) {
  const latest = useRef(options);
  useIsomorphicLayoutEffect(() => {
    latest.current = options;
  });
  const active = useRef<Drag | null>(null);
  const suppressClick = useRef(false);
  const [draggingIds, setDraggingIds] = useState<string[]>([]);
  const [armedId, setArmedId] = useState<string | null>(null);
  const [guide, setGuide] = useState<number | null>(null);

  const detailOf = (drag: Drag): AnimationTimelineDetail => ({ action: drag.edge ? "resize" : "move", ids: drag.ids });

  const timeAt = (clientX: number) => {
    const { laneRef, pixelsPerSecond } = latest.current;
    const left = laneRef.current?.getBoundingClientRect().left ?? 0;
    return (clientX - left) / pixelsPerSecond;
  };

  const applyPress = (drag: Drag) => {
    const { selection, onSelectionChange } = latest.current;
    if (drag.wasSelected) return;
    onSelectionChange(drag.shift ? [...selection, drag.id] : [drag.id]);
  };

  const apply = () => {
    const drag = active.current;
    if (!drag?.moved) return;
    const { laneRef, tracks, duration, snap, snapInterval, pixelsPerSecond, minClipDuration, setLive, onItemsChange } = latest.current;
    const raw = timeAt(drag.lastX) - drag.startTime;
    const found = snap && !drag.alt ? snapDelta(drag.edges.map((edge) => edge + raw), drag.targets, snapInterval, snapPixels / pixelsPerSecond) : null;
    const delta = raw + (found?.delta ?? 0);
    let next: TimelineItem[];
    if (drag.edge) {
      next = resizeClip(drag.startItems, drag.id, drag.edge, delta, minClipDuration, duration);
    } else {
      const rect = laneRef.current?.getBoundingClientRect();
      const rowHeight = rect && tracks.length ? rect.height / tracks.length : 0;
      const shift = rect && rowHeight ? Math.round((drag.lastY - rect.top - drag.startOffsetY) / rowHeight) : 0;
      next = moveItems(drag.startItems, drag.ids, delta, shift, tracks, duration);
    }
    setGuide(found ? roundTime(found.at) : null);
    if (sameItems(next, drag.last)) return;
    drag.last = next;
    setLive(next);
    onItemsChange?.(next, detailOf(drag));
  };

  const finish = (commit: boolean) => {
    const drag = active.current;
    if (!drag) return;
    active.current = null;
    drag.stop();
    setDraggingIds([]);
    setArmedId(null);
    setGuide(null);
    const { selection, setLive, onSelectionChange, onItemsChange, onItemsCommit } = latest.current;
    if (drag.moved) {
      suppressClick.current = true;
      window.setTimeout(() => {
        suppressClick.current = false;
      }, 0);
      setLive(null);
      if (commit && !sameItems(drag.last, drag.startItems)) onItemsCommit(drag.last, detailOf(drag));
      else if (!sameItems(drag.last, drag.startItems)) onItemsChange?.(drag.startItems, detailOf(drag));
      return;
    }
    if (!commit) return;
    if (!drag.armed) applyPress(drag);
    if (drag.wasSelected && drag.shift) onSelectionChange(selection.filter((id) => id !== drag.id));
    else if (drag.wasSelected && selection.length > 1) onSelectionChange([drag.id]);
  };

  const begin = (event: ReactPointerEvent<HTMLElement>, item: TimelineItem, edge?: TimelineEdge) => {
    const { items, selection, isEditable, currentTime, duration, laneRef } = latest.current;
    if (event.button !== 0 || event.ctrlKey || active.current || !isEditable(item)) return;
    event.stopPropagation();
    const wasSelected = selection.includes(item.id);
    const selected = items.filter((candidate) => selection.includes(candidate.id) && isEditable(candidate)).map((candidate) => candidate.id);
    const ids = edge ? [item.id] : wasSelected ? selected : event.shiftKey ? [...selected, item.id] : [item.id];
    const moving = items.filter((candidate) => ids.includes(candidate.id));
    const edges = edge ? [edge === "start" ? itemStart(item) : itemEnd(item)] : moving.flatMap(itemEdges);
    const others = items.filter((candidate) => !ids.includes(candidate.id)).flatMap(itemEdges);
    const element = event.currentTarget;
    const pointerId = event.pointerId;
    const holdFirst = event.pointerType === "touch" && !edge;
    let frame = 0;
    let timer = 0;

    const onMove = (next: PointerEvent) => {
      const drag = active.current;
      if (!drag || next.pointerId !== pointerId) return;
      drag.lastX = next.clientX;
      drag.lastY = next.clientY;
      drag.alt = next.altKey;
      const distance = Math.hypot(next.clientX - drag.startX, next.clientY - drag.startY);
      if (!drag.armed) {
        if (distance > touchSlop) finish(false);
        return;
      }
      if (!drag.moved) {
        if (distance < dragThreshold) return;
        drag.moved = true;
        setDraggingIds(drag.ids);
        frame = requestAnimationFrame(tick);
      }
      apply();
    };
    const tick = () => {
      const drag = active.current;
      const { scrollerRef, namesRef } = latest.current;
      const scroller = scrollerRef.current;
      if (!drag || !scroller) return;
      const rect = scroller.getBoundingClientRect();
      const left = rect.left + (namesRef.current?.offsetWidth ?? 0) + edgeZone;
      const right = rect.right - edgeZone;
      const speed = drag.lastX < left ? -edgeSpeed : drag.lastX > right ? edgeSpeed : 0;
      const before = scroller.scrollLeft;
      if (speed) scroller.scrollLeft = before + speed;
      if (scroller.scrollLeft !== before) apply();
      frame = requestAnimationFrame(tick);
    };
    const onUp = (next: PointerEvent) => void (next.pointerId === pointerId && finish(true));
    const onCancel = (next: PointerEvent) => void (next.pointerId === pointerId && finish(false));
    const onKey = (next: KeyboardEvent) => {
      if (next.key !== "Escape") return;
      next.preventDefault();
      next.stopPropagation();
      finish(false);
    };
    const onBlur = () => finish(false);
    // Once a held finger is dragging, the page must not start scrolling.
    const onTouchMove = (next: TouchEvent) => {
      if (active.current?.armed) next.preventDefault();
    };
    const listening = new AbortController();
    const { signal } = listening;
    window.addEventListener("pointermove", onMove, { signal });
    window.addEventListener("pointerup", onUp, { signal });
    window.addEventListener("pointercancel", onCancel, { signal });
    window.addEventListener("keydown", onKey, { signal, capture: true });
    window.addEventListener("blur", onBlur, { signal });
    if (holdFirst) window.addEventListener("touchmove", onTouchMove, { signal, passive: false });

    const laneTop = laneRef.current?.getBoundingClientRect().top ?? 0;
    const drag: Drag = {
      pointerId,
      id: item.id,
      edge,
      ids,
      shift: event.shiftKey,
      wasSelected,
      armed: !holdFirst,
      moved: false,
      alt: event.altKey,
      startX: event.clientX,
      startY: event.clientY,
      lastX: event.clientX,
      lastY: event.clientY,
      startOffsetY: event.clientY - laneTop,
      startTime: timeAt(event.clientX),
      startItems: items,
      last: items,
      targets: [0, duration, currentTime, ...others],
      edges,
      stop: () => {
        cancelAnimationFrame(frame);
        window.clearTimeout(timer);
        listening.abort();
      },
    };
    active.current = drag;
    if (holdFirst) {
      timer = window.setTimeout(() => {
        drag.armed = true;
        setArmedId(item.id);
        applyPress(drag);
      }, touchHold);
      return;
    }
    applyPress(drag);
    try {
      element.setPointerCapture?.(pointerId);
    } catch {
      // The pointer may already have ended.
    }
  };

  useEffect(() => () => active.current?.stop(), []);

  return { begin, cancel: () => finish(false), draggingIds, armedId, guide, clickSuppressed: () => suppressClick.current };
}

"use client";

import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuTarget } from "@/components/ui/context-menu";
import { type TimelineEdge, type TimelineItem, itemEnd, itemStart } from "./animation-timeline-math";
import { useAnimationTimeline } from "./animation-timeline-state";
import { cn } from "@/lib/utils";

const minLabelWidth = 44;
const minDurationWidth = 96;

function EdgeHandle({ item, edge }: { item: TimelineItem; edge: TimelineEdge }) {
  const { beginDrag } = useAnimationTimeline();
  return (
    <span
      aria-hidden
      data-slot="animation-timeline-edge"
      data-edge={edge}
      // On touch, only the selected clip's edges take a press, so a tap on the clip never resizes it.
      // There they are 44px targets centered on the clip's edge.
      className={cn(
        "absolute inset-y-0 z-10 w-2 cursor-ew-resize touch-none after:absolute after:inset-y-1.5 after:w-0.5 after:rounded-full after:bg-current after:opacity-0 group-hover/item:after:opacity-50 group-data-selected/item:after:opacity-70 pointer-coarse:inset-y-auto pointer-coarse:top-1/2 pointer-coarse:h-11 pointer-coarse:w-11 pointer-coarse:-translate-y-1/2 pointer-coarse:after:inset-y-3.5 pointer-coarse:not-group-data-selected/item:pointer-events-none",
        edge === "start" ? "left-0 after:left-0.5 pointer-coarse:-left-5 pointer-coarse:after:left-[1.375rem]" : "right-0 after:right-0.5 pointer-coarse:-right-5 pointer-coarse:after:right-[1.375rem]",
      )}
      onPointerDown={(event) => beginDrag(event, item, edge)}
    />
  );
}

/** One clip or keyframe, placed by its time and track. */
export function AnimationTimelineItem({ item }: { item: TimelineItem }) {
  const { tracks, selection, pixelsPerSecond, draggingIds, armedId, container, disabled, messages, instructionsId, formatTime, isEditable, menuIds, beginDrag, cancelDrag, selectForMenu, onItemKeyDown, onDuplicate, onDelete } = useAnimationTimeline();
  const index = tracks.findIndex((track) => track.id === item.trackId);
  if (index < 0) return null;
  const track = tracks[index];
  const editable = isEditable(item);
  const selected = selection.includes(item.id);
  const clip = item.kind === "clip";
  const name = item.label ?? (clip ? messages.untitledClip : messages.untitledKeyframe);
  const left = itemStart(item) * pixelsPerSecond;
  const rowTop = (index / tracks.length) * 100;
  const rowHeight = 100 / tracks.length;
  const label = clip ? messages.clip(name, track.label, formatTime(itemStart(item)), formatTime(itemEnd(item))) : messages.keyframe(name, track.label, formatTime(itemStart(item)));
  const width = clip ? Math.max(item.duration * pixelsPerSecond, 8) : 0;
  const position = clip
    ? { left, width, top: `calc(${rowTop}% + 0.25rem)`, height: `calc(${rowHeight}% - 0.5rem)` }
    : { left: `clamp(0.75rem, ${left}px, calc(100% - 0.75rem))`, top: `${rowTop + rowHeight / 2}%` };

  return (
    <ContextMenu
      disabled={disabled || !editable || (!onDuplicate && !onDelete)}
      onOpenChange={(open) => {
        if (open) cancelDrag();
      }}
    >
      <ContextMenuTarget
        role="button"
        tabIndex={editable ? 0 : -1}
        aria-label={label}
        aria-pressed={selected}
        aria-disabled={!editable || undefined}
        aria-describedby={editable ? instructionsId : undefined}
        data-timeline-item={item.kind}
        data-selected={selected ? "" : undefined}
        data-dragging={draggingIds.includes(item.id) ? "" : undefined}
        data-armed={armedId === item.id ? "" : undefined}
        className={cn(
          "group/item absolute touch-pan-x touch-pan-y select-none focus-visible:not-data-pointer-focus:ring-2 focus-visible:not-data-pointer-focus:ring-ring [-webkit-touch-callout:none] data-dragging:z-[5] data-selected:z-[4]",
          editable ? "cursor-grab data-dragging:cursor-grabbing" : "cursor-not-allowed",
          track.hidden && "opacity-40",
          !editable && !track.hidden && "opacity-60",
          clip
            ? "flex items-center justify-between gap-2 rounded-[5px] bg-foreground/25 px-2 text-xs text-foreground transition-colors hover:bg-foreground/30 data-armed:ring-2 data-armed:ring-primary data-selected:bg-primary data-selected:text-primary-foreground hover:data-selected:bg-primary motion-reduce:transition-none dark:bg-foreground/85 dark:text-background dark:hover:bg-foreground dark:data-selected:bg-primary dark:data-selected:text-primary-foreground dark:hover:data-selected:bg-primary"
            : "grid size-6 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-sm pointer-coarse:size-11",
        )}
        style={position}
        // A click selects without the keyboard focus ring; the ring returns when focus next arrives by keyboard.
        onPointerDownCapture={(event) => {
          event.currentTarget.dataset.pointerFocus = "";
        }}
        onBlur={(event) => {
          delete event.currentTarget.dataset.pointerFocus;
        }}
        onPointerDown={(event) => beginDrag(event, item)}
        onKeyDown={(event) => onItemKeyDown(event, item)}
        onContextMenuCapture={() => selectForMenu(item)}
      >
        {clip ? (
          <>
            {width >= minLabelWidth && <span className="pointer-events-none min-w-0 truncate">{name}</span>}
            {width >= minDurationWidth && <span className="pointer-events-none shrink-0 font-mono text-[0.6875rem] tabular-nums opacity-80">{Number(item.duration.toFixed(2))}s</span>}
            {editable && <EdgeHandle item={item} edge="start" />}
            {editable && <EdgeHandle item={item} edge="end" />}
          </>
        ) : (
          <span aria-hidden className="size-2.5 rotate-45 rounded-[2px] bg-foreground/70 transition-transform group-hover/item:scale-125 group-data-armed/item:scale-125 group-data-selected/item:bg-primary group-data-selected/item:ring-2 group-data-selected/item:ring-primary/30 motion-reduce:transition-none" />
        )}
      </ContextMenuTarget>
      <ContextMenuContent container={container} positionMethod={container ? "fixed" : undefined}>
        {onDuplicate && <ContextMenuItem onClick={() => onDuplicate(menuIds(item))}>{messages.duplicate}</ContextMenuItem>}
        {onDelete && (
          <ContextMenuItem variant="destructive" onClick={() => onDelete(menuIds(item))}>
            {messages.delete}
          </ContextMenuItem>
        )}
      </ContextMenuContent>
    </ContextMenu>
  );
}

export type TimelineTrack = { id: string; label: string; hidden?: boolean; locked?: boolean };
export type TimelineClip = { id: string; kind: "clip"; trackId: string; start: number; duration: number; label?: string };
export type TimelineKeyframe = { id: string; kind: "keyframe"; trackId: string; time: number; label?: string };
export type TimelineItem = TimelineClip | TimelineKeyframe;
export type TimelineEdge = "start" | "end";

export const defaultPixelsPerSecond = 80;

const rulerSteps = [0.05, 0.1, 0.25, 0.5, 1, 2, 5, 10, 15, 30, 60, 120, 300, 600];
const smallestLabelGap = 72;
const smallestTickGap = 10;

const clamp = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value));
export const roundTime = (time: number) => Math.round(time * 100) / 100;
export const itemStart = (item: TimelineItem) => (item.kind === "clip" ? item.start : item.time);
export const itemEnd = (item: TimelineItem) => (item.kind === "clip" ? item.start + item.duration : item.time);
export const itemEdges = (item: TimelineItem) => (item.kind === "clip" ? [item.start, item.start + item.duration] : [item.time]);

/** Labelled marks far enough apart to read, and the smaller ticks between them. */
export function rulerScale(pixelsPerSecond: number) {
  const major = rulerSteps.find((step) => step * pixelsPerSecond >= smallestLabelGap) ?? rulerSteps[rulerSteps.length - 1];
  const divisions = [5, 2].find((count) => (major * pixelsPerSecond) / count >= smallestTickGap) ?? 1;
  return { major, minor: major / divisions };
}

export function rulerMarks(duration: number, major: number) {
  const count = Math.floor(duration / major + 1e-6);
  return Array.from({ length: count + 1 }, (_, index) => roundTime(index * major));
}

export function formatRulerTime(time: number, major: number) {
  if (time < 60 && major < 60) return `${Number(time.toFixed(2))}s`;
  const minutes = Math.floor(time / 60);
  return `${minutes}:${String(Math.round(time - minutes * 60)).padStart(2, "0")}`;
}

/** The smallest shift that puts one candidate on a target or a ruler tick, if any is close enough. */
export function snapDelta(candidates: number[], targets: number[], interval: number, threshold: number) {
  let best: { delta: number; at: number } | null = null;
  const consider = (candidate: number, at: number) => {
    const delta = at - candidate;
    if (Math.abs(delta) <= threshold && (!best || Math.abs(delta) < Math.abs(best.delta))) best = { delta, at };
  };
  for (const candidate of candidates) {
    for (const target of targets) consider(candidate, target);
    if (interval > 0) consider(candidate, Math.round(candidate / interval) * interval);
  }
  return best as { delta: number; at: number } | null;
}

/** Moves items together in time and across tracks. The group keeps its shape at the limits. */
export function moveItems(items: TimelineItem[], ids: string[], delta: number, trackShift: number, tracks: TimelineTrack[], duration: number) {
  const moving = items.filter((item) => ids.includes(item.id));
  if (!moving.length) return items;
  const earliest = Math.min(...moving.map(itemStart));
  const latest = Math.max(...moving.map(itemEnd));
  const applied = clamp(delta, -earliest, duration - latest);
  const position = new Map(tracks.map((track, index) => [track.id, index]));
  const destination = (item: TimelineItem) => tracks[(position.get(item.trackId) ?? -1) + trackShift];
  const shift = trackShift !== 0 && moving.every((item) => destination(item) && !destination(item).locked);
  return items.map((item) => {
    if (!ids.includes(item.id)) return item;
    const trackId = shift ? destination(item).id : item.trackId;
    return item.kind === "clip" ? { ...item, trackId, start: roundTime(item.start + applied) } : { ...item, trackId, time: roundTime(item.time + applied) };
  });
}

/** Moves one edge of a clip, keeping the other edge where it is. */
export function resizeClip(items: TimelineItem[], id: string, edge: TimelineEdge, delta: number, minimum: number, duration: number) {
  return items.map((item) => {
    if (item.id !== id || item.kind !== "clip") return item;
    const end = item.start + item.duration;
    if (edge === "start") {
      const start = roundTime(clamp(item.start + delta, 0, end - minimum));
      return { ...item, start, duration: roundTime(end - start) };
    }
    return { ...item, duration: roundTime(clamp(item.duration + delta, minimum, duration - item.start)) };
  });
}

export function sameItems(a: TimelineItem[], b: TimelineItem[]) {
  return a.length === b.length && a.every((item, index) => {
    const other = b[index];
    return item.id === other.id && item.trackId === other.trackId && itemStart(item) === itemStart(other) && itemEnd(item) === itemEnd(other);
  });
}

"use client";

import { type KeyboardEvent, forwardRef, useEffect, useId, useRef, useState } from "react";
import { formatPlaybackTime } from "@/components/ui/playback-controls";
import { useTimelineDrag } from "./animation-timeline-drag";
import { type TimelineItem, defaultPixelsPerSecond, moveItems, resizeClip, rulerScale, sameItems } from "./animation-timeline-math";
import { AnimationTimelineBody } from "./animation-timeline-tracks";
import { AnimationTimelineToolbar } from "./animation-timeline-toolbar";
import { type AnimationTimelineDetail, type AnimationTimelineProps, AnimationTimelineContext, defaultMessages, defaultZoomLevels } from "./animation-timeline-state";
import { useTimelineScrub, useTimelineZoom } from "./animation-timeline-view";
import { cn } from "@/lib/utils";

/** Arranges clips and keyframes on tracks over time. Your app owns the data and runs playback. */
export const AnimationTimeline = forwardRef<HTMLDivElement, AnimationTimelineProps>(function AnimationTimeline(
  {
    label,
    tracks,
    items,
    duration,
    selection,
    onSelectionChange,
    onItemsCommit,
    onItemsChange,
    currentTime,
    onSeekCommit,
    onSeek,
    playing,
    onPlayingChange,
    loop,
    onLoopChange,
    onTrackHiddenChange,
    onTrackLockedChange,
    onDuplicate,
    onDelete,
    step = 0.1,
    largeStep = 1,
    minClipDuration = 0.1,
    snap = true,
    pixelsPerSecond: basePixels = defaultPixelsPerSecond,
    defaultZoom = "fit",
    zoomLevels = defaultZoomLevels,
    maxZoom = 800,
    formatTime = formatPlaybackTime,
    container,
    disabled = false,
    messages: messageOverrides,
    className,
    children,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const instructionsId = useId();
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const namesRef = useRef<HTMLDivElement | null>(null);
  const laneRef = useRef<HTMLDivElement | null>(null);
  const [liveItems, setLiveItems] = useState<TimelineItem[] | null>(null);
  const [liveTime, setLiveTime] = useState<number | null>(null);
  const { zoom, pixelsPerSecond, setZoom } = useTimelineZoom({ initial: defaultZoom, max: maxZoom, duration, basePixels, hasTracks: tracks.length > 0, scrollerRef, namesRef, laneRef });
  const { major, minor } = rulerScale(pixelsPerSecond);
  const shownItems = liveItems ?? items;
  const time = liveTime ?? currentTime;

  const trackOf = (item: TimelineItem) => tracks.find((track) => track.id === item.trackId);
  const isEditable = (item: TimelineItem) => !disabled && !trackOf(item)?.locked;
  const editableIds = (ids: string[]) => items.filter((item) => ids.includes(item.id) && isEditable(item)).map((item) => item.id);
  const menuIds = (item: TimelineItem) => (selection.includes(item.id) ? editableIds(selection) : [item.id]);

  const drag = useTimelineDrag({ items, tracks, selection, duration, currentTime, snap, snapInterval: minor, pixelsPerSecond, minClipDuration, scrollerRef, namesRef, laneRef, isEditable, setLive: setLiveItems, onSelectionChange, onItemsChange, onItemsCommit });
  const scrub = useTimelineScrub({ time: currentTime, duration, items, snap, snapInterval: minor, step, largeStep, pixelsPerSecond, disabled, laneRef, setLive: setLiveTime, onSeek, onSeekCommit });

  // Keeps the playhead in view while playing.
  useEffect(() => {
    const scroller = scrollerRef.current;
    if (!playing || !scroller) return;
    const names = namesRef.current?.offsetWidth ?? 0;
    const x = names + time * pixelsPerSecond;
    if (x < scroller.scrollLeft + names || x > scroller.scrollLeft + scroller.clientWidth - 12) scroller.scrollLeft = x - names - 12;
  }, [playing, time, pixelsPerSecond]);

  const edit = (next: TimelineItem[], detail: AnimationTimelineDetail) => {
    if (sameItems(next, items)) return;
    onItemsChange?.(next, detail);
    onItemsCommit(next, detail);
  };

  const onItemKeyDown = (event: KeyboardEvent<HTMLElement>, item: TimelineItem) => {
    if (!isEditable(item) || event.defaultPrevented) return;
    const selected = selection.includes(item.id);
    const ids = selected ? editableIds(selection) : [item.id];
    const amount = event.shiftKey && !event.altKey ? largeStep : step;
    const across = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
    const down = event.key === "ArrowDown" ? 1 : event.key === "ArrowUp" ? -1 : 0;
    const command = event.metaKey || event.ctrlKey;
    const handled = () => {
      event.preventDefault();
      event.stopPropagation();
      if (!selected) onSelectionChange([item.id]);
    };
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      if (event.shiftKey) onSelectionChange(selected ? selection.filter((id) => id !== item.id) : [...selection, item.id]);
      else onSelectionChange([item.id]);
    } else if (event.key === "Escape" && selection.length) {
      event.preventDefault();
      onSelectionChange([]);
    } else if ((event.key === "Delete" || event.key === "Backspace") && onDelete) {
      handled();
      onDelete(ids);
    } else if (command && event.key.toLowerCase() === "d" && onDuplicate) {
      handled();
      onDuplicate(ids);
    } else if (across && event.altKey) {
      if (item.kind !== "clip") return;
      handled();
      edit(resizeClip(items, item.id, event.shiftKey ? "start" : "end", across * step, minClipDuration, duration), { action: "resize", ids: [item.id] });
    } else if ((across || down) && !command) {
      handled();
      edit(moveItems(items, ids, across * amount, down, tracks, duration), { action: "move", ids });
    }
  };

  return (
    <AnimationTimelineContext.Provider
      value={{
        label,
        tracks,
        items: shownItems,
        duration,
        selection,
        playing,
        onPlayingChange,
        loop,
        onLoopChange,
        onTrackHiddenChange,
        onTrackLockedChange,
        onDuplicate,
        onDelete,
        container,
        time,
        disabled,
        step,
        largeStep,
        zoom,
        zoomLevels,
        pixelsPerSecond,
        major,
        minor,
        guide: drag.guide,
        draggingIds: drag.draggingIds,
        armedId: drag.armedId,
        scrubbing: scrub.scrubbing,
        messages,
        instructionsId,
        formatTime,
        scrollerRef,
        namesRef,
        laneRef,
        setZoom,
        seek: (next) => onSeek?.(next),
        commitSeek: onSeekCommit,
        isEditable,
        menuIds,
        beginDrag: drag.begin,
        cancelDrag: drag.cancel,
        selectForMenu: (item) => {
          if (isEditable(item) && !selection.includes(item.id)) onSelectionChange([item.id]);
        },
        onItemKeyDown,
        onLaneClick: (target, shift) => {
          if (!disabled && !shift && !drag.clickSuppressed() && !target.closest("[data-timeline-item]") && selection.length) onSelectionChange([]);
        },
        rulerHandlers: scrub.handlers,
      }}
    >
      <div ref={ref} role="group" aria-label={label} data-slot="animation-timeline" data-disabled={disabled ? "" : undefined} className={cn("@container/timeline grid w-full min-w-0 content-start gap-2 text-sm", className)} {...props}>
        {children ?? (
          <>
            <AnimationTimelineToolbar />
            <AnimationTimelineBody />
          </>
        )}
      </div>
    </AnimationTimelineContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, createContext, useContext, useEffect, useLayoutEffect } from "react";
import type { TimelineEdge, TimelineItem, TimelineTrack } from "./animation-timeline-math";

export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Replaceable text, for example to translate. */
export type AnimationTimelineMessages = {
  playback: string;
  zoom: string;
  fit: string;
  playhead: string;
  hide: string;
  show: string;
  lock: string;
  unlock: string;
  trackOptions: (track: string) => string;
  duplicate: string;
  delete: string;
  empty: string;
  /** Read with every item. */
  instructions: string;
  clip: (label: string, track: string, start: string, end: string) => string;
  keyframe: (label: string, track: string, time: string) => string;
  untitledClip: string;
  untitledKeyframe: string;
};

export const defaultMessages: AnimationTimelineMessages = {
  playback: "Timeline playback",
  zoom: "Zoom",
  fit: "Fit",
  playhead: "Playhead",
  hide: "Hide",
  show: "Show",
  lock: "Lock",
  unlock: "Unlock",
  trackOptions: (track) => `${track} options`,
  duplicate: "Duplicate",
  delete: "Delete",
  empty: "Nothing is animated yet.",
  instructions: "Arrow keys move. Shift moves further. Alt with Left or Right changes the end; add Shift to change the start.",
  clip: (label, track, start, end) => `${label}, ${track}, from ${start} to ${end}`,
  keyframe: (label, track, time) => `${label}, ${track}, at ${time}`,
  untitledClip: "Clip",
  untitledKeyframe: "Keyframe",
};

/** What changed, and which items. */
export type AnimationTimelineDetail = { action: "move" | "resize"; ids: string[] };

/** Fit shows the whole timeline; a number zooms in from it, in percent. */
export type AnimationTimelineZoomValue = "fit" | number;

export const defaultZoomLevels = [150, 200, 300, 400];

export type AnimationTimelineProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> & {
  /** Names the timeline for screen readers. */
  label: string;
  /** Rows from top to bottom. Your app owns them. */
  tracks: TimelineTrack[];
  /** Clips and keyframes. Your app owns them. */
  items: TimelineItem[];
  /** The length in seconds. */
  duration: number;
  /** Selected item ids. Your app owns them. */
  selection: string[];
  onSelectionChange: (ids: string[]) => void;
  /** Called once per finished drag or key press, for saving and undo. */
  onItemsCommit: (items: TimelineItem[], detail: AnimationTimelineDetail) => void;
  /** Called with live items while dragging, and the starting items when a drag is cancelled. */
  onItemsChange?: (items: TimelineItem[], detail: AnimationTimelineDetail) => void;
  /** The playhead in seconds. Your app owns it. */
  currentTime: number;
  /** Called once per finished ruler drag, key press or button. */
  onSeekCommit: (time: number) => void;
  /** Called with live positions, and the starting position when a drag is cancelled. */
  onSeek?: (time: number) => void;
  /** Whether playback is running. Your app runs it. */
  playing: boolean;
  onPlayingChange: (playing: boolean) => void;
  /** Passing it shows the Loop button. */
  loop?: boolean;
  onLoopChange?: (loop: boolean) => void;
  /** Passing it shows Hide and Show for each track. */
  onTrackHiddenChange?: (trackId: string, hidden: boolean) => void;
  /** Passing it shows Lock and Unlock for each track. */
  onTrackLockedChange?: (trackId: string, locked: boolean) => void;
  /** Passing it adds Duplicate to the item menu. Your app creates the copies. */
  onDuplicate?: (ids: string[]) => void;
  /** Passing it adds Delete to the item menu. Your app removes the items. */
  onDelete?: (ids: string[]) => void;
  /** Seconds moved by arrow keys. */
  step?: number;
  /** Seconds moved with Shift. */
  largeStep?: number;
  /** The shortest a clip can be, in seconds. */
  minClipDuration?: number;
  /** Snap to the playhead, item edges and ruler ticks. Hold Alt while dragging to turn it off. */
  snap?: boolean;
  /** Width of one second until the available space is known. */
  pixelsPerSecond?: number;
  /** The starting zoom. Fit shows the whole timeline without sideways scrolling. */
  defaultZoom?: AnimationTimelineZoomValue;
  /** Percent choices in the Zoom menu, after Fit. */
  zoomLevels?: number[];
  /** The furthest Ctrl or Cmd + scroll can zoom in, in percent of Fit. */
  maxZoom?: number;
  formatTime?: (seconds: number) => string;
  /** Where menus and tooltips are portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  disabled?: boolean;
  messages?: Partial<AnimationTimelineMessages>;
};

export type AnimationTimelineContextValue = Pick<AnimationTimelineProps, "label" | "tracks" | "duration" | "selection" | "playing" | "onPlayingChange" | "loop" | "onLoopChange" | "onTrackHiddenChange" | "onTrackLockedChange" | "onDuplicate" | "onDelete" | "container"> & {
  items: TimelineItem[];
  time: number;
  disabled: boolean;
  step: number;
  largeStep: number;
  zoom: AnimationTimelineZoomValue;
  zoomLevels: number[];
  pixelsPerSecond: number;
  major: number;
  minor: number;
  guide: number | null;
  draggingIds: string[];
  armedId: string | null;
  scrubbing: boolean;
  messages: AnimationTimelineMessages;
  instructionsId: string;
  formatTime: (seconds: number) => string;
  scrollerRef: { current: HTMLDivElement | null };
  namesRef: { current: HTMLDivElement | null };
  laneRef: { current: HTMLDivElement | null };
  setZoom: (zoom: AnimationTimelineZoomValue) => void;
  seek: (time: number) => void;
  commitSeek: (time: number) => void;
  isEditable: (item: TimelineItem) => boolean;
  menuIds: (item: TimelineItem) => string[];
  beginDrag: (event: PointerEvent<HTMLElement>, item: TimelineItem, edge?: TimelineEdge) => void;
  cancelDrag: () => void;
  selectForMenu: (item: TimelineItem) => void;
  onItemKeyDown: (event: KeyboardEvent<HTMLElement>, item: TimelineItem) => void;
  onLaneClick: (target: Element, shift: boolean) => void;
  rulerHandlers: { onPointerDown: (event: PointerEvent<HTMLElement>) => void; onKeyDown: (event: KeyboardEvent<HTMLElement>) => void };
};

export const AnimationTimelineContext = createContext<AnimationTimelineContextValue | null>(null);

/** The live items, time and scale of the nearest AnimationTimeline, for custom parts. */
export function useAnimationTimeline() {
  const context = useContext(AnimationTimelineContext);
  if (!context) throw new Error("Animation Timeline parts must be rendered inside <AnimationTimeline>.");
  return context;
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { InspectorField, InspectorFieldLabel, InspectorFieldSelect } from "@/components/ui/inspector-field";
import { PlaybackControls, PlaybackControlsRow, PlaybackLoopButton, PlaybackPlayButton, PlaybackRestartButton } from "@/components/ui/playback-controls";
import { useAnimationTimeline } from "./animation-timeline-state";
import { cn } from "@/lib/utils";

const quietButton = "size-9 rounded-md bg-foreground/8 text-foreground hover:bg-foreground/15 hover:text-foreground focus-visible:bg-foreground/15 focus-visible:text-foreground focus-visible:ring-0 pointer-coarse:size-11";

/** Fit, or a percent. Ctrl or Cmd + scroll can reach values between the choices. */
export const AnimationTimelineZoom = forwardRef<HTMLDivElement, Omit<ComponentPropsWithoutRef<"div">, "children">>(function AnimationTimelineZoom({ className, ...props }, ref) {
  const { zoom, zoomLevels, container, disabled, messages, setZoom } = useAnimationTimeline();
  const value = String(zoom);
  const options = [{ value: "fit", label: messages.fit, disabled: false }, ...zoomLevels.map((level) => ({ value: String(level), label: `${level}%`, disabled: false }))];
  if (!options.some((option) => option.value === value)) options.push({ value, label: `${zoom}%`, disabled: true });
  return (
    <InspectorField
      ref={ref}
      data-slot="animation-timeline-zoom"
      label={messages.zoom}
      align="start"
      disabled={disabled}
      className={cn("block w-24 shrink-0 [--uicoolkit-field-bg:color-mix(in_oklab,var(--foreground)_8%,transparent)] [--uicoolkit-field-border:transparent] [--uicoolkit-field-height:2.25rem] [--uicoolkit-field-shadow:none] pointer-coarse:[--uicoolkit-field-height:2.75rem]", className)}
      {...props}
    >
      <InspectorFieldLabel className="sr-only" />
      <InspectorFieldSelect value={value} options={options} container={container} positionMethod={container ? "fixed" : undefined} onCommit={(next) => setZoom(next === "fit" ? "fit" : Number(next))} />
    </InspectorField>
  );
});

/** The timeline's name, playback buttons and Zoom. */
export const AnimationTimelineToolbar = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function AnimationTimelineToolbar({ className, ...props }, ref) {
  const { label, playing, onPlayingChange, time, duration, loop, onLoopChange, formatTime, container, disabled, messages, commitSeek, seek } = useAnimationTimeline();
  return (
    <div ref={ref} data-slot="animation-timeline-toolbar" className={cn("flex min-w-0 items-center justify-end gap-1", className)} {...props}>
      <span aria-hidden className="mr-auto min-w-0 truncate font-medium text-foreground @max-md/timeline:hidden">
        {label}
      </span>
      <PlaybackControls label={messages.playback} playing={playing} onPlayingChange={onPlayingChange} currentTime={time} duration={duration} onSeek={seek} onSeekCommit={commitSeek} loop={loop} onLoopChange={onLoopChange} formatTime={formatTime} container={container} disabled={disabled} className="w-auto shrink-0 [container-type:normal]!">
        <PlaybackControlsRow className="flex-nowrap">
          <PlaybackPlayButton className={quietButton} />
          <PlaybackRestartButton className={quietButton} />
          <PlaybackLoopButton className={cn(quietButton, "aria-pressed:bg-foreground/20")} />
        </PlaybackControlsRow>
      </PlaybackControls>
      <AnimationTimelineZoom />
    </div>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { ContextMenu, ContextMenuButton, ContextMenuContent, ContextMenuItem, ContextMenuTarget } from "@/components/ui/context-menu";
import { AnimationTimelineItem } from "./animation-timeline-items";
import { type TimelineTrack, formatRulerTime, rulerMarks } from "./animation-timeline-math";
import { useAnimationTimeline } from "./animation-timeline-state";
import { cn } from "@/lib/utils";

const line = (path: string) => (
  <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
    <path d={path} />
  </svg>
);
const icons = {
  shown: line("M1.5 8S4 3.5 8 3.5 14.5 8 14.5 8 12 12.5 8 12.5 1.5 8 1.5 8ZM8 10a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"),
  hidden: line("M2 2l12 12M6.5 3.7A6 6 0 0 1 8 3.5c4 0 6.5 4.5 6.5 4.5a11 11 0 0 1-1.9 2.4M4.2 4.9A11 11 0 0 0 1.5 8S4 12.5 8 12.5a6 6 0 0 0 2.7-.7"),
  locked: line("M4 7.5h8v6H4ZM5.5 7.5V5a2.5 2.5 0 0 1 5 0v2.5"),
  unlocked: line("M4 7.5h8v6H4ZM5.5 7.5V5a2.5 2.5 0 0 1 4.8-1"),
};

function TrackButton({ label, icon, pressed, onClick }: { label: string; icon: ReactNode; pressed: boolean; onClick: () => void }) {
  const { disabled } = useAnimationTimeline();
  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={pressed}
      title={label}
      disabled={disabled}
      // Quiet until the row is hovered or the button is on, so the column stays clean.
      className="inline-flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground opacity-0 outline-none transition-[color,background-color,opacity] group-hover/track:opacity-100 hover:bg-foreground/10 hover:text-foreground focus-visible:bg-foreground/10 focus-visible:text-foreground focus-visible:opacity-100 disabled:pointer-events-none aria-pressed:text-foreground aria-pressed:opacity-100 motion-reduce:transition-none [&_svg]:size-3.5"
      onClick={onClick}
    >
      {icon}
    </button>
  );
}

function TrackHeader({ track }: { track: TimelineTrack }) {
  const { onTrackHiddenChange, onTrackLockedChange, container, disabled, messages } = useAnimationTimeline();
  const hideName = `${track.hidden ? messages.show : messages.hide} ${track.label}`;
  const lockName = `${track.locked ? messages.unlock : messages.lock} ${track.label}`;
  const hasActions = onTrackHiddenChange || onTrackLockedChange;
  return (
    <ContextMenu disabled={disabled || !hasActions}>
      <ContextMenuTarget data-slot="animation-timeline-track" data-hidden={track.hidden ? "" : undefined} data-locked={track.locked ? "" : undefined} className="group/track flex h-(--timeline-row) min-w-0 items-center gap-0.5 pr-1">
        <span className={cn("min-w-0 flex-1 truncate text-foreground/80", track.hidden && "line-through opacity-60")}>{track.label}</span>
        <span className="flex shrink-0 items-center @max-md/timeline:hidden">
          {onTrackHiddenChange && <TrackButton label={hideName} icon={track.hidden ? icons.hidden : icons.shown} pressed={!!track.hidden} onClick={() => onTrackHiddenChange(track.id, !track.hidden)} />}
          {onTrackLockedChange && <TrackButton label={lockName} icon={track.locked ? icons.locked : icons.unlocked} pressed={!!track.locked} onClick={() => onTrackLockedChange(track.id, !track.locked)} />}
        </span>
        {hasActions && <ContextMenuButton aria-label={messages.trackOptions(track.label)} className="hidden size-7 pointer-coarse:size-11 @max-md/timeline:inline-flex" />}
      </ContextMenuTarget>
      <ContextMenuContent container={container} positionMethod={container ? "fixed" : undefined}>
        {onTrackHiddenChange && <ContextMenuItem onClick={() => onTrackHiddenChange(track.id, !track.hidden)}>{track.hidden ? messages.show : messages.hide}</ContextMenuItem>}
        {onTrackLockedChange && <ContextMenuItem onClick={() => onTrackLockedChange(track.id, !track.locked)}>{track.locked ? messages.unlock : messages.lock}</ContextMenuItem>}
      </ContextMenuContent>
    </ContextMenu>
  );
}

const badgeHalf = "1.5rem";

/** The time scale. Click or drag it to move the playhead. */
export function AnimationTimelineRuler({ className }: { className?: string }) {
  const { time, duration, pixelsPerSecond, major, minor, disabled, scrubbing, messages, formatTime, rulerHandlers } = useAnimationTimeline();
  const width = duration * pixelsPerSecond;
  return (
    <div
      role="slider"
      tabIndex={disabled ? -1 : 0}
      aria-label={messages.playhead}
      aria-orientation="horizontal"
      aria-valuemin={0}
      aria-valuemax={duration}
      aria-valuenow={time}
      aria-valuetext={formatTime(time)}
      aria-disabled={disabled || undefined}
      data-slot="animation-timeline-ruler"
      data-scrubbing={scrubbing ? "" : undefined}
      className={cn("group/ruler relative h-full shrink-0 cursor-ew-resize touch-none overflow-hidden outline-none select-none aria-disabled:cursor-default", className)}
      style={{ width, backgroundImage: "linear-gradient(to right, color-mix(in oklab, var(--foreground) 30%, transparent) 1px, transparent 1px)", backgroundSize: `${minor * pixelsPerSecond}px 0.375rem`, backgroundPosition: "0 55%", backgroundRepeat: "repeat-x" }}
      {...rulerHandlers}
    >
      {rulerMarks(duration, major).filter((mark) => width - mark * pixelsPerSecond >= 28).map((mark) => (
        <span key={mark} aria-hidden className="absolute inset-y-1.5 border-l border-foreground/45 bg-background pl-1 font-mono text-[0.625rem] leading-none whitespace-nowrap text-foreground/75 tabular-nums" style={{ left: mark * pixelsPerSecond }}>
          {formatRulerTime(mark, major)}
        </span>
      ))}
      {/* Joins the time label to the line running through the tracks. */}
      <span aria-hidden data-slot="animation-timeline-playhead-stem" className="absolute top-4 bottom-0 w-0.5 bg-primary" style={{ left: `clamp(0px, ${time * pixelsPerSecond}px, calc(100% - 2px))` }} />
      <span
        aria-hidden
        data-slot="animation-timeline-playhead-head"
        className="absolute top-1 z-10 w-12 -translate-x-1/2 rounded-[5px] bg-primary py-0.5 text-center font-mono text-[0.6875rem] leading-4 text-primary-foreground tabular-nums group-focus-visible/ruler:ring-2 group-focus-visible/ruler:ring-ring"
        style={{ left: `clamp(${badgeHalf}, ${time * pixelsPerSecond}px, calc(100% - ${badgeHalf}))` }}
      >
        {Number(time.toFixed(2)).toFixed(2)}
      </span>
    </div>
  );
}

/** The ruler, track names, rows, items and playhead. It scrolls when zoomed in, while names and the ruler stay in place. */
export const AnimationTimelineBody = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function AnimationTimelineBody({ className, ...props }, ref) {
  const { tracks, items, duration, time, pixelsPerSecond, guide, messages, instructionsId, scrollerRef, namesRef, laneRef, onLaneClick } = useAnimationTimeline();
  const width = duration * pixelsPerSecond;
  if (!tracks.length) {
    return (
      <div ref={ref} data-slot="animation-timeline-empty" className={cn("flex flex-col items-center justify-center gap-2.5 px-4 py-10 text-center text-sm text-muted-foreground", className)} {...props}>
        <span aria-hidden className="grid size-10 place-items-center rounded-full bg-muted [&_svg]:size-5">
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round">
            <path d="M3 6h8M7 10h10M3 14h6" />
          </svg>
        </span>
        <p className="max-w-52 text-balance">{messages.empty}</p>
      </div>
    );
  }
  return (
    <div
      ref={(node) => {
        scrollerRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-slot="animation-timeline-scroller"
      className={cn("relative max-h-80 overflow-auto overscroll-x-contain [--timeline-names:9rem] [--timeline-row:2.25rem] pointer-coarse:[--timeline-row:2.75rem] @max-md/timeline:[--timeline-names:6.5rem]", className)}
      {...props}
    >
      <span id={instructionsId} className="sr-only">
        {messages.instructions}
      </span>
      <div className="min-w-full" style={{ width: `calc(var(--timeline-names) + ${width}px)` }}>
        <div className="sticky top-0 z-30 flex h-8 bg-background">
          <div aria-hidden className="sticky left-0 z-20 w-(--timeline-names) shrink-0 bg-background" />
          <AnimationTimelineRuler />
        </div>
        <div className="flex">
          <div ref={namesRef} className="sticky left-0 z-20 w-(--timeline-names) shrink-0 bg-background">
            {tracks.map((track) => (
              <TrackHeader key={track.id} track={track} />
            ))}
          </div>
          <div
            ref={laneRef}
            data-slot="animation-timeline-lanes"
            className="relative shrink-0 overflow-hidden select-none"
            style={{ width }}
            onClick={(event) => {
              if (event.currentTarget.contains(event.target as Node)) onLaneClick(event.target as Element, event.shiftKey);
            }}
          >
            {tracks.map((track) => (
              <div key={track.id} className="h-(--timeline-row) py-0.5">
                <div data-locked={track.locked ? "" : undefined} className="h-full rounded-md bg-foreground/8 data-locked:opacity-50" />
              </div>
            ))}
            {items.map((item) => (
              <AnimationTimelineItem key={item.id} item={item} />
            ))}
            {guide !== null && <div aria-hidden data-slot="animation-timeline-guide" className="pointer-events-none absolute inset-y-0 z-10 w-px bg-primary" style={{ left: guide * pixelsPerSecond }} />}
            <div aria-hidden data-slot="animation-timeline-playhead" className="pointer-events-none absolute inset-y-0 z-10 w-0.5 bg-primary" style={{ left: `clamp(0px, ${time * pixelsPerSecond}px, calc(100% - 2px))` }} />
          </div>
        </div>
      </div>
    </div>
  );
});

"use client";

import { type KeyboardEvent, type PointerEvent as ReactPointerEvent, useEffect, useRef, useState } from "react";
import { itemEdges, roundTime, snapDelta, type TimelineItem } from "./animation-timeline-math";
import { type AnimationTimelineZoomValue, useIsomorphicLayoutEffect } from "./animation-timeline-state";

type ScrubOptions = {
  time: number;
  duration: number;
  items: TimelineItem[];
  snap: boolean;
  snapInterval: number;
  step: number;
  largeStep: number;
  pixelsPerSecond: number;
  disabled: boolean;
  laneRef: { current: HTMLDivElement | null };
  setLive: (time: number | null) => void;
  onSeek?: (time: number) => void;
  onSeekCommit: (time: number) => void;
};

const clampTime = (time: number, duration: number) => roundTime(Math.min(duration, Math.max(0, time)));

/** Click or drag the ruler to move the playhead. Escape returns it to where it started. */
export function useTimelineScrub(options: ScrubOptions) {
  const latest = useRef(options);
  useIsomorphicLayoutEffect(() => {
    latest.current = options;
  });
  const stopRef = useRef<(() => void) | null>(null);
  const [scrubbing, setScrubbing] = useState(false);

  const timeFrom = (event: { clientX: number; altKey: boolean }) => {
    const { laneRef, pixelsPerSecond, duration, items, snap, snapInterval } = latest.current;
    const left = laneRef.current?.getBoundingClientRect().left ?? 0;
    const raw = (event.clientX - left) / pixelsPerSecond;
    const found = snap && !event.altKey ? snapDelta([raw], [0, duration, ...items.flatMap(itemEdges)], snapInterval, 6 / pixelsPerSecond) : null;
    return clampTime(raw + (found?.delta ?? 0), duration);
  };

  const onPointerDown = (event: ReactPointerEvent<HTMLElement>) => {
    const { disabled, time: start } = latest.current;
    if (disabled || event.button !== 0 || stopRef.current) return;
    const pointerId = event.pointerId;
    let last = timeFrom(event);
    const show = (next: number) => {
      last = next;
      latest.current.setLive(next);
      latest.current.onSeek?.(next);
    };
    const end = () => {
      stopRef.current?.();
      stopRef.current = null;
      setScrubbing(false);
      latest.current.setLive(null);
    };
    const cancel = () => {
      latest.current.onSeek?.(start);
      end();
    };
    const onMove = (next: PointerEvent) => {
      if (next.pointerId === pointerId) show(timeFrom(next));
    };
    const onUp = (next: PointerEvent) => {
      if (next.pointerId !== pointerId) return;
      latest.current.onSeekCommit(last);
      end();
    };
    const onCancel = (next: PointerEvent) => {
      if (next.pointerId === pointerId) cancel();
    };
    const onKey = (next: globalThis.KeyboardEvent) => {
      if (next.key !== "Escape") return;
      next.preventDefault();
      next.stopPropagation();
      cancel();
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("blur", cancel);
    stopRef.current = () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("blur", cancel);
    };
    setScrubbing(true);
    show(last);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    const { disabled, time, duration, step, largeStep, onSeek, onSeekCommit } = latest.current;
    const amount = event.shiftKey ? largeStep : step;
    const targets: Record<string, number> = { ArrowLeft: time - amount, ArrowDown: time - amount, ArrowRight: time + amount, ArrowUp: time + amount, PageDown: time - largeStep, PageUp: time + largeStep, Home: 0, End: duration };
    const target = targets[event.key];
    if (disabled || target === undefined) return;
    event.preventDefault();
    const next = clampTime(target, duration);
    if (next === time) return;
    onSeek?.(next);
    onSeekCommit(next);
  };

  useEffect(() => () => stopRef.current?.(), []);

  return { scrubbing, handlers: { onPointerDown, onKeyDown } };
}

type ZoomOptions = {
  initial: AnimationTimelineZoomValue;
  max: number;
  duration: number;
  basePixels: number;
  hasTracks: boolean;
  scrollerRef: { current: HTMLDivElement | null };
  namesRef: { current: HTMLDivElement | null };
  laneRef: { current: HTMLDivElement | null };
};

/** Fit shows the whole timeline. A percent zooms in from Fit and keeps one moment in place: the pointer's with Ctrl or Cmd + scroll, otherwise the view's center. */
export function useTimelineZoom({ initial, max, duration, basePixels, hasTracks, scrollerRef, namesRef, laneRef }: ZoomOptions) {
  const [zoom, setZoomState] = useState(initial);
  const [fitWidth, setFitWidth] = useState(0);
  const fitPixels = fitWidth > 0 && duration > 0 ? fitWidth / duration : basePixels;
  const pixelsPerSecond = zoom === "fit" ? fitPixels : (fitPixels * zoom) / 100;
  const latest = useRef({ zoom, pixelsPerSecond, fitPixels, max });
  const pending = useRef<{ time: number; offset: number } | null>(null);
  useIsomorphicLayoutEffect(() => {
    latest.current = { zoom, pixelsPerSecond, fitPixels, max };
    const scroller = scrollerRef.current;
    if (!pending.current || !scroller) return;
    scroller.scrollLeft = (namesRef.current?.offsetWidth ?? 0) + pending.current.time * pixelsPerSecond - pending.current.offset;
    pending.current = null;
  });

  // Fit follows the space available, so it holds at every screen size.
  useIsomorphicLayoutEffect(() => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const measure = () => setFitWidth(Math.max(0, Math.floor(scroller.clientWidth - (namesRef.current?.offsetWidth ?? 0))));
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(scroller);
    return () => observer.disconnect();
  }, [hasTracks, scrollerRef, namesRef]);

  const zoomTo = (requested: AnimationTimelineZoomValue, clientX?: number) => {
    const current = latest.current;
    if (requested === "fit" || requested <= 100) {
      pending.current = null;
      setZoomState("fit");
      return;
    }
    const next = Math.round(Math.min(current.max, requested));
    if (next === current.zoom) return;
    const scroller = scrollerRef.current;
    const lane = laneRef.current;
    if (scroller && lane) {
      const box = scroller.getBoundingClientRect();
      const names = namesRef.current?.offsetWidth ?? 0;
      const anchor = clientX ?? box.left + names + (box.width - names) / 2;
      pending.current = { time: (anchor - lane.getBoundingClientRect().left) / current.pixelsPerSecond, offset: anchor - box.left };
    }
    setZoomState(next);
  };
  const zoomRef = useRef(zoomTo);
  useIsomorphicLayoutEffect(() => {
    zoomRef.current = zoomTo;
  });

  useEffect(() => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey && !event.metaKey) return;
      event.preventDefault();
      const { pixelsPerSecond: shown, fitPixels: fit } = latest.current;
      zoomRef.current((shown / fit) * 100 * Math.exp(-event.deltaY * 0.002), event.clientX);
    };
    scroller.addEventListener("wheel", onWheel, { passive: false });
    return () => scroller.removeEventListener("wheel", onWheel);
  }, [hasTracks, scrollerRef]);

  return { zoom, pixelsPerSecond, setZoom: zoomTo };
}

