type Props = {
  textRef: RefObject<HTMLElement | null>;
  text: string;
  preset: FlamePreset;
  still: boolean;
  speed: number;
  color: string;
};

export function FlameCanvas({ textRef, text, preset, still, speed, color }: Props) {
  const ref = useRef<HTMLCanvasElement>(null);
  const options = useRef({ preset, still, speed });
  const invalidate = useRef<() => void>(undefined);

  useEffect(() => {
    options.current = { preset, still, speed };
    invalidate.current?.();
  }, [preset, still, speed, text, color]);

  useEffect(() => {
    const canvas = ref.current;
    const word = textRef.current;
    if (!canvas || !word) return;
    let renderer = createFlameRenderer(canvas, word);
    const reduced = matchMedia("(prefers-reduced-motion: reduce)");
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    let inView = false;
    let forceMask = true;
    let frame = 0;
    let time = 3;
    let last = 0;

    const animate = (now: number) => {
      time += Math.min(now - last, 50) / 1000 * options.current.speed;
      last = now;
      renderer?.draw(time);
      frame = requestAnimationFrame(animate);
    };
    const sync = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      if (!renderer || !inView || document.hidden) return;
      if (renderer.update(forceMask, options.current.preset)) {
        renderer.draw(time);
        canvas.dataset.ready = "";
      }
      forceMask = false;
      if (!reduced.matches && !options.current.still) {
        last = performance.now();
        frame = requestAnimationFrame(animate);
      }
    };
    const fontsChanged = () => { forceMask = true; sync(); };
    const lost = (event: Event) => {
      event.preventDefault();
      renderer = undefined;
      delete canvas.dataset.ready;
      sync();
    };
    const restored = () => {
      renderer = createFlameRenderer(canvas, word);
      fontsChanged();
    };
    invalidate.current = sync;
    const resize = new ResizeObserver(sync);
    resize.observe(word);
    resize.observe(canvas);
    const theme = new MutationObserver(sync);
    for (let node = canvas.parentElement; node; node = node.parentElement) {
      theme.observe(node, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
    }
    const viewer = new IntersectionObserver(([entry]) => {
      inView = entry.isIntersecting;
      sync();
    });
    viewer.observe(canvas);
    document.fonts?.addEventListener("loadingdone", fontsChanged);
    document.addEventListener("visibilitychange", sync);
    window.addEventListener("resize", sync);
    reduced.addEventListener("change", sync);
    scheme.addEventListener("change", sync);
    canvas.addEventListener("webglcontextlost", lost);
    canvas.addEventListener("webglcontextrestored", restored);
    return () => {
      invalidate.current = undefined;
      cancelAnimationFrame(frame);
      resize.disconnect();
      theme.disconnect();
      viewer.disconnect();
      document.fonts?.removeEventListener("loadingdone", fontsChanged);
      document.removeEventListener("visibilitychange", sync);
      window.removeEventListener("resize", sync);
      reduced.removeEventListener("change", sync);
      scheme.removeEventListener("change", sync);
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      renderer?.dispose();
      delete canvas.dataset.ready;
    };
  }, [textRef]);

  return <canvas ref={ref} aria-hidden className={styles.canvas} />;
}

import { flameBed } from "./flame-bed";
import { flamePresets, flameShader, flameUniforms, type FlamePreset } from "./flame-shader";
import { createFullscreenProgram } from "./burning-text-gl";

export function createFlameRenderer(canvas: HTMLCanvasElement, word: HTMLElement) {
  const gl = canvas.getContext("webgl2", { alpha: true, antialias: false, premultipliedAlpha: true });
  const mask = document.createElement("canvas");
  const ctx = mask.getContext("2d", { willReadFrequently: true });
  if (!gl || !ctx) return;
  const setup = createFullscreenProgram(gl, flameShader, flameUniforms);
  if (!setup) return;
  const u = setup.uniforms;

  const texture = (unit: number, uniform: string) => {
    const handle = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, handle);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.uniform1i(u[uniform], unit);
    return handle;
  };

  const glyphs = texture(0, "u_mask");
  const bed = texture(1, "u_bed");
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  let geometry = "";
  let palette = "";

  return {
    update(forceMask: boolean, preset: FlamePreset) {
      const style = getComputedStyle(word);
      const box = canvas.getBoundingClientRect();
      const letters = word.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
      const text = word.textContent ?? "";
      const x = letters.left - box.left;
      const y = letters.top - box.top;
      const key = JSON.stringify([text, font, style.letterSpacing, style.direction, box.width, box.height, x, y, letters.height, dpr]);
      const maskChanged = forceMask || key !== geometry;
      if (maskChanged) {
        geometry = key;
        canvas.width = mask.width = Math.max(1, Math.round(box.width * dpr));
        canvas.height = mask.height = Math.max(1, Math.round(box.height * dpr));
        gl.viewport(0, 0, mask.width, mask.height);
        gl.uniform2f(u.u_res, mask.width, mask.height);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.font = font;
        ctx.direction = style.direction === "rtl" ? "rtl" : "ltr";
        ctx.textAlign = "left";
        ctx.letterSpacing = style.letterSpacing === "normal" ? "0px" : style.letterSpacing;
        const metrics = ctx.measureText(text);
        const baseline = y + (letters.height + metrics.fontBoundingBoxAscent - metrics.fontBoundingBoxDescent) / 2;
        ctx.fillStyle = "#fff";
        ctx.fillText(text, x, baseline);
        gl.activeTexture(gl.TEXTURE0);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, mask);
        const em = parseFloat(style.fontSize) * dpr;
        const pixels = ctx.getImageData(0, 0, mask.width, mask.height).data;
        gl.activeTexture(gl.TEXTURE1);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, mask.width, 1, 0, gl.RGBA, gl.FLOAT, flameBed(pixels, mask.width, mask.height, em));
        gl.uniform1f(u.u_em, em / mask.height);
      }
      const { color, colorScheme } = getComputedStyle(canvas);
      const paletteKey = JSON.stringify([color, colorScheme, preset]);
      if (paletteKey === palette) return maskChanged;
      palette = paletteKey;
      // Canvas resolves CSS colors, including wide-gamut theme tokens, to sRGB bytes.
      ctx.resetTransform();
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, 1, 1);
      const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
      gl.uniform3f(u.u_color, r / 255, g / 255, b / 255);
      gl.uniform1f(u.u_dark, colorScheme === "dark" ? 1 : 0);
      const { reach, sway, rate, profile } = flamePresets[preset];
      gl.uniform1f(u.u_reach, reach);
      gl.uniform1f(u.u_sway, sway);
      gl.uniform1f(u.u_rate, rate);
      gl.uniform1f(u.u_profile, profile);
      return true;
    },
    draw(time: number) {
      gl.uniform1f(u.u_time, time);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteTexture(glyphs);
      gl.deleteTexture(bed);
      gl.deleteBuffer(setup.buffer);
      gl.deleteProgram(setup.program);
    },
  };
}

export const flameUniforms = ["u_mask", "u_bed", "u_res", "u_time", "u_color", "u_dark", "u_reach", "u_sway", "u_rate", "u_profile", "u_em"];

/** Presets for how tall, wild and fast the flames are. */
export const flamePresets = {
  candle: { reach: 0.085, sway: 0.012, rate: 0.52, profile: -1 },
  campfire: { reach: 0.21, sway: 0.05, rate: 1.05, profile: 0 },
  blaze: { reach: 0.40, sway: 0.085, rate: 1.38, profile: 1 },
} as const;

export type FlamePreset = keyof typeof flamePresets;

/**
 * Flames rising from a glyph mask. `u_bed` holds, per column, a roof over the letter tops
 * (see flame-bed.ts), the letter top and the flame strength. Flames rise from the roof with
 * noise-driven sway that grows with height; below the roof, down to the letters, the bed
 * burns too, so fire fills curved shoulders and the dips between letters.
 */
export const flameShader = /* glsl */ `#version 300 es
precision highp float;
uniform sampler2D u_mask;
uniform sampler2D u_bed;
uniform vec2 u_res;
uniform float u_time;
uniform vec3 u_color;
uniform float u_dark;
uniform float u_reach;
uniform float u_sway;
uniform float u_rate;
uniform float u_profile;
uniform float u_em;
out vec4 outColor;
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = m * p;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  float t = u_time * u_rate;

  // Flow field scrolling upward: sways and stretches the flames.
  vec2 flow = vec2(uv.x * aspect * 2.4, uv.y * 2.0 - t * 1.25);
  float n1 = fbm(flow);
  float n2 = fbm(flow * 2.3 + vec2(3.7, -t * 1.1));
  float reach = u_reach * (0.55 + 0.9 * n1);

  // Sway grows with height above the roof, so the base stays on the letters.
  float rise = clamp((uv.y - texture(u_bed, vec2(uv.x, 0.5)).r) / reach, 0.0, 1.0);
  float shift = ((n1 - 0.5) + (n2 - 0.5) * 0.7) * u_sway * rise * 1.6;
  vec3 bed = texture(u_bed, vec2(uv.x - shift, 0.5)).rgb;
  // Candle has only a few low flickers on the actual letter tops.
  if (u_profile < 0.0) {
    bed.b *= 1.0 - smoothstep(0.06, 0.16, (bed.r - bed.g) / u_em);
    bed.r = max(bed.g, bed.r - 0.16 * u_em);
    bed.b *= mix(0.42, 1.0, smoothstep(0.26, 0.70, n2));
  }
  float above = uv.y - bed.r;
  // Tongues rise tallest straight off the letters and stay lower over the gaps between them.
  reach *= mix(0.78, 1.15, bed.b);

  // Run one heat field through the upper strokes and into the air above them.
  // Only the lower part of the word returns to solid ink.
  float ink = texture(u_mask, uv).a;
  float root = max(bed.g, bed.r - 0.14 * u_em);
  float belowTop = max(root - uv.y, 0.0) / u_em;
  float licks = smoothstep(0.26, 0.74, fbm(vec2(uv.x * aspect * 7.0, uv.y * 3.0 - t * 2.2)));
  float inside = 1.0 - smoothstep(0.01, 0.13 + 0.13 * licks, belowTop);
  float crown = 1.0 - smoothstep(0.06, 0.23, max(-above, 0.0) / u_em);
  float heat = pow(max(1.0 - max(above, 0.0) / reach, 0.0), 0.9);
  heat *= bed.b * crown * inside;
  float fire = heat * mix(0.48, 1.16, licks);

  if (u_profile < 0.0) {
    fire *= 0.84;
  } else if (u_profile > 0.0) {
    // Follow each column from its lowest ink. The glyph mask keeps the
    // counters open while hot streaks climb the strokes into the plume.
    vec4 column = texture(u_bed, vec2(uv.x, 0.5));
    float height = max(column.g - column.a, 1.0 / u_res.y);
    float fromBase = clamp((uv.y - column.a) / height, 0.0, 1.0);
    float streak = fbm(vec2(uv.x * aspect * 10.0 + 1.3 * n2, uv.y * 4.0 - t * 2.5));
    float ignition = mix(0.52, 1.38, smoothstep(0.24, 0.74, streak));
    fire = max(fire * 1.18, ink * ignition * mix(1.10, 0.92, fromBase));
  }

  vec3 coal = u_color * mix(0.63, 0.88, u_dark);
  float warmth = smoothstep(0.0, 0.55, u_color.r - u_color.b);
  vec3 incandescent = mix(vec3(0.88, 0.95, 1.0), vec3(1.0, 0.79, 0.42), warmth);
  vec3 ember = mix(u_color, incandescent, 0.55);
  vec3 flame = mix(u_color, ember, smoothstep(0.46, 0.88, fire));
  flame = mix(flame, mix(incandescent, vec3(1.0), 0.6), 0.5 * smoothstep(0.84, 1.12, fire));
  vec3 body = mix(coal, mix(u_color, ember, 0.45 * u_dark), 0.28 + 0.65 * licks);
  body = mix(body, incandescent, 0.12 * u_dark * smoothstep(0.10, 0.30, belowTop));
  body = mix(body, flame, inside * crown);
  // At a hot root the same color covers both sides of the glyph silhouette.
  float plume = smoothstep(0.18, 0.80, fire) * (1.0 - smoothstep(0.85, 1.0, uv.y));
  outColor = vec4(mix(body * ink, flame, plume), ink + (1.0 - ink) * plume);
}
`;

"use client";

import { Toolbar } from "@base-ui/react/toolbar";
import { type ComponentPropsWithoutRef, type MouseEvent, type ReactNode, forwardRef, useCallback, useContext, useEffect, useRef } from "react";
import { CanvasToolbarTip } from "./canvas-toolbar-root";
import { CanvasToolbarToolsContext, useCanvasToolbar } from "./canvas-toolbar-state";
import { cn } from "@/lib/utils";

type ItemProps = Omit<ComponentPropsWithoutRef<"button">, "children" | "aria-label"> & {
  /** Names the item, and shows in its tooltip. */
  label: string;
  icon?: ReactNode;
  /** The shortcut to show in the tooltip. */
  shortcut?: string;
  /** Why the item is disabled. It replaces the tooltip and is read by screen readers. */
  reason?: string;
  /** Shows the label beside the icon. */
  showLabel?: boolean;
  tooltipClassName?: string;
};

const Item = forwardRef<HTMLButtonElement, ItemProps & { selected?: boolean }>(function Item({ label, icon, shortcut, reason, showLabel, selected, disabled, tooltipClassName, className, ...props }, ref) {
  const explained = disabled ? reason : undefined;
  return (
    <CanvasToolbarTip label={explained ?? label} shortcut={disabled ? undefined : shortcut} className={tooltipClassName}>
      <Toolbar.Button
        ref={ref}
        disabled={disabled}
        aria-label={label}
        aria-description={explained}
        aria-keyshortcuts={disabled ? undefined : shortcut}
        data-canvas-toolbar-item=""
        data-selected={selected || undefined}
        className={cn(
          "relative z-10 inline-flex h-8 shrink-0 items-center justify-center gap-1.5 rounded-md text-[13px] text-muted-foreground outline-none transition-colors select-none pointer-coarse:h-11 [&_svg]:size-4 [&_svg]:shrink-0",
          showLabel ? "px-2.5" : "w-8 pointer-coarse:w-11",
          "hover:text-foreground focus-visible:bg-foreground/10 focus-visible:text-foreground",
          // A tint of the primary colour stays visible in light and dark themes.
          "data-selected:bg-primary/10 data-selected:text-foreground",
          "aria-disabled:opacity-40 aria-disabled:hover:text-muted-foreground",
          className,
        )}
        {...props}
      >
        {icon}
        {showLabel && label}
      </Toolbar.Button>
    </CanvasToolbarTip>
  );
});

export type CanvasToolbarButtonProps = ItemProps & {
  /** Keeps the button on, for a panel or setting that stays active. */
  pressed?: boolean;
};

/** An action, or a toggle when given `pressed`. It also works as a menu trigger. */
export const CanvasToolbarButton = forwardRef<HTMLButtonElement, CanvasToolbarButtonProps>(function CanvasToolbarButton({ pressed, ...props }, ref) {
  return <Item ref={ref} selected={pressed} aria-pressed={pressed} {...props} />;
});

export type CanvasToolbarToolsProps<V extends string = string> = Omit<ComponentPropsWithoutRef<"div">, "onChange"> & {
  /** The chosen tool, or null for none. Your app owns it. */
  value: V | null;
  onValueChange: (value: V | null) => void;
  /** Choosing the current tool again turns it off. */
  deselectable?: boolean;
  /** Listens for each tool's single-key shortcut while nobody is typing. */
  shortcuts?: boolean;
};

const isTyping = (target: EventTarget | null) => target instanceof HTMLElement && (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));

/** The tools, of which one is active at a time. Arrow keys move through the toolbar; Enter or Space chooses. */
export function CanvasToolbarTools<V extends string = string>({ value, onValueChange, deselectable = false, shortcuts = false, className, children, ...props }: CanvasToolbarToolsProps<V>) {
  const { orientation, disabled, messages } = useCanvasToolbar();
  const registered = useRef(new Map<string, { shortcut?: string; disabled: boolean }>());
  const latest = useRef(onValueChange);
  useEffect(() => {
    latest.current = onValueChange;
  });

  useEffect(() => {
    if (!shortcuts || disabled) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.repeat || event.defaultPrevented || event.metaKey || event.ctrlKey || event.altKey || isTyping(event.target)) return;
      for (const [tool, entry] of registered.current) {
        if (entry.disabled || entry.shortcut?.toLowerCase() !== event.key.toLowerCase()) continue;
        event.preventDefault();
        latest.current(tool as V);
        return;
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [shortcuts, disabled]);

  const register = useCallback((tool: string, shortcut: string | undefined, toolDisabled: boolean) => {
    registered.current.set(tool, { shortcut, disabled: toolDisabled });
    return () => void registered.current.delete(tool);
  }, []);

  const context = {
    value,
    choose: (next: string) => onValueChange(next === value && deselectable ? null : (next as V)),
    register,
  };

  return (
    <CanvasToolbarToolsContext.Provider value={context}>
      <Toolbar.Group role="radiogroup" aria-label={messages.tools} className={cn("flex gap-0.5", orientation === "vertical" ? "flex-col items-center" : "items-center", className)} {...props}>
        {children}
      </Toolbar.Group>
    </CanvasToolbarToolsContext.Provider>
  );
}

export type CanvasToolbarToolProps = ItemProps & { value: string };

/** One tool in CanvasToolbarTools. */
export const CanvasToolbarTool = forwardRef<HTMLButtonElement, CanvasToolbarToolProps>(function CanvasToolbarTool({ value, shortcut, disabled = false, onClick, ...props }, ref) {
  const tools = useContext(CanvasToolbarToolsContext);
  if (!tools) throw new Error("CanvasToolbarTool must be rendered inside <CanvasToolbarTools>.");
  const { register } = tools;
  useEffect(() => register(value, shortcut, disabled), [register, value, shortcut, disabled]);
  const selected = tools.value === value;
  return (
    <Item
      ref={ref}
      role="radio"
      aria-checked={selected}
      selected={selected}
      shortcut={shortcut}
      disabled={disabled}
      onClick={(event: MouseEvent<HTMLButtonElement>) => {
        onClick?.(event);
        if (!event.defaultPrevented) tools.choose(value);
      }}
      {...props}
    />
  );
});

type PresetProps = Partial<CanvasToolbarToolProps>;

const pointerIcon = (
  <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinejoin="round">
    <path d="M3.25 2.75 13 7.2 8.8 8.8 7.2 13Z" />
  </svg>
);

const handIcon = (
  <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5.25 8V3.5a1 1 0 0 1 2 0V7m0-.25V2.75a1 1 0 0 1 2 0V7m0-3.25a1 1 0 0 1 2 0V7.5m0-2a1 1 0 0 1 2 0V9.5a4.75 4.75 0 0 1-4.75 4.75c-1.8 0-2.9-.65-3.8-2L2.6 9.6a1.05 1.05 0 0 1 1.65-1.3L5.25 9.4" />
  </svg>
);

/** The standard selection tool: V. */
export const CanvasToolbarPointer = forwardRef<HTMLButtonElement, PresetProps>(function CanvasToolbarPointer(props, ref) {
  const { messages } = useCanvasToolbar();
  return <CanvasToolbarTool ref={ref} value="pointer" label={messages.pointer} shortcut="V" icon={pointerIcon} {...props} />;
});

/** The standard panning tool: H. Pair it with Canvas Viewport's `panning`. */
export const CanvasToolbarHand = forwardRef<HTMLButtonElement, PresetProps>(function CanvasToolbarHand(props, ref) {
  const { messages } = useCanvasToolbar();
  return <CanvasToolbarTool ref={ref} value="hand" label={messages.hand} shortcut="H" icon={handIcon} {...props} />;
});

"use client";

import { Toolbar } from "@base-ui/react/toolbar";
import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactElement, type ReactNode, forwardRef, useState } from "react";
import { type CanvasToolbarProps, CanvasToolbarContext, defaultMessages, useCanvasToolbar } from "./canvas-toolbar-state";
import { cn } from "@/lib/utils";

type HoverBox = { x: number; y: number; width: number; height: number; slide: boolean };

/** A design tool's toolbar: one box of tools and actions, and one tab stop with arrow keys between its items. */
export const CanvasToolbar = forwardRef<HTMLDivElement, CanvasToolbarProps>(function CanvasToolbar(
  { orientation = "horizontal", variant = "floating", disabled = false, motion = true, container, messages: messagesProp, className, children, onPointerOver, onPointerLeave, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  const vertical = orientation === "vertical";
  const [hover, setHover] = useState<HoverBox | null>(null);

  // One soft box follows the pointer between items and skips any that already show as chosen.
  const trackHover: NonNullable<CanvasToolbarProps["onPointerOver"]> = (event) => {
    onPointerOver?.(event);
    if (event.pointerType === "touch") return;
    const item = (event.target as Element).closest<HTMLElement>("[data-canvas-toolbar-item]");
    if (!item || item.hasAttribute("data-selected") || item.getAttribute("aria-disabled") === "true") return setHover(null);
    setHover((current) => ({ x: item.offsetLeft, y: item.offsetTop, width: item.offsetWidth, height: item.offsetHeight, slide: !!current }));
  };

  return (
    <CanvasToolbarContext.Provider value={{ orientation, disabled, animated: motion, container, messages }}>
      <Tooltip.Provider delay={400}>
        <Toolbar.Root
          ref={ref}
          aria-label={messages.label}
          orientation={orientation}
          disabled={disabled}
          data-slot="canvas-toolbar"
          data-variant={variant}
          className={cn(
            "relative isolate inline-flex w-fit gap-0.5 text-popover-foreground [scrollbar-width:none]",
            vertical ? "max-h-full flex-col items-center overflow-y-auto" : "max-w-full items-center overflow-x-auto",
            variant === "floating" && "rounded-xl border border-border bg-popover p-1 shadow-lg",
            disabled && "opacity-60",
            className,
          )}
          onPointerOver={trackHover}
          onPointerLeave={(event) => {
            onPointerLeave?.(event);
            setHover(null);
          }}
          {...props}
        >
          {hover && (
            <span
              aria-hidden
              data-slot="canvas-toolbar-hover"
              className={cn("pointer-events-none absolute top-0 left-0 rounded-md bg-accent", motion && hover.slide && "transition-[transform,width,height] duration-150 ease-out motion-reduce:transition-none")}
              style={{ width: hover.width, height: hover.height, transform: `translate(${hover.x}px, ${hover.y}px)` }}
            />
          )}
          {children}
        </Toolbar.Root>
      </Tooltip.Provider>
    </CanvasToolbarContext.Provider>
  );
});

/** A thin line between sets of items. */
export const CanvasToolbarSeparator = forwardRef<HTMLDivElement, Omit<ComponentPropsWithoutRef<typeof Toolbar.Separator>, "className" | "render"> & { className?: string }>(function CanvasToolbarSeparator(
  { className, ...props },
  ref,
) {
  const { orientation } = useCanvasToolbar();
  return <Toolbar.Separator ref={ref} className={cn("shrink-0 bg-border", orientation === "vertical" ? "my-1 h-px w-5" : "mx-0.5 h-5 w-px", className)} {...props} />;
});

type TipProps = {
