import { useSharedHighlight, usePhoneMenu } from "./context-menu-responsive";
import { cn } from "@/lib/utils";
import { type TransitionEvent, type ComponentPropsWithoutRef, useState, forwardRef } from "react";
import { ContextMenu as Base } from "@base-ui/react/context-menu";
import { useContextMenuContext } from "./context-menu-state";

/**
 * Open motion: the popup grows from the corner it opened at, widening and lengthening
 * together while fading in. The corner follows the side and alignment Base UI picks
 * after flipping to stay on screen. The clip stops exactly at the popup's edge so the
 * growth is visible to the end, then is removed (data-revealed) so the outline and
 * shadow outside that edge show. Closing fades out.
 */
export const reveal = cn(
  "[clip-path:inset(0)] transition-[clip-path,opacity] duration-300 ease-[cubic-bezier(0.33,1,0.68,1)] motion-reduce:transition-none",
  "data-[revealed]:[clip-path:none] data-[starting-style]:opacity-0 data-[ending-style]:opacity-0 data-[ending-style]:duration-150",
  "data-[starting-style]:[clip-path:inset(0_100%_100%_0)]",
  "data-[side=top]:data-[starting-style]:[clip-path:inset(100%_100%_0_0)]",
  "data-[align=end]:data-[starting-style]:[clip-path:inset(0_0_100%_100%)]",
  "data-[side=top]:data-[align=end]:data-[starting-style]:[clip-path:inset(100%_0_0_100%)]",
);

/** Marks the popup revealed once its clip transition ends, which lifts the clip. */
export const markRevealed = (event: TransitionEvent<HTMLDivElement>) => {
  if (event.target === event.currentTarget && event.propertyName === "clip-path" && !event.currentTarget.hasAttribute("data-ending-style")) {
    event.currentTarget.setAttribute("data-revealed", "");
  }
};

export type ContextMenuContentProps = ComponentPropsWithoutRef<typeof Base.Popup> & {
  /** Where the popup is portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  positionMethod?: "absolute" | "fixed";
  collisionPadding?: number;
  /** Styles the shared highlight that slides between items. It carries the item's data-variant. */
  highlightClassName?: string;
  /** Visible dismissal action on phones; replace for localization. */
  cancelLabel?: string;
};

export const ContextMenuContent = forwardRef<HTMLDivElement, ContextMenuContentProps>(function ContextMenuContent(
  { className, container, positionMethod, collisionPadding = 8, highlightClassName, cancelLabel = "Cancel", onTransitionEnd, children, ...props },
  ref,
) {
  const { animated, focusFirstRef } = useContextMenuContext("ContextMenuContent");
  const [popup, setPopup] = useState<HTMLDivElement | null>(null);
  const highlight = useSharedHighlight(popup);
  const phone = usePhoneMenu();

  return (
    <Base.Portal container={container ?? undefined}>
      {phone && <Base.Backdrop className="fixed inset-0 z-50 bg-black/40" />}
      <Base.Positioner positionMethod={positionMethod} collisionPadding={collisionPadding} className="z-50 outline-none"
        style={phone ? { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } : undefined}>
        <Base.Popup
          onTransitionEnd={(event) => {
            onTransitionEnd?.(event);
            if (animated) markRevealed(event);
          }}
          ref={(node) => {
            if (typeof ref === "function") ref(node);
            else if (ref) ref.current = node;
            setPopup(node);
            // A keyboard-opened menu starts on its first available action.
            if (node && (phone || focusFirstRef.current)) {
              focusFirstRef.current = false;
              requestAnimationFrame(() => phone ? node.focus() : node.querySelector<HTMLElement>('[role="menuitem"]:not([data-disabled])')?.focus());
            }
          }}
          className={cn(
            "relative min-w-48 origin-[var(--transform-origin)] overflow-hidden rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md outline-none",
            phone && "max-h-[80dvh] w-full overflow-y-auto rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
            animated && (phone ? "transition-[transform,opacity] duration-200 ease-out data-[starting-style]:translate-y-full data-[ending-style]:translate-y-full data-[starting-style]:opacity-0 data-[ending-style]:opacity-0 motion-reduce:transition-none" : reveal),
            className,
          )}
          {...(props as ComponentPropsWithoutRef<typeof Base.Popup>)}
        >
          <span
            aria-hidden
            data-slot="highlight"
            data-variant={highlight?.variant}
            data-visible={highlight?.visible ? "" : undefined}
            className={cn(
              "pointer-events-none absolute rounded-sm bg-accent opacity-0 data-[visible]:opacity-100 data-[variant=destructive]:bg-destructive/10",
              animated && highlight?.slide && "transition-[top,height,width,opacity,background-color] duration-150 ease-out motion-reduce:transition-none",
              animated && !highlight?.slide && "transition-opacity duration-100 motion-reduce:transition-none",
              highlightClassName,
            )}
            style={highlight ? { top: highlight.top, left: highlight.left, width: highlight.width, height: highlight.height } : undefined}
          />
          {children}
          {phone && <Base.Item className="relative mt-3 flex min-h-11 items-center justify-center rounded-lg border border-border px-4 text-sm font-medium outline-none data-[highlighted]:bg-accent">{cancelLabel}</Base.Item>}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  );
});

"use client";

import { useState, useEffect, useSyncExternalStore } from "react";

const query = "(max-width: 639px)";
const phoneSnapshot = () => typeof window.matchMedia === "function" && window.matchMedia(query).matches;
const serverSnapshot = () => false;
const subscribe = (notify: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};

/** Keeps SSR deterministic, then adapts the open menu to the current viewport. */
export function usePhoneMenu() {
  return useSyncExternalStore(subscribe, phoneSnapshot, serverSnapshot);
}

export type Highlight = { top: number; left: number; width: number; height: number; variant?: string; visible: boolean; slide: boolean };

/**
 * One highlight for the whole menu. It follows Base UI's data-highlighted item, sliding across
 * separators and groups instead of each item lighting up on its own.
 */
export function useSharedHighlight(popup: HTMLElement | null) {
  const [highlight, setHighlight] = useState<Highlight | null>(null);
  useEffect(() => {
    if (!popup) return;
    const update = () => {
      const item = popup.querySelector<HTMLElement>('[role="menuitem"][data-highlighted]');
      setHighlight((previous) =>
        item
          ? {
              top: item.offsetTop,
              left: item.offsetLeft,
              width: item.offsetWidth,
              height: item.offsetHeight,
              variant: item.dataset.variant,
              visible: true,
              // Slide only from one item to another; the first highlight appears in place.
              slide: !!previous?.visible,
            }
          : previous && { ...previous, visible: false },
      );
    };
    const observer = new MutationObserver(update);
    observer.observe(popup, { subtree: true, attributes: true, attributeFilter: ["data-highlighted"] });
    update();
    return () => observer.disconnect();
  }, [popup]);
  return highlight;
}

"use client";

import { type MutableRefObject, createContext, useContext, type ReactNode, useState, useRef } from "react";
import { ContextMenu as Base } from "@base-ui/react/context-menu";

export type ContextMenuContextValue = {
  open: boolean;
  disabled: boolean;
  animated: boolean;
  targetRef: MutableRefObject<HTMLDivElement | null>;
  /** Opens the menu at a point, through the same path as a right click. */
  openAt: (x: number, y: number, fromKeyboard: boolean) => void;
  focusFirstRef: MutableRefObject<boolean>;
};

export const ContextMenuContext = createContext<ContextMenuContextValue | null>(null);

export function useContextMenuContext(part: string) {
  const context = useContext(ContextMenuContext);
  if (!context) throw new Error(`<${part}> must be used inside <ContextMenu>.`);
  return context;
}

/** Events we dispatch ourselves, so the keyboard handling below leaves them alone. */
export const synthetic = new WeakSet<Event>();

/**
 * Turns off text selection on the page while a finger holds the target, so a long
 * press opens the menu instead of also selecting nearby text (iOS starts both).
 * Returns a function that restores the previous setting.
 */
export function suspendTextSelection() {
  const style = document.documentElement.style;
  const previous = [style.userSelect, style.webkitUserSelect];
  style.userSelect = "none";
  style.webkitUserSelect = "none";
  return () => {
    [style.userSelect, style.webkitUserSelect] = previous;
  };
}

/** Bottom-left corner of an element: where a keyboard- or button-opened menu appears. */
export const cornerOf = (element: Element) => {
  const rect = element.getBoundingClientRect();
  return { x: rect.left, y: rect.bottom };
};

/** A contextmenu event the browser raised for the menu key or Shift+F10 rather than a pointer. */
export const isKeyboardEvent = (event: MouseEvent) => {
  const pointerType = (event as PointerEvent).pointerType;
  return pointerType === "" || (pointerType === undefined && event.button !== 2 && event.clientX === 0 && event.clientY === 0);
};

export type ContextMenuProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Leaves the browser's own menu in place and disables the button. */
  disabled?: boolean;
  /** Open and close transitions. Reduced motion is always honored. */
  motion?: boolean;
  children?: ReactNode;
};

export function ContextMenu({ open: openProp, defaultOpen = false, onOpenChange, disabled = false, motion = true, children }: ContextMenuProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const open = openProp ?? uncontrolledOpen;
  const targetRef = useRef<HTMLDivElement | null>(null);
  const focusFirstRef = useRef(false);

  const openAt = (x: number, y: number, fromKeyboard: boolean) => {
    const event = new MouseEvent("contextmenu", { bubbles: true, cancelable: true, clientX: x, clientY: y, button: 2 });
    synthetic.add(event);
    focusFirstRef.current = fromKeyboard;
    targetRef.current?.dispatchEvent(event);
  };

  return (
    <ContextMenuContext.Provider value={{ open, disabled, animated: motion, targetRef, openAt, focusFirstRef }}>
      <Base.Root
        open={open}
        disabled={disabled}
        onOpenChange={(next) => {
          if (openProp === undefined) setUncontrolledOpen(next);
          onOpenChange?.(next);
        }}
      >
        {children}
      </Base.Root>
    </ContextMenuContext.Provider>
  );
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef, useRef, useEffect, type KeyboardEvent, type TouchEvent as ReactTouchEvent, type MouseEvent as ReactMouseEvent } from "react";
import { useContextMenuContext, cornerOf, suspendTextSelection, synthetic, isKeyboardEvent } from "./context-menu-state";
import { ContextMenu as Base } from "@base-ui/react/context-menu";
import { cn } from "@/lib/utils";

export type ContextMenuTargetProps = ComponentPropsWithoutRef<"div">;

/** The area that opens the menu on right click, long press, the menu key or Shift+F10. */
export const ContextMenuTarget = forwardRef<HTMLDivElement, ContextMenuTargetProps>(function ContextMenuTarget(
  { className, onKeyDown, onContextMenuCapture, onTouchStart, onTouchEnd, onTouchCancel, ...props },
  ref,
) {
  const { open, disabled, targetRef, openAt } = useContextMenuContext("ContextMenuTarget");
  const restoreSelection = useRef<(() => void) | null>(null);
  const endTouch = () => {
    restoreSelection.current?.();
    restoreSelection.current = null;
    // If the press opened the menu, clear any selection it started before selection was suspended.
    if (open) window.getSelection()?.removeAllRanges();
  };
  useEffect(() => () => restoreSelection.current?.(), []);

  const openFromKeyboard = () => {
    const focused = document.activeElement;
    const anchor = focused && targetRef.current?.contains(focused) ? focused : targetRef.current;
    if (!anchor) return;
    const { x, y } = cornerOf(anchor);
    openAt(x, y, true);
  };

  return (
    <Base.Trigger
      ref={(node) => {
        targetRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-disabled={disabled ? "" : undefined}
      className={cn("outline-none", className)}
      onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
        onKeyDown?.(event);
        if (disabled || event.defaultPrevented) return;
        if (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10")) {
          event.preventDefault();
          openFromKeyboard();
        }
      }}
      onTouchStart={(event: ReactTouchEvent<HTMLDivElement>) => {
        onTouchStart?.(event);
        if (!disabled && !restoreSelection.current) restoreSelection.current = suspendTextSelection();
      }}
      onTouchEnd={(event: ReactTouchEvent<HTMLDivElement>) => {
        onTouchEnd?.(event);
        if (restoreSelection.current) endTouch();
      }}
      onTouchCancel={(event: ReactTouchEvent<HTMLDivElement>) => {
        onTouchCancel?.(event);
        if (restoreSelection.current) endTouch();
      }}
      onContextMenuCapture={(event: ReactMouseEvent<HTMLDivElement>) => {
        onContextMenuCapture?.(event);
        // Browsers anchor keyboard-raised menus at the page corner; reopen at the focused element instead.
        if (disabled || synthetic.has(event.nativeEvent) || !isKeyboardEvent(event.nativeEvent)) return;
        event.preventDefault();
        event.stopPropagation();
        openFromKeyboard();
      }}
      {...props}
    />
  );
});

export type ContextMenuButtonProps = ComponentPropsWithoutRef<"button">;

/** A visible button with the same actions, for touch, keyboard and discoverability. */
export const ContextMenuButton = forwardRef<HTMLButtonElement, ContextMenuButtonProps>(function ContextMenuButton(
  { className, children, onClick, onPointerDown, "aria-label": ariaLabel = "More actions", ...props },
  ref,
) {
  const { open, disabled, openAt } = useContextMenuContext("ContextMenuButton");
  // The press that dismisses an open menu should not reopen it.
  const wasOpen = useRef(false);

  return (
    <button
      ref={ref}
      type="button"
      aria-haspopup="menu"
      aria-expanded={open}
      aria-label={children ? undefined : ariaLabel}
      disabled={disabled}
      data-state={open ? "open" : "closed"}
      className={cn(
        "inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:bg-accent focus-visible:text-accent-foreground disabled:pointer-events-none disabled:opacity-50 data-[state=open]:bg-accent data-[state=open]:text-accent-foreground",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        wasOpen.current = open;
      }}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || wasOpen.current) {
          wasOpen.current = false;
          return;
        }
        const { x, y } = cornerOf(event.currentTarget);
        // detail is 0 when Enter or Space pressed the button.
        openAt(x, y + 4, event.detail === 0);
      }}
      {...props}
    >
      {children ?? (
        <svg aria-hidden viewBox="0 0 16 16" fill="currentColor" className="size-4">
          <circle cx="3" cy="8" r="1.5" />
          <circle cx="8" cy="8" r="1.5" />
          <circle cx="13" cy="8" r="1.5" />
        </svg>
      )}
    </button>
  );
});

"use client";

export { type ContextMenuProps, ContextMenu } from "./context-menu-state";
export { type ContextMenuTargetProps, ContextMenuTarget, type ContextMenuButtonProps, ContextMenuButton } from "./context-menu-triggers";
export { type ContextMenuContentProps, ContextMenuContent } from "./context-menu-popup";
export { type ContextMenuItemProps, ContextMenuItem, ContextMenuGroup, ContextMenuGroupLabel, ContextMenuSeparator, ContextMenuShortcut, useContextMenu } from "./context-menu-items";

const vertex = `#version 300 es
in vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`;

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn("[shader-canvas] shader compile failed:", gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** Builds a program that draws one fragment shader over a fullscreen triangle. */
export function createFullscreenProgram(gl: WebGL2RenderingContext, fragment: string, uniformNames: string[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, vertex);
  const fs = compile(gl, gl.FRAGMENT_SHADER, fragment);
  if (!vs || !fs) {
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    return null;
  }

  const program = gl.createProgram();
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.warn("[shader-canvas] program link failed:", gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const location = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 0, 0);
  gl.useProgram(program);

  const uniforms: Record<string, WebGLUniformLocation | null> = Object.fromEntries(
    uniformNames.map((name) => [name, gl.getUniformLocation(program, name)]),
  );

  return { program, buffer, uniforms };
}

"use client";

import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import { mountContourField } from "./contour-runtime";

export type ContourFieldProps = {
  color?: string;
  density?: number;
  still?: boolean;
  speed?: number;
  interactive?: boolean;
  className?: string;
};

export function ContourField({ color = "var(--primary, #ff5a1f)", density = 1, still = false,
  speed = 1, interactive = true, className }: ContourFieldProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const field = useRef<ReturnType<typeof mountContourField>>(undefined);
  useEffect(() => {
    if (!canvas.current) return;
    field.current = mountContourField(canvas.current);
    return () => { field.current?.dispose(); field.current = undefined; };
  }, []);
  useEffect(() => {
    field.current?.update({ density: Number.isFinite(density) && density > 0 ? density : 1, still, speed, interactive });
  }, [density, still, speed, interactive, color]);
  return <canvas ref={canvas} aria-hidden="true" style={{ color }}
    className={cn("pointer-events-none block size-full", className)} />;
}

import { createFullscreenProgram } from "./contour-field-gl";
import { contourShader, uniforms } from "./contour-shader";

export function createContourRenderer(canvas: HTMLCanvasElement) {
  const gl = canvas.getContext("webgl2", { alpha: true, premultipliedAlpha: true, antialias: false });
  if (!gl) return;
  const setup = createFullscreenProgram(gl, contourShader, uniforms);
  if (!setup) return;
  const u = setup.uniforms;
  const pixel = document.createElement("canvas");
  pixel.width = pixel.height = 1;
  const palette = pixel.getContext("2d", { willReadFrequently: true });
  let lastColor = "";
  let lastForeground = "";
  const uploadColor = (location: WebGLUniformLocation | null, color: string) => {
    if (!palette) return;
    palette.clearRect(0, 0, 1, 1);
    palette.fillStyle = color;
    palette.fillRect(0, 0, 1, 1);
    const [r, g, b] = palette.getImageData(0, 0, 1, 1).data;
    gl.uniform3f(location, r / 255, g / 255, b / 255);
  };

  return {
    resize() {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
      const height = Math.max(1, Math.round(canvas.clientHeight * dpr));
      if (canvas.width !== width) canvas.width = width;
      if (canvas.height !== height) canvas.height = height;
      gl.viewport(0, 0, width, height);
      gl.uniform2f(u.u_res, width, height);
      gl.uniform1f(u.u_dpr, dpr);
    },
    refreshPalette() {
      const accent = getComputedStyle(canvas).color;
      const foreground = getComputedStyle(canvas.parentElement!).color;
      if (accent === lastColor && foreground === lastForeground) return false;
      lastColor = accent;
      lastForeground = foreground;
      uploadColor(u.u_accent, accent);
      uploadColor(u.u_fg, foreground);
      return true;
    },
    draw(time: number, density: number, x: number, y: number) {
      gl.uniform1f(u.u_time, time);
      gl.uniform1f(u.u_density, density);
      gl.uniform2f(u.u_mouse, x * canvas.width, y * canvas.height);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteBuffer(setup.buffer);
      gl.deleteProgram(setup.program);
    },
  };
}

import { createContourRenderer } from "./contour-renderer";

type Options = { density: number; still: boolean; speed: number; interactive: boolean };

export function mountContourField(canvas: HTMLCanvasElement) {
  const host = canvas.parentElement;
  if (!host) return;
  let renderer = createContourRenderer(canvas);
  const reduced = matchMedia("(prefers-reduced-motion: reduce)");
  const theme = matchMedia("(prefers-color-scheme: dark)");
  let options: Options;
  let inView = false;
  let frame = 0;
  let last = 0;
  let time = 6;
  // Normalized coordinates keep the frozen pointer influence stable on resize.
  const pointer = { x: -1, y: -1, targetX: -1, targetY: -1 };
  const frozen = () => options.still || reduced.matches;
  const visible = () => inView && !document.hidden;
  const stop = () => { cancelAnimationFrame(frame); frame = 0; };
  const draw = () => renderer?.draw(time, options.density, pointer.x, pointer.y);
  const tick = (now: number) => {
    time += Math.min(50, now - last) * options.speed / 1000;
    last = now;
    if (pointer.x < 0 || pointer.targetX < 0) {
      pointer.x = pointer.targetX;
      pointer.y = pointer.targetY;
    } else {
      pointer.x += (pointer.targetX - pointer.x) * 0.12;
      pointer.y += (pointer.targetY - pointer.y) * 0.12;
    }
    draw();
    frame = requestAnimationFrame(tick);
  };
  const refresh = () => {
    stop();
    if (!renderer || !options || !visible()) return;
    renderer.resize();
    renderer.refreshPalette();
    draw();
    if (!frozen()) {
      last = performance.now();
      frame = requestAnimationFrame(tick);
    }
  };
  const paletteChanged = () => {
    if (options && visible() && renderer?.refreshPalette() && frozen()) draw();
  };
  const leave = () => { pointer.targetX = pointer.targetY = -1; };
  const move = (event: PointerEvent) => {
    if (!options?.interactive || frozen() || !visible() || event.pointerType === "touch") return;
    const box = canvas.getBoundingClientRect();
    if (!box.width || !box.height || event.clientX < box.left || event.clientX > box.right ||
        event.clientY < box.top || event.clientY > box.bottom) { leave(); return; }
    pointer.targetX = (event.clientX - box.left) / box.width;
    pointer.targetY = 1 - (event.clientY - box.top) / box.height;
  };
  const lost = (event: Event) => { event.preventDefault(); stop(); renderer = undefined; };
  const restored = () => { renderer = createContourRenderer(canvas); refresh(); };
  const viewer = new IntersectionObserver(([entry]) => { inView = entry.isIntersecting; refresh(); });
  viewer.observe(canvas);
  const resize = new ResizeObserver(refresh);
  resize.observe(canvas);
  const colors = new MutationObserver(paletteChanged);
  for (let node: HTMLElement | null = canvas; node; node = node.parentElement) {
    colors.observe(node, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
  }
  host.addEventListener("pointermove", move, { passive: true });
  host.addEventListener("pointerleave", leave);
  document.addEventListener("visibilitychange", refresh);
  reduced.addEventListener("change", refresh);
  theme.addEventListener("change", paletteChanged);
  window.addEventListener("resize", refresh);
  canvas.addEventListener("webglcontextlost", lost);
  canvas.addEventListener("webglcontextrestored", restored);
  return {
    update(next: Options) {
      options = next;
      if (!next.interactive) { leave(); pointer.x = pointer.y = -1; }
      refresh();
    },
    dispose() {
      stop();
      viewer.disconnect();
      resize.disconnect();
      colors.disconnect();
      host.removeEventListener("pointermove", move);
      host.removeEventListener("pointerleave", leave);
      document.removeEventListener("visibilitychange", refresh);
      reduced.removeEventListener("change", refresh);
      theme.removeEventListener("change", paletteChanged);
      window.removeEventListener("resize", refresh);
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      renderer?.dispose();
    },
  };
}

export const uniforms = ["u_res", "u_time", "u_dpr", "u_mouse", "u_fg", "u_accent", "u_density"];

export const contourShader = /* glsl */ `#version 300 es
precision highp float;
uniform vec2 u_res;
uniform float u_time;
uniform float u_dpr;
uniform vec2 u_mouse;
uniform vec3 u_fg;
uniform vec3 u_accent;
uniform float u_density;
out vec4 outColor;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = m * p;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 p = (gl_FragCoord.xy - 0.5 * u_res) / u_res.y;
  float t = u_time * 0.03;
  float f = fbm(p * 1.2 + vec2(t, -t * 0.6)) + 0.3 * fbm(p * 2.4 - vec2(t * 0.8, t));
  float near = 0.0;
  if (u_mouse.x >= 0.0) {
    vec2 m = (u_mouse - 0.5 * u_res) / u_res.y;
    near = exp(-dot(p - m, p - m) / 0.018);
    f += 0.16 * near;
  }

  float v = f * 13.0 * u_density;
  float dl = min(fract(v), 1.0 - fract(v));
  float line = 1.0 - smoothstep(0.0, max(fwidth(v) * 1.1 * u_dpr, 0.00001), dl);
  float major = mod(floor(v + 0.5), 5.0) < 0.5 ? 1.0 : 0.0;
  float accent = max(major * 0.85, smoothstep(0.1, 0.6, near));

  float alpha = line * mix(0.1, 0.5, accent);
  vec3 col = mix(u_fg, u_accent, accent);
  outColor = vec4(col * alpha, alpha);
}
`;

"use client";

import { type DailyTask, useDailyTaskListContext } from "./daily-task-list-state";
import { type ReactNode } from "react";
import { Checkbox } from "@base-ui/react/checkbox";
import { cn } from "@/lib/utils";
import { useSortableList } from "@/components/ui/sortable-list";
import { ContextMenu, ContextMenuTarget, ContextMenuButton, ContextMenuContent, ContextMenuItem, ContextMenuSeparator } from "@/components/ui/context-menu";

export type RowOptions = {
  /** Extra content under each title, such as a time or tag. */
  renderMeta?: (task: DailyTask) => ReactNode;
  /** Extra menu items for each task, rendered after the built-in actions. */
  renderActions?: (task: DailyTask) => ReactNode;
  classNames?: { item?: string; row?: string; checkbox?: string; title?: string; menu?: string; menuItem?: string; menuHighlight?: string };
};

/** How long the strike line takes to cross a title before the task moves to Completed. */
export const STRIKE_MS = 320;

export function TaskCheckbox({ task, className }: { task: DailyTask; className?: string }) {
  const { toggle, busy, striking, disabled, animated, messages } = useDailyTaskListContext("DailyTaskList");
  return (
    <Checkbox.Root
      // Shown as checked while the strike plays; it reverts if the app's save fails.
      checked={task.done || striking.has(task.id)}
      onCheckedChange={() => toggle(task)}
      // A save in flight blocks another click in toggle(), without dimming the row before it moves.
      disabled={disabled}
      aria-label={task.done ? `${messages.reopen} ${task.title}` : task.title}
      aria-busy={busy.has(task.id) || undefined}
      className={cn(
        "group grid size-5 shrink-0 place-items-center rounded-[5px] border border-input bg-background shadow-xs outline-none focus-visible:ring-1 focus-visible:ring-ring data-[checked]:border-primary data-[checked]:bg-primary data-[checked]:text-primary-foreground data-[disabled]:opacity-50",
        className,
      )}
    >
      <Checkbox.Indicator keepMounted>
        <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.25" strokeLinecap="round" strokeLinejoin="round" className="size-3.5">
          {/* The tick draws itself in when checked. */}
          <path
            d="M3.5 8.5l3 3 6-7"
            pathLength={1}
            className={cn(
              "[stroke-dasharray:1] [stroke-dashoffset:1] group-data-[checked]:[stroke-dashoffset:0]",
              animated && "transition-[stroke-dashoffset] duration-200 ease-out motion-reduce:transition-none",
            )}
          />
        </svg>
      </Checkbox.Indicator>
    </Checkbox.Root>
  );
}

export function TaskMenu({ task, index, count, options, children }: { task: DailyTask; index: number; count: number; options: RowOptions; children: ReactNode }) {
  const { messages, disabled, busy, rename, reorder, remove, toggle, setRenamingId, renamingId, animated, portal } = useDailyTaskListContext("DailyTaskList");
  const { move } = useSortableList<DailyTask>();
  const blocked = disabled || busy.has(task.id);
  const item = options.classNames?.menuItem;
  return (
    <ContextMenu disabled={blocked || renamingId === task.id} motion={animated}>
      <ContextMenuTarget className={cn("flex min-w-0 flex-1 items-center gap-2.5", options.classNames?.row)}>
        {children}
        {/* Locked while its save is in flight, without dimming the row before it moves. */}
        <ContextMenuButton aria-label={messages.actions(task.title)} className={cn(busy.has(task.id) && !disabled && "disabled:opacity-100")} />
      </ContextMenuTarget>
      <ContextMenuContent container={portal} className={options.classNames?.menu} highlightClassName={options.classNames?.menuHighlight}>
        {task.done ? (
          <ContextMenuItem className={item} onClick={() => toggle(task)}>
            {messages.reopen}
          </ContextMenuItem>
        ) : (
          rename && (
            <ContextMenuItem className={item} onClick={() => setRenamingId(task.id)}>
              {messages.rename}
            </ContextMenuItem>
          )
        )}
        {reorder && (
          <>
            <ContextMenuItem className={item} disabled={index === 0} onClick={() => move(task.id, index - 1)}>
              {messages.moveUp}
            </ContextMenuItem>
            <ContextMenuItem className={item} disabled={index === count - 1} onClick={() => move(task.id, index + 1)}>
              {messages.moveDown}
            </ContextMenuItem>
          </>
        )}
        {options.renderActions?.(task)}
        <ContextMenuSeparator />
        <ContextMenuItem className={item} variant="destructive" onClick={() => remove(task)}>
          {messages.delete}
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

