  const listId = useId();
  const expanded = showAll || hover || readingCards;
  const limit = Math.max(1, Math.trunc(visible) || 1);
  const shown = showAll ? [...items] : items.slice(-limit);
  if (position === "top") shown.reverse();
  const heights = useCardHeights(list, items, shown.length);
  const layout = notificationLayout(shown, heights, expanded, position);

  function dismissCard(id: string, index: number) {
    const buttons = list.current?.querySelectorAll<HTMLButtonElement>("li:not([aria-hidden=true]) button");
    if (buttons?.[index]?.contains(document.activeElement)) {
      (buttons[index + 1] ?? buttons[index - 1] ?? region.current)?.focus();
    }
    onDismiss(id);
  }

  function left(event: FocusEvent<HTMLElement>) {
    return !event.currentTarget.contains(event.relatedTarget);
  }

  return <section ref={region} aria-label="Notifications" tabIndex={-1}
    className={cn("flex h-80 w-full min-w-0 flex-col justify-end text-foreground [overflow-anchor:none]", className)}
    onFocusCapture={() => setFocus(true)} onBlurCapture={event => { if (left(event)) setFocus(false); }}>
    {items.map(item => <NotificationTimer key={item.id} id={item.id} duration={item.duration ?? duration}
      paused={focus || hover} onDismiss={onDismiss} />)}
    {(["polite", "assertive"] as const).map(priority => <div key={priority} aria-live={priority}
      aria-relevant="additions" aria-atomic="false" className="sr-only">
      {items.filter(item => (item.tone === "error") === (priority === "assertive")).map(item =>
        <p key={item.id}>{item.title}{item.description && `. ${item.description}`}</p>)}
    </div>)}
    {items.length === 0 && <div className="grid justify-items-center gap-2 py-6 text-sm text-muted-foreground">
      <span aria-hidden="true" className="grid size-9 place-items-center rounded-full bg-muted">{emptyIcon ?? <Bell className="size-4" />}</span>
      All caught up.
    </div>}
    <div className={cn("relative min-h-0", items.length > 0 && "flex-1")}>
      <div className={cn("pointer-events-none absolute inset-x-0 -bottom-6 z-10 flex h-[var(--notification-window-height,calc(75dvh+1.5rem))] [overflow-x:var(--notification-overflow,hidden)] [overflow-y:var(--notification-overflow,auto)] overscroll-contain pb-6 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
        position === "bottom" ? "flex-col-reverse" : "flex-col")}>
        <ol ref={list} id={listId} aria-label="Notification list" onFocusCapture={() => setReadingCards(true)}
          onPointerEnter={event => { if (event.pointerType !== "touch") setHover(true); }}
          onPointerLeave={() => setHover(false)}
          onBlurCapture={event => { if (left(event)) setReadingCards(false); }}
          className={cn("pointer-events-auto relative isolate shrink-0", position === "top" && "mt-auto")} style={{ height: layout.height + 8 }}>
          <AnimatePresence initial={false}>
            {shown.map((item, index) => <NotificationCard key={item.id} item={item} offset={layout.offsets.get(item.id)!}
              layer={position === "top" ? shown.length - index : index + 1} position={position}
              depth={expanded ? 0 : position === "top" ? index : shown.length - 1 - index}
              motion={motion} className={cardClassName} dismiss={() => dismissCard(item.id, index)} />)}
          </AnimatePresence>
        </ol>
      </div>
    </div>
    {items.length > 1 && <button type="button" aria-controls={listId} aria-expanded={showAll}
      onClick={() => setShowAll(value => !value)}
      className="mx-auto mt-2 flex h-8 min-w-28 shrink-0 items-center justify-center gap-1 rounded-md px-2 text-xs font-medium text-muted-foreground hover:bg-muted focus-visible:bg-muted">
      {showAll ? <>Show less <ChevronUp aria-hidden="true" className="size-3.5" /></> :
        <>Show all {items.length} <ChevronDown aria-hidden="true" className="size-3.5" /></>}
    </button>}
  </section>;
}

"use client";

import { useEffect, useRef } from "react";

/** Keep a clock for each queued item, including ones outside the compact view. */
export function NotificationTimer({ id, duration, paused, onDismiss }: {
  id: string; duration: number; paused: boolean; onDismiss: (id: string) => void;
}) {
  const remaining = useRef(duration);
  const dismiss = useRef(onDismiss);
  useEffect(() => { dismiss.current = onDismiss; }, [onDismiss]);
  useEffect(() => { remaining.current = duration; }, [duration]);
  useEffect(() => {
    if (paused || !Number.isFinite(duration) || duration <= 0) return;
    const start = Date.now();
    const timer = setTimeout(() => dismiss.current(id), remaining.current);
    return () => {
      clearTimeout(timer);
      remaining.current = Math.max(0, remaining.current - (Date.now() - start));
    };
  }, [id, duration, paused]);
  return null;
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { usePointerAdjust } from "./number-field-scrub";
import { handleTypingKeys, mergeRefs, useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/** The visible label. Clicking it focuses the input. */
export const NumberFieldLabel = forwardRef<HTMLLabelElement, ComponentPropsWithoutRef<"label">>(function NumberFieldLabel(
  { className, children, ...props },
  ref,
) {
  const { label, labelId, inputId } = useNumberField();
  return (
    <label ref={ref} id={labelId} htmlFor={inputId} data-slot="label" className={cn("text-xs text-muted-foreground select-none", className)} {...props}>
      {children ?? label}
    </label>
  );
});

/**
 * The field's box: holds the input, unit and stepper, and shows focus and invalid states
 * for all of them. Pressing anywhere in it focuses the input.
 */
export const NumberFieldGroup = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function NumberFieldGroup(
  { className, onMouseDown, ...props },
  ref,
) {
  const { inputRef, stepperLayout } = useNumberField();
  return (
    <div
      ref={ref}
      data-slot="group"
      data-layout={stepperLayout}
      className={cn(
        "group/numeric flex h-[var(--uicoolkit-field-height,2.5rem)] min-w-0 flex-1 items-stretch overflow-hidden rounded-md border border-[color:var(--uicoolkit-field-border,var(--input))] bg-[var(--uicoolkit-field-bg,transparent)] shadow-[var(--uicoolkit-field-shadow,0_1px_2px_0_rgb(0_0_0/0.05))] focus-within:border-ring has-[input:disabled]:opacity-50 has-[input[aria-invalid=true]]:border-destructive has-[input[aria-invalid=true]]:ring-destructive/20",
        className,
      )}
      onMouseDown={(event) => {
        onMouseDown?.(event);
        const target = event.target as HTMLElement;
        if (event.defaultPrevented || target.closest("input, button")) return;
        event.preventDefault();
        inputRef.current?.focus();
      }}
      {...props}
    />
  );
});

type InputProps = Omit<ComponentPropsWithoutRef<"input">, "value" | "defaultValue" | "type"> & {
  /**
   * Drag left or right over the number to adjust it, as over the label (the default). A click without
   * moving still starts typing; while typing, the pointer selects text as usual. Set false to turn it off.
   */
  scrub?: boolean;
};

/** A text input that behaves as a spin button: type and press Enter, or step with the arrow keys. Place it in NumberFieldGroup. */
export const NumberFieldInput = forwardRef<HTMLInputElement, InputProps>(function NumberFieldInput(
  { className, onChange, onKeyDown, onFocus, onBlur, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onMouseDown, scrub = true, ...props },
  ref,
) {
  const field = useNumberField();
  const adjust = usePointerAdjust({
    valueAt: (start, dx, _width, event) => start + Math.round(dx / field.sensitivity) * (event.shiftKey ? field.largeStep : field.step),
    onTap: () => field.inputRef.current?.focus(),
  });
  const unitShown = !!field.unit && !(field.display === null && field.draft === null);
  // Only an idle number is a drag handle; once focused, the input edits text.
  const idle = (target: EventTarget) => scrub && !field.disabled && !field.readOnly && document.activeElement !== target;
  return (
    <input
      ref={mergeRefs(ref, field.inputRef)}
      id={field.inputId}
      type="text"
      inputMode="decimal"
      autoComplete="off"
      spellCheck={false}
      role="spinbutton"
      aria-label={field.label}
      aria-valuenow={field.display ?? undefined}
      aria-valuemin={field.min}
      aria-valuemax={field.max}
      aria-valuetext={field.valueText}
      aria-invalid={field.error ? true : undefined}
      aria-describedby={field.error ? field.errorId : undefined}
      disabled={field.disabled}
      readOnly={field.readOnly}
      placeholder={field.placeholder}
      className={cn(
        // Numbers line up on the right, next to their unit; the group draws the box.
        "w-full min-w-0 flex-1 bg-transparent pl-2 text-right text-sm tabular-nums outline-none placeholder:text-muted-foreground",
        // A shown unit supplies the gap before the stepper; without one ("Mixed", or no unit) the input keeps the same gap.
        unitShown ? "pr-1" : "pr-2",
        scrub && !field.disabled && !field.readOnly && field.adjustFrom !== null && "touch-pan-y not-focus:cursor-ew-resize",
        className,
      )}
      {...props}
      value={field.draft ?? field.text}
      onMouseDown={(event) => {
        onMouseDown?.(event);
        // Keep an idle number from taking focus or selecting text on press; a tap focuses it on release.
        if (!event.defaultPrevented && event.button === 0 && idle(event.currentTarget)) event.preventDefault();
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.defaultPrevented || !idle(event.currentTarget)) return;
        if (event.pointerType === "mouse") event.preventDefault();
        adjust.onPointerDown(event);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        adjust.onPointerMove(event);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        adjust.onPointerUp(event);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        adjust.onPointerCancel(event);
      }}
      onFocus={(event) => {
        onFocus?.(event);
        const input = event.currentTarget;
        // An empty value can still stand for something to edit, such as a merged field's list.
        if (field.draft === null && field.display === null && field.editText && !field.readOnly) {
          field.setDraft(field.editText);
          // Focus updates render before microtasks run, so this selects the prefilled text before any typing.
          queueMicrotask(() => input.select());
        } else input.select();
      }}
      onChange={(event) => {
        onChange?.(event);
        if (!event.defaultPrevented) field.setDraft(event.target.value);
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (!event.defaultPrevented) handleTypingKeys(event, field);
      }}
      onBlur={(event) => {
        onBlur?.(event);
        // An invalid draft stays in the field with its message until it is fixed or reverted.
        field.submitDraft();
      }}
    />
  );
});

/** The unit after the value. Hidden from assistive technology, which reads it in the value text. */
export const NumberFieldUnit = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function NumberFieldUnit(
  { className, children, ...props },
  ref,
) {
  const { unit, display, draft } = useNumberField();
  // A placeholder such as "Mixed" reads on its own.
  if ((!unit && !children) || (display === null && draft === null)) return null;
  return (
    <span ref={ref} aria-hidden className={cn("flex items-center pr-2 text-xs text-muted-foreground select-none", className)} {...props}>
      {children ?? unit}
    </span>
  );
});

/** The validation message for a rejected typed value. */
export const NumberFieldError = forwardRef<HTMLParagraphElement, ComponentPropsWithoutRef<"p">>(function NumberFieldError(
  { className, children, ...props },
  ref,
) {
  const { error, errorId } = useNumberField();
  if (!error) return null;
  return (
    <p ref={ref} id={errorId} data-slot="error" role="alert" className={cn("basis-full text-xs text-destructive", className)} {...props}>
      {children ?? error}
    </p>
  );
});

"use client";

import { Select } from "@base-ui/react/select";
import { useRef, useState, useSyncExternalStore } from "react";
import { useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

const phoneQuery = "(max-width: 639px)";
const subscribe = (notify: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const media = window.matchMedia(phoneQuery);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
/** Phones get a bottom sheet; the server renders the desktop popup, then adapts. */
const usePhone = () =>
  useSyncExternalStore(subscribe, () => typeof window.matchMedia === "function" && window.matchMedia(phoneQuery).matches, () => false);

/** The menu's value for a plain number. */
const fixed = "__fixed";

type KeywordMenuProps = {
  className?: string;
  /** Class for the popup (or the bottom sheet on phones). */
  popupClassName?: string;
  /** Class for each option. Highlighted options have data-highlighted; the chosen one data-selected. */
  itemClassName?: string;
  /** For narrow fields, such as a design tool's grid: Fixed shows only the arrow, leaving room for the number. Keywords still show. */
  compact?: boolean;
};

/**
 * Picks Fixed or one of the field's keywords, at the end of NumberFieldGroup; the menu opens at the field's width. It shows the current
 * mode, except for a keyword the input already spells out (Auto). Fixed keeps the shown number.
 */
export function NumberFieldKeywordMenu({ className, popupClassName, itemClassName, compact = false }: KeywordMenuProps) {
  const field = useNumberField();
  const phone = usePhone();
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement | null>(null);
  const blocked = field.readOnly || field.disabled;
  const options = [{ value: fixed, label: field.messages.fixed }, ...field.keywords.map((keyword) => ({ value: keyword.value, label: keyword.label }))];
  const current = field.keyword ? field.keyword.value : field.value !== null ? fixed : null;
  // A keyword without a number already reads in the input, so the trigger shows only its arrow.
  const shown =
    (field.keyword && field.display === null && field.draft === null) || (compact && current === fixed) ? null : (options.find((option) => option.value === current)?.label ?? null);

  return (
    <Select.Root
      items={options}
      value={current}
      onValueChange={(next) => {
        if (next === null || next === current) return;
        field.setKeyword(next === fixed ? null : (next as string));
      }}
      disabled={field.disabled}
      readOnly={field.readOnly}
      open={open && !blocked}
      onOpenChange={(next) => setOpen(next && !blocked)}
    >
      <Select.Trigger
        ref={trigger}
        aria-label={field.messages.mode(field.label)}
        data-slot="keyword"
        className={cn(
          "flex shrink-0 items-center gap-1.5 self-stretch text-sm",
          compact ? "pr-2 pl-0.5" : "pr-2.5 pl-1.5",
          "text-muted-foreground outline-none select-none hover:text-foreground focus-visible:text-foreground data-[popup-open]:text-foreground data-[readonly]:pointer-events-none",
          className,
        )}
      >
        {shown && <span>{shown}</span>}
        {!blocked && (
          <svg aria-hidden viewBox="0 0 10 6" className="h-1.5 w-2.5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M1.5 1.25 5 4.75l3.5-3.5" />
          </svg>
        )}
      </Select.Trigger>
      <Select.Portal container={field.container ?? undefined}>
        {phone && <Select.Backdrop className="fixed inset-0 z-50 bg-black/40" />}
        <Select.Positioner
          // The menu opens under the whole field, at its width, not under the small trigger. A host whose
          // visible box is larger, such as a row with its label inside, marks that box data-menu-anchor.
          anchor={() => trigger.current?.closest<HTMLElement>("[data-menu-anchor]") ?? trigger.current?.closest<HTMLElement>('[data-slot="group"]') ?? trigger.current}
          alignItemWithTrigger={false}
          side="bottom"
          align="start"
          sideOffset={6}
          positionMethod="fixed"
          className="z-50 outline-none"
          style={phone ? { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } : undefined}
        >
          <Select.Popup
            className={cn(
              // At least the field's width, wider only if an option needs it.
              "max-h-[var(--available-height)] w-max min-w-[var(--anchor-width)] overflow-y-auto rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md outline-none",
              phone && "max-h-[80dvh] w-full rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
              field.animated &&
                (phone
                  ? "transition-[transform,opacity] duration-200 ease-out data-[ending-style]:translate-y-full data-[starting-style]:translate-y-full motion-reduce:transition-none"
                  : "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 ease-out data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none"),
              popupClassName,
            )}
          >
            <Select.List>
              {options.map((option) => (
                <Select.Item
                  key={option.value}
                  value={option.value}
                  className={cn(
                    "flex min-h-8 cursor-pointer items-center justify-between gap-3 rounded-sm px-2 text-sm outline-none select-none data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground",
                    phone && "min-h-11",
                    itemClassName,
                  )}
                >
                  <Select.ItemText>{option.label}</Select.ItemText>
                  <Select.ItemIndicator data-slot="check">
                    <svg aria-hidden viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round">
                      <path d="m3.5 8.5 3 3 6-7" />
                    </svg>
                  </Select.ItemIndicator>
                </Select.Item>
              ))}
            </Select.List>
          </Select.Popup>
        </Select.Positioner>
      </Select.Portal>
    </Select.Root>
  );
}

"use client";

import { type ReactElement, type RefAttributes, forwardRef, useId, useRef, useState } from "react";
import { type NumberFieldContextValue, type NumberFieldProps, NumberFieldContext, decimalsOf, defaultMessages } from "./number-field-state";
import { cn } from "@/lib/utils";

const NumberFieldRoot = forwardRef<HTMLDivElement, NumberFieldProps<string>>(function NumberField(
  {
    value,
    onValueCommit,
    onValueChange,
    label,
    min,
    max,
    step = 1,
    largeStep = step * 10,
    precision = decimalsOf(step),
    unit,
    format,
    parse,
    validate,
    placeholder,
    disabled = false,
    readOnly = false,
    sensitivity = 4,
    motion = true,
    stepperLayout = "auto",
    keywords = [],
    keywordFallback,
    container,
    submitText,
    editText,
    messages: messagesProp,
    className,
    ...props
  },
  ref,
) {
  const [preview, setPreview] = useState<number | null>(null);
  const [draft, setDraftValue] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);
  // Pointer events can arrive faster than renders, so the drag reads its latest value here.
  const live = useRef<number | null>(null);
  // Mirrors the draft so a blur that follows Enter, Escape or a step cannot commit it twice.
  const draftRef = useRef<string | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const sliderRef = useRef<HTMLDivElement | null>(null);
  const id = useId();
  const messages = { ...defaultMessages, ...messagesProp };
  const locked = disabled || readOnly;

  const normalize = (next: number) => Math.min(max ?? Infinity, Math.max(min ?? -Infinity, Number(next.toFixed(precision))));
  const formatValue = (next: number) => (format ? format(next) : next.toFixed(precision));
  const parseText = (text: string) => {
    if (parse) return parse(text);
    let cleaned = text.trim().replace(/−/g, "-");
    if (unit && cleaned.endsWith(unit)) cleaned = cleaned.slice(0, -unit.length).trim();
    return cleaned === "" ? NaN : Number(cleaned);
  };

  const setDraftState = (next: string | null) => {
    draftRef.current = next;
    setDraftValue(next);
  };

  // A keyword stands in for the number; one with a resolved size still shows that size.
  const number = typeof value === "number" ? value : null;
  const keyword = typeof value === "string" ? (keywords.find((item) => item.value === value) ?? null) : null;
  const display = preview ?? number ?? keyword?.resolved ?? null;
  const text = display !== null ? formatValue(display) : keyword ? keyword.label : "";
  const adjustFrom = display ?? (keyword ? (keywordFallback ?? min ?? 0) : null);
  const keywordFor = (typed: string) => {
    const name = typed.trim().toLowerCase();
    return keywords.find((item) => item.label.toLowerCase() === name || item.value.toLowerCase() === name) ?? null;
  };

  const commit = (next: number) => {
    const normalized = normalize(next);
    live.current = null;
    setPreview(null);
    if (normalized === value) return;
    onValueChange?.(normalized);
    onValueCommit(normalized);
  };

  const commitKeyword = (next: string) => {
    live.current = null;
    setPreview(null);
    if (next === value) return;
    onValueChange?.(next);
    onValueCommit(next);
  };

  const cancelDraft = () => {
    setDraftState(null);
    setError(null);
  };

  const submitDraft = () => {
    const draft = draftRef.current;
    if (draft === null) return true;
    // Clearing the text reverts rather than committing an empty value.
    if (draft.trim() === "") {
      cancelDraft();
      return true;
    }
    // The host reads its own forms first, such as a list of values.
    const handled = submitText?.(draft);
    if (handled === true) {
      cancelDraft();
      return true;
    }
    if (typeof handled === "string") {
      setError(handled);
      return false;
    }
    // A keyword's name selects it, such as "auto".
    const typedKeyword = keywordFor(draft);
    if (typedKeyword) {
      cancelDraft();
      commitKeyword(typedKeyword.value);
      return true;
    }
    const parsed = parseText(draft);
    if (!Number.isFinite(parsed)) {
      setError(messages.invalid);
      return false;
    }
    // Typed values outside the limits are rejected rather than silently clamped.
    const rounded = Number(parsed.toFixed(precision));
    // Symbol units such as % and ° attach to the number; word units such as px take a space.
    const withUnit = (limit: number) => (!unit ? formatValue(limit) : /^[%°′″]$/.test(unit) ? `${formatValue(limit)}${unit}` : `${formatValue(limit)} ${unit}`);
    if (min !== undefined && rounded < min) {
      setError(messages.tooLow.replace("{min}", withUnit(min)));
      return false;
    }
    if (max !== undefined && rounded > max) {
      setError(messages.tooHigh.replace("{max}", withUnit(max)));
      return false;
    }
    const normalized = normalize(rounded);
    const message = validate?.(normalized);
    if (message) {
      setError(message);
      return false;
    }
    cancelDraft();
    commit(normalized);
    return true;
  };

  const stepBy = (steps: number, large = false) => {
    if (locked) return;
    const typed = draftRef.current === null ? NaN : parseText(draftRef.current);
    // Stepping a keyword turns it into a number, from its resolved size or the fallback.
    const base = Number.isFinite(typed) ? typed : adjustFrom;
    // A mixed value has no common base to step from; typing sets one.
    if (base === null) return;
    cancelDraft();
    commit(base + steps * (large ? largeStep : step));
  };

  const cancelDrag = () => {
    live.current = null;
    setPreview(null);
    setDragging(false);
    if (value !== null) onValueChange?.(value);
  };

  const context: NumberFieldContextValue = {
    label,
    value: number,
    keyword,
    keywords,
    adjustFrom,
    setKeyword: (next) => {
      if (locked) return;
      cancelDraft();
      if (next !== null) commitKeyword(next);
      else if (adjustFrom !== null) commit(adjustFrom);
    },
    container,
    editText,
    display,
    text,
    valueText:
      display === null
        ? (keyword?.label ?? placeholder)
        : `${unit ? `${text} ${unit}` : text}${keyword ? `, ${keyword.label}` : ""}`,
    unit,
    min,
    max,
    step,
    largeStep,
    sensitivity,
    placeholder,
    disabled,
    readOnly,
    animated: motion,
    stepperLayout,
    dragging,
    draft,
    error,
    messages,
    inputId: `${id}-input`,
    labelId: `${id}-label`,
    errorId: `${id}-error`,
    inputRef,
    sliderRef,
    setDraft: (next) => {
      setDraftState(next);
      if (error) setError(null);
    },
    beginTyping: () => !locked && setDraftState(text),
    submitDraft,
    cancelDraft,
    stepBy,
    commit: (next) => !locked && commit(next),
    beginDrag: () => {
      if (locked || adjustFrom === null) return null;
      cancelDraft();
      setDragging(true);
      return adjustFrom;
    },
    dragTo: (next) => {
      const normalized = normalize(next);
      if (normalized === live.current) return;
      live.current = normalized;
      setPreview(normalized);
      onValueChange?.(normalized);
    },
    endDrag: () => {
      setDragging(false);
      if (live.current === null) return;
      commit(live.current);
    },
    cancelDrag,
  };

  return (
    <NumberFieldContext.Provider value={context}>
      <div
        ref={ref}
        data-dragging={dragging || undefined}
        data-typing={draft !== null || undefined}
        data-invalid={error ? true : undefined}
        data-empty={display === null || undefined}
        data-disabled={disabled || undefined}
        data-readonly={readOnly || undefined}
        className={cn("flex flex-wrap items-center gap-x-2 gap-y-1", className)}
        {...props}
      />
    </NumberFieldContext.Provider>
  );
});

/**
 * A number your app owns, typed, stepped or dragged. With `keywords`, it can also hold a named value
 * such as Auto or Hug; the value's type then widens to include them.
 */
export const NumberField = NumberFieldRoot as <K extends string = never>(props: NumberFieldProps<K> & RefAttributes<HTMLDivElement>) => ReactElement | null;

"use client";

import { type ComponentPropsWithoutRef, type PointerEvent, forwardRef, useEffect, useRef } from "react";
import { useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/** Pointer travel before a press becomes a drag, so a click or tap still works. */
const threshold = 3;

type Gesture = { pointerId: number; x: number; width: number; start: number | null; moved: boolean };

/**
 * Turns a horizontal drag on an element into live values and one commit on release.
 * `valueAt` maps the start value and pointer travel to the next value. A press without
 * movement calls `onTap`. Escape or a cancelled pointer restores the committed value.
 */
export function usePointerAdjust({ valueAt, onTap }: { valueAt: (start: number, dx: number, width: number, event: PointerEvent<HTMLElement>) => number; onTap?: () => void }) {
  const field = useNumberField();
  const gesture = useRef<Gesture | null>(null);
  const cancelDrag = field.cancelDrag;

  useEffect(() => {
    if (!field.dragging) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || !gesture.current) return;
      event.preventDefault();
      event.stopPropagation();
      gesture.current = null;
      cancelDrag();
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [field.dragging, cancelDrag]);

  const finish = (event: PointerEvent<HTMLElement>, cancelled: boolean) => {
    const current = gesture.current;
    if (!current || current.pointerId !== event.pointerId) return;
    gesture.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    if (current.moved) {
      if (cancelled) field.cancelDrag();
      else field.endDrag();
    } else if (!cancelled) onTap?.();
  };

  return {
    onPointerDown: (event: PointerEvent<HTMLElement>) => {
      if (event.button !== 0 || field.disabled || field.readOnly || field.draft !== null) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      const width = event.currentTarget.getBoundingClientRect().width;
      gesture.current = { pointerId: event.pointerId, x: event.clientX, width, start: field.adjustFrom, moved: false };
    },
    onPointerMove: (event: PointerEvent<HTMLElement>) => {
      const current = gesture.current;
      if (!current || current.pointerId !== event.pointerId || current.start === null) return;
      const dx = event.clientX - current.x;
      if (!current.moved) {
        if (Math.abs(dx) < threshold) return;
        current.moved = true;
        field.beginDrag();
      }
      field.dragTo(valueAt(current.start, dx, current.width, event));
    },
    onPointerUp: (event: PointerEvent<HTMLElement>) => finish(event, false),
    // Fired when the browser takes over, such as a vertical scroll on touch.
    onPointerCancel: (event: PointerEvent<HTMLElement>) => finish(event, true),
  };
}

/**
 * Drag left or right over this area to adjust the value, usually around the label.
 * Each `sensitivity` pixels is one step; hold Shift for large steps. A click focuses the input.
 */
export const NumberFieldScrubArea = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function NumberFieldScrubArea(
  { className, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, ...props },
  ref,
) {
  const field = useNumberField();
  const adjust = usePointerAdjust({
    valueAt: (start, dx, _width, event) => start + Math.round(dx / field.sensitivity) * (event.shiftKey ? field.largeStep : field.step),
    onTap: () => field.inputRef.current?.focus(),
  });
  const locked = field.disabled || field.readOnly || field.adjustFrom === null;
  return (
    <span
      ref={ref}
      data-slot="scrub"
      data-dragging={field.dragging || undefined}
      className={cn("inline-flex touch-pan-y items-center select-none", !locked && "cursor-ew-resize", className)}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (!event.defaultPrevented) adjust.onPointerDown(event);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        adjust.onPointerMove(event);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        adjust.onPointerUp(event);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        adjust.onPointerCancel(event);
      }}
      {...props}
    />
  );
});

"use client";

import { type ComponentPropsWithoutRef, forwardRef, useEffect, useLayoutEffect, useRef, useState } from "react";
import { useNumberFieldSlider } from "./number-field-slider";
import { mergeRefs, useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/*
 * Shared geometry: the thumb's centre travels from 8px to (100% - 8px), and the fill ends
 * 6px past it so the thumb sits inside the fill's rounded end. Step marks use the same track.
 */
const thumbAt = "calc(8px + (100% - 16px) * var(--number-field-progress))";
const fillTo = "calc(14px + (100% - 16px) * var(--number-field-progress))";
/** More marks than this would read as texture, so large steps or none are shown instead. */
const maxMarks = 40;
/** Room kept between the thumb and the label or value text, in pixels. */
const textClearance = 6;

const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Steps glide; a drag follows the pointer exactly. */
function useGlide(property: string) {
  const { animated, dragging } = useNumberField();
  return animated && !dragging && `${property} duration-150 ease-out motion-reduce:transition-none`;
}

/** The filled part of the slider row, rounded at its end, sized to the value. */
export const NumberFieldSliderFill = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function NumberFieldSliderFill(
  { className, style, ...props },
  ref,
) {
  const { display } = useNumberField();
  const glide = useGlide("transition-[width]");
  return (
    <span
      ref={ref}
      aria-hidden
      className={cn("pointer-events-none absolute inset-y-0 left-0 -z-10 rounded-[inherit] bg-foreground/10", glide, className)}
      style={{ width: display === null ? 0 : fillTo, ...style }}
      {...props}
    />
  );
});

/**
 * A small handle inside the end of the fill. It grows slightly while dragging, and fades out
 * where it would run under the label or value (parts marked data-slot="label" or "value").
 * Hidden when read-only.
 */
export const NumberFieldSliderThumb = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function NumberFieldSliderThumb(
  { className, style, ...props },
  ref,
) {
  const { display, dragging, animated, readOnly } = useNumberField();
  const { progress } = useNumberFieldSlider();
  const [covered, setCovered] = useState(false);
  const own = useRef<HTMLSpanElement | null>(null);
  const glide = useGlide("transition-[left,scale,opacity]");

  // Measured after every render: the value text changes width as the number changes.
  useIsomorphicLayoutEffect(() => {
    // The thumb's own node is attached by now; the slider's merged ref may not be yet.
    const slider = own.current?.closest<HTMLElement>('[data-slot="slider"]');
    if (!slider) return;
    const box = slider.getBoundingClientRect();
    const x = box.left + 8 + (box.width - 16) * progress;
    const text = slider.querySelectorAll<HTMLElement>('[data-slot="label"], [data-slot="value"]');
    setCovered(
      Array.from(text).some((element) => {
        const rect = element.getBoundingClientRect();
        return rect.width > 0 && x > rect.left - textClearance && x < rect.right + textClearance;
      }),
    );
  });

  // A read-only value has nothing to grab, so the fill alone shows it.
  if (display === null || readOnly) return null;
  return (
    <span
      ref={mergeRefs(ref, own)}
      aria-hidden
      data-dragging={dragging || undefined}
      data-covered={covered || undefined}
      className={cn(
        "pointer-events-none absolute top-1/2 -z-10 h-4 w-1 -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground/45 data-covered:opacity-0 data-dragging:scale-y-110 data-dragging:bg-foreground/70",
        glide,
        animated && dragging && "transition-[scale,opacity] duration-150 motion-reduce:transition-none",
        className,
      )}
      style={{ left: thumbAt, ...style }}
      {...props}
    />
  );
});

type StepsProps = ComponentPropsWithoutRef<"span"> & {
  /** Class for each mark. Marks under the fill have data-filled. */
  markClassName?: string;
};

/** Step marks along the bottom of the track that fade in while dragging or stepping with keys. */
export const NumberFieldSliderSteps = forwardRef<HTMLSpanElement, StepsProps>(function NumberFieldSliderSteps(
  { className, markClassName, ...props },
  ref,
) {
  const { min = 0, max = 100, step, largeStep, animated } = useNumberField();
  const { progress, adjusting } = useNumberFieldSlider();
  const range = max - min;
  const interval = range / step <= maxMarks ? step : largeStep;
  const count = range > 0 ? Math.round(range / interval) : 0;
  if (count < 1 || count > maxMarks) return null;
  const marks = Array.from({ length: count + 1 }, (_, index) => Math.min(1, (index * interval) / range));
  return (
    <span
      ref={ref}
      aria-hidden
      data-visible={adjusting || undefined}
      className={cn(
        "pointer-events-none absolute inset-0 -z-10 opacity-0 data-visible:opacity-100",
        animated && "transition-opacity duration-200 motion-reduce:transition-none",
        className,
      )}
      {...props}
    >
      {marks.map((at) => (
        <span
          key={at}
          data-filled={at <= progress || undefined}
          // Along the bottom edge, like a ruler, so the marks stay clear of the label and value.
          className={cn("absolute bottom-[3px] h-1.5 w-0.5 -translate-x-1/2 rounded-full bg-foreground/20 data-filled:bg-foreground/35", markClassName)}
          style={{ left: `calc(8px + (100% - 16px) * ${at})` }}
        />
      ))}
    </span>
  );
});

"use client";

import { type CSSProperties, type ComponentPropsWithoutRef, createContext, forwardRef, useContext, useEffect, useRef, useState } from "react";
import { usePointerAdjust } from "./number-field-scrub";
import { mergeRefs, useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/** How long step marks stay after a key press. */
const keyStepLinger = 700;

type SliderContextValue = {
  /** Where the value sits between min and max, from 0 to 1. */
  progress: number;
  /** True while dragging or stepping with keys; step marks show then. */
  adjusting: boolean;
};

const SliderContext = createContext<SliderContextValue | null>(null);

export function useNumberFieldSlider() {
  const context = useContext(SliderContext);
  if (!context) throw new Error("NumberFieldSlider parts must be rendered inside <NumberFieldSlider>.");
  return context;
}

/**
 * The slider presentation: a row that fills to the value. Drag anywhere to adjust it
 * relative to where you started, click or press Enter to type, and use the arrow keys,
 * Page Up/Down, Home and End to step. Needs `min` and `max` on the NumberField.
 * Exposes the position as `--number-field-progress` for custom parts.
 */
export const NumberFieldSlider = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function NumberFieldSlider(
  { className, style, onKeyDown, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, ...props },
  ref,
) {
  const field = useNumberField();
  const { min = 0, max = 100, display } = field;
  const range = max - min;
  const typing = field.draft !== null;
  const locked = field.disabled || field.readOnly;
  const progress = display === null || range === 0 ? 0 : Math.min(1, Math.max(0, (display - min) / range));
  const [keyStepping, setKeyStepping] = useState(false);
  const linger = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(linger.current), []);
  const adjusting = field.dragging || keyStepping;

  const adjust = usePointerAdjust({
    // Snap travel to whole steps so the value lands where the keyboard would.
    valueAt: (start, dx, width) => start + Math.round(((dx / width) * range) / field.step) * field.step,
    onTap: field.beginTyping,
  });

  const showSteps = () => {
    clearTimeout(linger.current);
    setKeyStepping(true);
    linger.current = setTimeout(() => setKeyStepping(false), keyStepLinger);
  };

  return (
    <SliderContext.Provider value={{ progress, adjusting }}>
      <div
        ref={mergeRefs(ref, field.sliderRef)}
        data-slot="slider"
        // While typing, the input inside takes over as the control.
        role={typing ? undefined : "slider"}
        tabIndex={typing || field.disabled ? -1 : 0}
        aria-label={typing ? undefined : field.label}
        aria-valuemin={typing ? undefined : min}
        aria-valuemax={typing ? undefined : max}
        aria-valuenow={typing ? undefined : display ?? undefined}
        aria-valuetext={typing ? undefined : field.valueText}
        aria-disabled={field.disabled || undefined}
        aria-readonly={field.readOnly || undefined}
        data-dragging={field.dragging || undefined}
        data-adjusting={adjusting || undefined}
        data-typing={typing || undefined}
        className={cn(
          "group/slider relative isolate flex h-[calc(var(--uicoolkit-field-height,2.5rem)-0.5rem)] w-full min-w-0 touch-pan-y items-center justify-between gap-3 overflow-hidden rounded-md bg-muted px-2.5 text-sm outline-none select-none focus-visible:ring-1 focus-visible:ring-ring aria-disabled:opacity-50 in-data-invalid:ring-1 in-data-invalid:ring-destructive",
          !locked && !typing && "cursor-ew-resize",
          className,
        )}
        style={{ "--number-field-progress": progress, ...style } as CSSProperties}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented || typing || event.target !== event.currentTarget) return;
          const steps: Record<string, [number, boolean]> = {
            ArrowRight: [1, event.shiftKey],
            ArrowUp: [1, event.shiftKey],
            ArrowLeft: [-1, event.shiftKey],
            ArrowDown: [-1, event.shiftKey],
            PageUp: [1, true],
            PageDown: [-1, true],
          };
          if (event.key in steps) {
            event.preventDefault();
            if (!locked && display !== null) showSteps();
            field.stepBy(...steps[event.key]);
          } else if (event.key === "Home" || event.key === "End") {
            event.preventDefault();
            if (!locked) showSteps();
            field.commit(event.key === "Home" ? min : max);
          } else if (event.key === "Enter" || event.key === "F2") {
            event.preventDefault();
            field.beginTyping();
          }
        }}
        onPointerDown={(event) => {
          onPointerDown?.(event);
          if (!event.defaultPrevented && !typing) adjust.onPointerDown(event);
        }}
        onPointerMove={(event) => {
          onPointerMove?.(event);
          adjust.onPointerMove(event);
        }}
        onPointerUp={(event) => {
          onPointerUp?.(event);
          adjust.onPointerUp(event);
        }}
        onPointerCancel={(event) => {
          onPointerCancel?.(event);
          adjust.onPointerCancel(event);
        }}
        {...props}
      />
    </SliderContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type KeyboardEvent, type MutableRefObject, type Ref, createContext, useContext } from "react";

/**
 * Replaceable text for validation and the step buttons. In `tooLow` and `tooHigh`, `{min}` and
 * `{max}` are replaced with the formatted limit and its unit.
 */
export type NumberFieldMessages = {
  invalid: string;
  tooLow: string;
  tooHigh: string;
  increment: string;
  decrement: string;
  /** The keyword menu's option for a plain number. */
  fixed: string;
  /** Names the keyword menu, such as "Gap mode". */
  mode: (label: string) => string;
};

export const defaultMessages: NumberFieldMessages = {
  invalid: "Enter a number.",
  tooLow: "Enter {min} or more.",
  tooHigh: "Enter {max} or less.",
  increment: "Increase",
  decrement: "Decrease",
  fixed: "Fixed",
  mode: (label) => `${label} mode`,
};

/**
 * A named value the field can hold instead of a number, such as Auto or Hug. Give `resolved`
 * when the keyword stands for a size your app worked out (Hug's 560); the field then shows that
 * number with the keyword beside it, and adjusting it starts from there.
 */
export type NumberFieldKeyword<K extends string = string> = { value: K; label: string; resolved?: number | null };

/**
 * Where the step buttons go. "stacked" puts small up/down arrows at the end of the field;
 * "split" puts larger − and + buttons on either side for fingers. "auto" picks split on
 * touch screens (a coarse pointer) and stacked otherwise, decided in CSS so it never flashes.
 */
export type NumberFieldStepperLayout = "auto" | "stacked" | "split";

/** Only `keywords` decides K, so a field without keywords keeps a plain number value. */
export type NumberFieldProps<K extends string = never> = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> & {
  /** The committed value: a number, one of your keywords, or null when there is none (for example a mixed selection). The application owns it. */
  value: number | NoInfer<K> | null;
  /** Called once per finished change: a typed value, a step, the end of a drag, or a keyword. */
  onValueCommit: (value: number | NoInfer<K>) => void;
  /** Called with every change, including live values while dragging, and with the committed value when a drag is cancelled. */
  onValueChange?: (value: number | NoInfer<K>) => void;
  /** Named values the field can hold instead of a number, offered in NumberFieldKeywordMenu and accepted when typed. */
  keywords?: readonly NumberFieldKeyword<K>[];
  /** Where stepping or dragging starts from a keyword with no resolved number. Defaults to min, or 0. */
  keywordFallback?: number;
  /** Where NumberFieldKeywordMenu is portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  /**
   * Handle typed text before the field reads it as a number, such as a list like "8, 20". Return true
   * when you applied it, a message to reject it, or nothing to let the field read it as usual.
   */
  submitText?: (text: string) => true | string | null | undefined | void;
  /** When the value is empty, the text typing starts from, such as the list a merged field stands for. */
  editText?: string;
  /** Accessible name of the field, such as "Width". */
  label: string;
  /** Limits. Typed values outside them are rejected with a message; stepping and dragging stop at them. */
  min?: number;
  max?: number;
  step?: number;
  /** Used with Shift and Page Up/Down. Defaults to ten steps. */
  largeStep?: number;
  /** Decimal places kept and shown. Defaults to the decimals of `step`. */
  precision?: number;
  /** Shown after the value and read with it, such as "px" or "%". */
  unit?: string;
  format?: (value: number) => string;
  /** Turn typed text into a number; return NaN to reject it. */
  parse?: (text: string) => number;
  /** Return a message to reject a typed value. */
  validate?: (value: number) => string | null | undefined;
  /** Shown when `value` is null, such as "Mixed". */
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  /** Pointer travel in pixels per step when dragging a scrub area. */
  sensitivity?: number;
  /** Fill and press transitions. Reduced motion is always honored. */
  motion?: boolean;
  /** Where NumberFieldStepper puts its buttons. Defaults to "auto". */
  stepperLayout?: NumberFieldStepperLayout;
  messages?: Partial<NumberFieldMessages>;
};

export type NumberFieldContextValue = {
  label: string;
  /** The committed number, or null when the value is a keyword or there is none. */
  value: number | null;
  /** The keyword the field holds, if any. */
  keyword: NumberFieldKeyword | null;
  keywords: readonly NumberFieldKeyword[];
  /** Where an adjustment starts: the shown number, or for a keyword without one, the fallback. Null when Mixed. */
  adjustFrom: number | null;
  /** Commits a keyword by its value, or a plain number (Fixed) when null. */
  setKeyword: (keyword: string | null) => void;
  container?: HTMLElement | null;
  editText?: string;
  /** The live value while dragging, otherwise the committed value. */
  display: number | null;
  /** `display` formatted, or "" when there is none. */
  text: string;
  valueText: string | undefined;
  unit?: string;
  min?: number;
  max?: number;
  step: number;
  largeStep: number;
  sensitivity: number;
  placeholder?: string;
  disabled: boolean;
  readOnly: boolean;
  animated: boolean;
  stepperLayout: NumberFieldStepperLayout;
  dragging: boolean;
  /** Typed text not yet committed, or null. */
  draft: string | null;
  error: string | null;
  messages: NumberFieldMessages;
  inputId: string;
  labelId: string;
  errorId: string;
  inputRef: MutableRefObject<HTMLInputElement | null>;
  sliderRef: MutableRefObject<HTMLDivElement | null>;
  setDraft: (text: string) => void;
  beginTyping: () => void;
  /** Commits the draft. Returns false and keeps it when it is invalid. */
  submitDraft: () => boolean;
  cancelDraft: () => void;
  stepBy: (steps: number, large?: boolean) => void;
  commit: (value: number) => void;
  /** Starts a drag; returns the value it starts from, or null when there is none to adjust. */
  beginDrag: () => number | null;
  dragTo: (value: number) => void;
  endDrag: () => void;
  cancelDrag: () => void;
};

export const NumberFieldContext = createContext<NumberFieldContextValue | null>(null);

/** State and actions of the nearest NumberField, for building custom parts. */
export function useNumberField() {
  const context = useContext(NumberFieldContext);
  if (!context) throw new Error("NumberField parts must be rendered inside <NumberField>.");
  return context;
}

export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<T | null>).current = node;
    }
  };
}

export function decimalsOf(step: number) {
  const [mantissa, exponent] = String(step).split("e-");
  return (mantissa.split(".")[1]?.length ?? 0) + Number(exponent ?? 0);
}

/** Keys shared by every typed input: Enter commits, Escape reverts, arrows step. */
export function handleTypingKeys(event: KeyboardEvent<HTMLInputElement>, field: NumberFieldContextValue) {
  if (event.key === "Enter") {
    // Enter confirms an input-method composition instead of committing.
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    event.preventDefault();
    field.submitDraft();
  } else if (event.key === "Escape" && field.draft !== null) {
    // Stop here so an enclosing sheet or popover stays open.
    event.preventDefault();
    event.stopPropagation();
    field.cancelDraft();
  } else if (event.key === "ArrowUp" || event.key === "ArrowDown") {
    event.preventDefault();
    field.stepBy(event.key === "ArrowUp" ? 1 : -1, event.shiftKey);
  } else if (event.key === "PageUp" || event.key === "PageDown") {
    event.preventDefault();
    field.stepBy(event.key === "PageUp" ? 1 : -1, true);
  }
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef, useEffect, useRef } from "react";
import { useNumberField } from "./number-field-state";
import { cn } from "@/lib/utils";

/** How long an arrow is held before it repeats, and how often it repeats after that. */
const holdDelay = 400;
const repeatEvery = 60;

/*
 * Split styles are written twice: for stepperLayout="split", and for "auto" on a coarse pointer.
 * Each part carries data-layout so the CSS decides, with no flash before hydration.
 */

/**
 * Up and down arrows in a small pill centred at the end of NumberFieldGroup, with room above and below. In the split layout
 * the pill dissolves and the buttons move to either side of the value as larger − and + targets.
 */
export const NumberFieldStepper = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function NumberFieldStepper(
  { className, ...props },
  ref,
) {
  const { stepperLayout, readOnly } = useNumberField();
  // A read-only value cannot be stepped, so the arrows are left out rather than shown disabled.
  if (readOnly) return null;
  return (
    <div
      ref={ref}
      data-layout={stepperLayout}
      className={cn(
        // A thin border keeps the stepper distinct from the field in light themes, where muted and background are close.
        "mr-1.5 flex h-7 w-5 shrink-0 flex-col self-center divide-y divide-border overflow-hidden rounded-[5px] bg-muted ring-1 ring-border data-[layout=split]:contents pointer-coarse:data-[layout=auto]:contents",
        className,
      )}
      {...props}
    />
  );
});

type StepProps = ComponentPropsWithoutRef<"button">;

function stepButton(direction: 1 | -1, name: string, icon: string, touchIcon: string) {
  const Step = forwardRef<HTMLButtonElement, StepProps>(function Step({ className, children, onClick, onMouseDown, onPointerDown, ...props }, ref) {
    const field = useNumberField();
    // Timers outlive the render that started them, so they act on the latest field.
    const latest = useRef(field);
    latest.current = field;
    const pressed = useRef(false);
    const stopHold = useRef<() => void>(undefined);
    useEffect(() => () => stopHold.current?.(), []);

    const bound = direction > 0 ? field.max : field.min;
    const atBound = bound !== undefined && field.display !== null && (direction > 0 ? field.display >= bound : field.display <= bound);

    /** One step now; holding repeats as a live preview that commits once on release. */
    const startHold = (large: boolean) => {
      latest.current.stepBy(direction, large);
      let current: number | null = null;
      let timer: ReturnType<typeof setTimeout>;
      const tick = () => {
        if (current === null) {
          current = latest.current.beginDrag();
          if (current === null) return;
        }
        current += direction * (large ? latest.current.largeStep : latest.current.step);
        latest.current.dragTo(current);
        timer = setTimeout(tick, repeatEvery);
      };
      timer = setTimeout(tick, holdDelay);
      // Listen on the window: the button disables itself at a limit and then gets no pointer events.
      const stop = () => {
        clearTimeout(timer);
        window.removeEventListener("pointerup", stop);
        window.removeEventListener("pointercancel", stop);
        window.removeEventListener("blur", stop);
        stopHold.current = undefined;
        if (current !== null) latest.current.endDrag();
      };
      window.addEventListener("pointerup", stop);
      window.addEventListener("pointercancel", stop);
      window.addEventListener("blur", stop);
      stopHold.current = stop;
    };

    return (
      <button
        ref={ref}
        type="button"
        // Keyboard users step with the arrow keys in the input, so the buttons stay out of the tab order.
        tabIndex={-1}
        data-layout={field.stepperLayout}
        aria-label={direction > 0 ? field.messages.increment : field.messages.decrement}
        aria-controls={field.inputId}
        disabled={field.disabled || field.readOnly || field.adjustFrom === null || atBound}
        className={cn(
          // Quiet until the field is hovered or focused; the pressed arrow nudges the way it steps.
          "group/step flex min-h-0 flex-1 touch-none items-center justify-center text-muted-foreground outline-none hover:bg-accent hover:text-foreground! focus-visible:bg-accent focus-visible:text-foreground! active:bg-accent/70 disabled:pointer-events-none disabled:opacity-35",
          direction > 0 ? "active:[&>svg]:-translate-y-px" : "active:[&>svg]:translate-y-px",
          // Split: a full-height button on each side, decrease first and increase last.
          "data-[layout=split]:w-10 data-[layout=split]:flex-none data-[layout=split]:text-muted-foreground data-[layout=split]:active:[&>svg]:translate-y-0 data-[layout=split]:active:[&>svg]:scale-90",
          "pointer-coarse:data-[layout=auto]:w-10 pointer-coarse:data-[layout=auto]:flex-none pointer-coarse:data-[layout=auto]:text-muted-foreground pointer-coarse:data-[layout=auto]:active:[&>svg]:translate-y-0 pointer-coarse:data-[layout=auto]:active:[&>svg]:scale-90",
          direction > 0
            ? "data-[layout=split]:order-last data-[layout=split]:border-l data-[layout=split]:border-input pointer-coarse:data-[layout=auto]:order-last pointer-coarse:data-[layout=auto]:border-l pointer-coarse:data-[layout=auto]:border-input"
            : "data-[layout=split]:order-first data-[layout=split]:border-r data-[layout=split]:border-input pointer-coarse:data-[layout=auto]:order-first pointer-coarse:data-[layout=auto]:border-r pointer-coarse:data-[layout=auto]:border-input",
          field.animated && "[&>svg]:transition-transform [&>svg]:duration-100 motion-reduce:[&>svg]:transition-none",
          className,
        )}
        onPointerDown={(event) => {
          onPointerDown?.(event);
          if (event.defaultPrevented || event.button !== 0) return;
          pressed.current = true;
          stopHold.current?.();
          startHold(event.shiftKey);
        }}
        onMouseDown={(event) => {
          onMouseDown?.(event);
          // Keep focus (and any typed draft) in the input while stepping.
          event.preventDefault();
        }}
        onClick={(event) => {
          onClick?.(event);
          // A pointer press already stepped; a click from assistive technology steps here.
          if (pressed.current) pressed.current = false;
          else if (!event.defaultPrevented) field.stepBy(direction, event.shiftKey);
        }}
        {...props}
      >
        {children ?? (
          <>
            <svg aria-hidden viewBox="0 0 10 6" className="h-1.5 w-2.5 group-data-[layout=split]/step:hidden pointer-coarse:group-data-[layout=auto]/step:hidden" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
              <path d={icon} />
            </svg>
            <svg aria-hidden viewBox="0 0 16 16" className="hidden size-4 group-data-[layout=split]/step:block pointer-coarse:group-data-[layout=auto]/step:block" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round">
              <path d={touchIcon} />
            </svg>
          </>
        )}
      </button>
    );
  });
  Step.displayName = name;
  return Step;
}

export const NumberFieldIncrement = stepButton(1, "NumberFieldIncrement", "M1.5 4.75 5 1.25l3.5 3.5", "M3.5 8h9M8 3.5v9");
export const NumberFieldDecrement = stepButton(-1, "NumberFieldDecrement", "M1.5 1.25 5 4.75l3.5-3.5", "M3.5 8h9");

