import { Fragment, useMemo } from "react";
import { cn } from "@/lib/utils";

export type NumberTickerProps = {
  value: number;
  locale?: string;
  format?: Intl.NumberFormatOptions;
  motion?: boolean;
  duration?: number;
  className?: string;
};

export function NumberTicker({ value, locale = "en-US", format, motion = true, duration = 600,
  className }: NumberTickerProps) {
  const formatter = useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);
  const digits = useMemo(() => {
    const decimal = new Intl.NumberFormat(locale, { numberingSystem: formatter.resolvedOptions().numberingSystem });
    return Array.from({ length: 10 }, (_, i) => decimal.format(i));
  }, [locale, formatter]);
  const parts = formatter.formatToParts(value);
  const text = parts.map(part => part.value).join("");
  // Integer columns keep their place from the units digit, even when a new group appears.
  let integerPlaces = parts.reduce((count, part) => count + (part.type === "integer" ? Array.from(part.value).length : 0), 0);
  return (
    <span className={cn("inline-block whitespace-nowrap tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <bdi aria-hidden="true">
        {parts.flatMap((part, index) => {
          if (part.type !== "integer" && part.type !== "fraction") {
            return <Fragment key={`${part.type}-${index}`}>{part.value}</Fragment>;
          }
          return Array.from(part.value, (char, position) => {
            const key = part.type === "integer" ? `place-${--integerPlaces}` : `fraction-${position}`;
            const digit = digits.indexOf(char);
            if (digit < 0) return <Fragment key={key}>{char}</Fragment>;
            return (
              <span key={key} className="relative inline-grid align-baseline leading-none">
                <span className="invisible">{digits[0]}</span>
                <span className="absolute inset-0 overflow-hidden">
                  <span className={cn("flex flex-col",
                    motion && "transition-transform ease-out motion-reduce:transition-none")}
                    style={{ transform: `translateY(-${digit}em)`, transitionDuration: motion ? `${Math.max(0, duration)}ms` : "0ms" }}>
                    {digits.map(glyph => <span key={glyph} className="block h-[1em] leading-none">{glyph}</span>)}
                  </span>
                </span>
              </span>
            );
          });
        })}
      </bdi>
    </span>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import { cn } from "@/lib/utils";

export type WorkspaceSetup = {
  step: 0 | 1 | 2 | 3;
  workspaceName: string;
  inviteEmail: string;
  startingPoint: "blank" | "template";
};

export const emptyWorkspaceSetup: WorkspaceSetup = {
  step: 0, workspaceName: "", inviteEmail: "", startingPoint: "blank",
};

const titles = ["Name your workspace", "Invite a teammate", "Pick a starting point", "Your workspace is ready"];
const choices = [
  { value: "blank", label: "Blank workspace" },
  { value: "template", label: "Use a template" },
] as const;
const fieldStyle = "mt-2 block w-full rounded-[var(--radius,0.625rem)] border border-input bg-background px-3 py-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary aria-invalid:border-destructive";
const buttonStyle = "rounded-[var(--radius,0.625rem)] px-3 py-2 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary";
const primaryButton = cn(buttonStyle, "bg-primary text-primary-foreground");
const quietButton = cn(buttonStyle, "text-muted-foreground hover:bg-muted hover:text-foreground");

type Props = {
  value: WorkspaceSetup;
  onChange: (value: WorkspaceSetup) => void;
  onComplete?: (value: WorkspaceSetup) => void;
  onReset?: () => void;
  motion?: boolean;
  className?: string;
};

export function OnboardingSteps({ value, onChange, onComplete, onReset, motion = true, className }: Props) {
  const { step, workspaceName, inviteEmail, startingPoint } = value;
  const id = useId();
  const heading = useRef<HTMLHeadingElement>(null);
  const body = useRef<HTMLDivElement>(null);
  const field = useRef<HTMLInputElement>(null);
  const previousStep = useRef(step);
  const [error, setError] = useState("");
  const done = step === 3;

  useEffect(() => {
    const previous = previousStep.current;
    previousStep.current = step;
    if (previous === step) return;
    heading.current?.focus({ preventScroll: true });
    if (!motion || window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
    const animation = body.current?.animate?.([
      { opacity: 0, transform: "translateX(" + (previous < step ? 8 : -8) + "px)" },
      { opacity: 1, transform: "translateX(0)" },
    ], { duration: 160, easing: "ease-out" });
    return () => animation?.cancel();
  }, [step, motion]);

  function update(next: WorkspaceSetup) {
    setError("");
    onChange(next);
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    const message = step === 0 && !workspaceName.trim() ? "Enter a workspace name."
      : step === 1 && field.current?.validity.typeMismatch ? "Enter a valid email address or skip this step." : "";
    if (message) {
      setError(message);
      field.current?.focus();
      return;
    }
    const next: WorkspaceSetup = { ...value, workspaceName: workspaceName.trim(), inviteEmail: inviteEmail.trim(), step: step === 0 ? 1 : step === 1 ? 2 : 3 };
    update(next);
    if (next.step === 3) onComplete?.(next);
  }

  return (
    <section aria-labelledby={id} className={cn("w-full max-w-sm rounded-[calc(var(--radius,0.625rem)+6px)] border border-border bg-background p-5 text-left text-foreground shadow-sm", className)}>
      <ol aria-label="Setup progress" className="flex gap-1.5">
        {titles.slice(0, 3).map((title, index) => (
          <li key={title} aria-current={index === step ? "step" : undefined} className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted">
            <span aria-hidden="true" style={{ width: index < step ? "100%" : index === step ? "50%" : "0%" }}
              className={cn("block h-full rounded-full bg-primary", motion && "motion-safe:transition-[width] motion-safe:duration-150")} />
            <span className="sr-only">{title}{index < step && ", complete"}</span>
          </li>
        ))}
      </ol>
      <div ref={body} className="mt-5">
        <p className="text-xs font-medium text-muted-foreground">{done ? "Setup complete" : `Step ${step + 1} of 3${step === 1 ? " · Optional" : ""}`}</p>
        <h3 id={id} ref={heading} tabIndex={-1} className="mt-1 text-xl font-semibold tracking-tight outline-none">{titles[step]}</h3>
        {done ? <>
          <dl className="my-5 grid gap-3 text-sm">
            {[
              ["Workspace", workspaceName], ["Starting point", startingPoint === "blank" ? "Blank workspace" : "Template"],
              ["Teammate", inviteEmail || "Skipped"],
            ].map(([label, text]) => <div key={label} className="flex justify-between gap-3">
              <dt className="text-muted-foreground">{label}</dt><dd className="min-w-0 text-right font-medium [overflow-wrap:anywhere]">{text}</dd>
            </div>)}
          </dl>
          <button type="button" className={primaryButton} onClick={() => { update({ ...emptyWorkspaceSetup }); onReset?.(); }}>Start over</button>
        </> : (
          <form noValidate onSubmit={submit} className="mt-5">
            {step < 2 ? (
              <div key={step}>
                <label htmlFor={id + "-input"} className="text-sm font-medium">{step === 0 ? "Workspace name" : "Teammate email"}</label>
                <input id={id + "-input"} ref={field} type={step === 0 ? "text" : "email"} required={step === 0}
                  autoComplete="off" placeholder={step === 0 ? "e.g. Design studio" : "teammate@example.com"}
                  aria-invalid={error ? true : undefined} aria-describedby={error ? id + "-error" : undefined}
                  value={step === 0 ? workspaceName : inviteEmail} className={fieldStyle}
                  onChange={event => update(step === 0 ? { ...value, workspaceName: event.target.value } : { ...value, inviteEmail: event.target.value })} />
                {error && <p role="alert" id={id + "-error"} className="mt-2 text-sm text-destructive">{error}</p>}
              </div>
            ) : (
              <fieldset className="grid gap-2">
                <legend className="sr-only">Starting point</legend>
                {choices.map(choice => (
                  <label key={choice.value} className="flex cursor-pointer items-center gap-3 rounded-[var(--radius,0.625rem)] border border-input px-3 py-2 text-sm has-checked:border-primary has-checked:bg-primary/10">
                    <input type="radio" name={id + "-start"} value={choice.value} checked={startingPoint === choice.value}
                      className="size-4 accent-primary" onChange={() => update({ ...value, startingPoint: choice.value })} />
                    {choice.label}
                  </label>
                ))}
              </fieldset>
            )}
            <div className="mt-5 flex flex-wrap items-center gap-1">
              {step > 0 && <button type="button" className={quietButton} onClick={() => update({ ...value, step: step === 2 ? 1 : 0 })}>Back</button>}
              <div className="ml-auto flex flex-wrap items-center gap-1">
                {step === 1 && <button type="button" className={quietButton} onClick={() => update({ ...value, inviteEmail: "", step: 2 })}>Skip for now</button>}
                <button className={primaryButton} type="submit">{step === 2 ? "Finish" : "Continue"}</button>
              </div>
            </div>
          </form>
        )}
      </div>
    </section>
  );
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useOrbitMotion } from "./use-orbit-motion";

export type OrbitNode = { ring: number; index: number; count: number };
export type OrbitRing = { radius: number; dots: number; offset?: number };
export type OrbitFieldProps = {
  rings?: number | readonly OrbitRing[];
  center?: ReactNode;
  renderNode?: (node: OrbitNode) => ReactNode;
  synchronized?: boolean;
  color?: string;
  speed?: number;
  still?: boolean;
  interactive?: boolean;
  label?: string;
  className?: string;
};

// Apply the outline to the slotted element so the browser uses its own corner radius.
const iconHalo = {
  "--orbit-icon-halo": "0 0 0 2px light-dark(#fff, rgb(255 255 255 / 0.40)), 0 0 0 3px light-dark(rgb(37 37 37 / 0.52), transparent), 0 0 7px light-dark(rgb(0 0 0 / 0.16), rgb(255 255 255 / 0.22))",
  "--orbit-svg-halo": "drop-shadow(0 0 1px white) drop-shadow(0 0 2px light-dark(rgb(37 37 37 / 0.65), rgb(255 255 255 / 0.45)))",
} as CSSProperties;

const periods = [14, 22, 32, 46, 60, 78];

export function OrbitField({ rings = 3, center, renderNode, color = "var(--primary, currentColor)",
  synchronized = false, speed = 1, still = false, interactive = true, label, className }: OrbitFieldProps) {
  const customRings = typeof rings === "number" ? undefined : rings;
  const requested = typeof rings === "number" ? rings : rings.length;
  const ringCount = Number.isFinite(requested) ? Math.max(1, Math.min(6, Math.round(requested))) : 3;
  const ref = useOrbitMotion(still, Number.isFinite(speed) ? Math.max(0, speed) : 1, interactive);
  return (
    <div ref={ref} role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : true}
      className={cn("group/orbit relative aspect-square w-64 max-w-full", className)}>
      <div className="pointer-events-none absolute inset-0">
        {Array.from({ length: ringCount }, (_, ring) => {
          const custom = customRings?.[ring];
          const autoRadius = ringCount === 1 ? 86 : 56 + 64 * ring / (ringCount - 1);
          const radius = custom && Number.isFinite(custom.radius) ? Math.max(0, custom.radius) : autoRadius;
          // Multiples of three give synchronized rings exact third-turn anchor points.
          const autoCount = (synchronized ? 3 : 5) + ring * 3;
          const count = custom && Number.isFinite(custom.dots) ? Math.max(0, Math.floor(custom.dots)) : autoCount;
          const rate = synchronized ? 360 / periods[2] : (ring % 2 ? -360 : 360) / periods[ring];
          const icons: ReactNode[] = [];
          const dots = Array.from({ length: count }, (_, index) => {
            const angle = (index * 360 / count - 90 + (custom?.offset ?? 0)) * Math.PI / 180;
            const x = Number((radius * Math.cos(angle)).toFixed(4));
            const y = Number((radius * Math.sin(angle)).toFixed(4));
            const icon = renderNode?.({ ring, index, count });
            if (icon != null && icon !== false) {
              icons.push(
                <span key={index} className="absolute grid aspect-square w-[9.5%] -translate-1/2 place-items-center"
                  style={{ left: (50 + x / 2.6) + "%", top: (50 + y / 2.6) + "%",
                    transform: `rotate(calc(var(--orbit-seconds, 0) * ${-rate}deg))` }}>
                  <span data-orbit-icon="" style={iconHalo} className={cn("grid size-full place-items-center",
                    interactive && !still && "motion-safe:group-hover/orbit:[&>:not(svg)]:shadow-(--orbit-icon-halo) motion-safe:group-hover/orbit:[&>svg]:[filter:var(--orbit-svg-halo)]")}>
                    {icon}
                  </span>
                </span>
              );
              return null;
            }
            const accented = index % 4 === ring % 4;
            return <circle key={index} data-orbit-accent={accented ? "" : undefined} cx={x} cy={y} r={accented ? 3 : 1.6}
              fill={accented ? color : "var(--muted-foreground, currentColor)"} />;
          });
          return (
            <div key={ring} className="absolute inset-0"
              style={{ transform: `rotate(calc(var(--orbit-seconds, 0) * ${rate}deg))` }}>
              <svg viewBox="-130 -130 260 260" className="size-full overflow-visible" aria-hidden="true">
                <circle r={radius} fill="none" stroke="var(--border, currentColor)" strokeWidth="0.6" />
                {dots}
              </svg>
              {icons}
            </div>
          );
        })}
        <span className="absolute left-1/2 top-1/2 grid aspect-square w-[14.5%] -translate-1/2 place-items-center">
          {center ?? <span className="aspect-square w-1/2 rounded-full" style={{ backgroundColor: color }} />}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

export function useOrbitMotion(still: boolean, speed: number, interactive: boolean) {
  const ref = useRef<HTMLDivElement>(null);
  const seconds = useRef(0);
  useEffect(() => {
    const host = ref.current;
    if (!host) return;
    let feedback: Animation[] = [];
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
    let visible = false;
    let frame = 0;
    let last = 0;
    const running = () => visible && !still && !reduced.matches && !document.hidden;
    const tick = (now: number) => {
      const elapsed = Math.max(0, Math.min(now - last, 64)) / 1000;
      last = now;
      seconds.current += elapsed * speed;
      host.style.setProperty("--orbit-seconds", String(seconds.current));
      frame = requestAnimationFrame(tick);
    };
    const stopFeedback = () => {
      feedback.forEach(animation => animation.cancel());
      feedback = [];
    };
    const sync = () => {
      stopFeedback();
      cancelAnimationFrame(frame);
      if (running()) {
        last = performance.now();
        frame = requestAnimationFrame(tick);
      }
    };
    const hover = (event: PointerEvent) => {
      if (!running() || !interactive || event.pointerType === "touch") return;
      stopFeedback();
      if (host.querySelector("[data-orbit-icon]")) return;
      const frames = [{ opacity: 1 }, { opacity: 0.35 }, { opacity: 1 }];
      for (const dot of host.querySelectorAll("[data-orbit-accent]")) {
        if (dot.animate) feedback.push(dot.animate(frames, { duration: 420, easing: "ease-in-out" }));
      }
    };
    const observer = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; sync(); });
    observer.observe(host);
    host.addEventListener("pointerenter", hover);
    reduced.addEventListener("change", sync);
    document.addEventListener("visibilitychange", sync);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      host.removeEventListener("pointerenter", hover);
      stopFeedback();
      reduced.removeEventListener("change", sync);
      document.removeEventListener("visibilitychange", sync);
    };
  }, [still, speed, interactive]);
  return ref;
}

"use client";

import { useId } from "react";
import { NumberTicker } from "@/components/ui/number-ticker";
import { cn } from "@/lib/utils";

export type BillingPeriod = "monthly" | "yearly";
export type PlanSelection = { planId: string; period: BillingPeriod };
export type PricingPlan = {
  id: string;
  name: string;
  /** Prices for one month and one full year in major currency units. */
  monthlyPrice: number;
  annualPrice: number;
  features: readonly string[];
  featured?: boolean;
};

export function BillingPeriodControl({ value, onChange, motion = true }: {
  value: BillingPeriod;
  onChange: (period: BillingPeriod) => void;
  motion?: boolean;
}) {
  const name = useId();
  return (
    <fieldset className="relative mx-auto grid w-fit grid-cols-2 rounded-full border border-border bg-background p-1">
      <legend className="sr-only">Billing period</legend>
      <span aria-hidden="true" className={cn(
        "pointer-events-none absolute inset-y-1 left-1 w-[calc(50%-0.25rem)] rounded-full bg-primary shadow-sm",
        value === "yearly" && "translate-x-full", motion && "motion-safe:transition-transform motion-safe:duration-200",
      )} />
      {(["monthly", "yearly"] as const).map(period => (
        <label key={period} className={cn("relative cursor-pointer rounded-full px-4 py-1.5 text-center text-sm font-medium has-focus-visible:outline-2 has-focus-visible:outline-offset-2 has-focus-visible:outline-ring",
          value === period ? "text-primary-foreground" : "text-muted-foreground")}>
          <input className="sr-only" name={name} type="radio" value={period}
            checked={value === period} onChange={() => onChange(period)} />
          {period === "monthly" ? "Monthly" : "Yearly"}
        </label>
      ))}
    </fieldset>
  );
}

export type PlanSwitcherProps = {
  plans: readonly PricingPlan[];
  period: BillingPeriod;
  onPeriodChange: (period: BillingPeriod) => void;
  currentPlan?: PlanSelection;
  onChoose: (selection: PlanSelection) => void;
  currency?: string;
  locale?: string;
  motion?: boolean;
  className?: string;
};

export function PlanSwitcher({ plans, period, onPeriodChange, currentPlan, onChoose,
  currency = "USD", locale = "en-US", motion = true, className }: PlanSwitcherProps) {
  const format = { style: "currency", currency, trailingZeroDisplay: "stripIfInteger" } as const;
  const money = new Intl.NumberFormat(locale, format);
  const currencyScale = 10 ** (money.resolvedOptions().maximumFractionDigits ?? 2);
  const yearly = period === "yearly";
  const summary = plans.map(plan => {
    const price = yearly ? plan.annualPrice : plan.monthlyPrice;
    return plan.name + " " + money.format(price) + (yearly ? " per year" : " per month");
  }).join(", ");

  return (
    <section aria-label="Compare plans" className={cn("@container w-full max-w-xl text-foreground", className)}>
      <BillingPeriodControl value={period} onChange={onPeriodChange} motion={motion} />
      <div role="status" aria-atomic="true" className="sr-only">{summary}</div>
      <div className="mt-4 grid grid-cols-1 gap-3 @min-[26rem]:grid-cols-2">
        {plans.map(plan => {
          const current = plan.id === currentPlan?.planId;
          const active = current && period === currentPlan.period;
          const monthly = yearly ? plan.annualPrice / 12 : plan.monthlyPrice;
          const savings = (Math.round(plan.monthlyPrice * currencyScale) * 12 - Math.round(plan.annualPrice * currencyScale)) / currencyScale;
          const action = active ? "Current plan" : current ? "Switch to " + period : "Choose " + plan.name;
          return (
            <article key={plan.id} aria-label={plan.name} data-featured={plan.featured || undefined} className={cn(
              "flex min-w-0 flex-col rounded-[calc(var(--radius,0.625rem)+6px)] border bg-background p-4 shadow-sm",
              plan.featured ? "border-primary/65 bg-linear-to-b from-primary/10 to-transparent to-40%" : "border-border",
            )}>
              <div className="flex flex-wrap items-baseline justify-between gap-1.5">
                <h3 className={cn("text-base font-semibold", plan.featured && "text-[color-mix(in_oklab,var(--primary)_50%,var(--foreground))]")}>{plan.name}</h3>
                {current && !active && <span className="text-xs text-muted-foreground">Current plan</span>}
              </div>
              <p className="mt-2 flex flex-wrap items-baseline gap-1">
                <NumberTicker value={monthly} format={format} locale={locale} motion={motion} duration={340} className="text-3xl font-semibold tracking-tight" />
                <span className="text-sm text-muted-foreground">/mo</span>
              </p>
              <div className="mt-1 flex min-h-10 flex-wrap content-start items-baseline gap-x-2 gap-y-1 text-xs leading-5 text-muted-foreground">
                <p>{yearly ? money.format(plan.annualPrice) + " billed yearly" : "Billed monthly"}</p>
                {yearly && savings > 0 && (
                  <span className="rounded-full bg-primary/15 px-2 py-0.5 font-semibold leading-4 text-[color-mix(in_oklab,var(--primary)_35%,var(--foreground))]">
                    Save {money.format(savings)}/year
                  </span>
                )}
              </div>
              <ul className="mb-4 mt-2 list-disc space-y-1 border-t border-border pt-3 pl-4 text-sm leading-5 marker:text-muted-foreground">
                {plan.features.map(feature => <li key={feature}>{feature}</li>)}
              </ul>
              <button type="button" aria-disabled={active || undefined} onClick={() => { if (!active) onChoose({ planId: plan.id, period }); }}
                className={cn("mt-auto w-full rounded-[var(--radius,0.625rem)] px-3 py-2 text-sm font-semibold focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
                  active && "bg-muted text-muted-foreground",
                  !active && "cursor-pointer shadow-sm",
                  !active && (plan.featured
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-foreground inset-ring inset-ring-border hover:bg-foreground/10"))}>
                {action}
              </button>
            </article>
          );
        })}
      </div>
    </section>
  );
}

