  /** Read with the seek bar. */
  seekValue: (current: string, total: string) => string;
  /** Names a speed in the menu. */
  speedValue: (speed: number) => string;
};

export const defaultMessages: PlaybackControlsMessages = {
  play: "Play",
  pause: "Pause",
