const vertex = `#version 300 es
in vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`;

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn("[shader-canvas] shader compile failed:", gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** Builds a program that draws one fragment shader over a fullscreen triangle. */
export function createFullscreenProgram(gl: WebGL2RenderingContext, fragment: string, uniformNames: string[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, vertex);
  const fs = compile(gl, gl.FRAGMENT_SHADER, fragment);
  if (!vs || !fs) {
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    return null;
  }

  const program = gl.createProgram();
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.warn("[shader-canvas] program link failed:", gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const location = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 0, 0);
  gl.useProgram(program);

  const uniforms: Record<string, WebGLUniformLocation | null> = Object.fromEntries(
    uniformNames.map((name) => [name, gl.getUniformLocation(program, name)]),
  );

  return { program, buffer, uniforms };
}

"use client";

import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import { mountPulseGrid } from "./pulse-runtime";

const origins = {
  center: [0.5, 0.5], top: [0.5, 0], bottom: [0.5, 1],
  left: [0, 0.5], right: [1, 0.5], corner: [0, 0],
} as const;
export type PulseOriginName = keyof typeof origins;
export type PulseGridProps = {
  origin?: PulseOriginName | readonly [number, number];
  flow?: "outward" | "inward";
  color?: string;
  interactive?: boolean;
  still?: boolean;
  speed?: number;
  className?: string;
};

export function PulseGrid({ origin = "center", flow = "outward", interactive = true, still = false,
  speed = 1, color = "var(--primary, currentColor)", className }: PulseGridProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const grid = useRef<ReturnType<typeof mountPulseGrid>>(undefined);
  const [x, y] = typeof origin === "string" ? origins[origin] : origin;
  useEffect(() => {
    if (!canvas.current) return;
    grid.current = mountPulseGrid(canvas.current);
    return () => { grid.current?.dispose(); grid.current = undefined; };
  }, []);
  useEffect(() => {
    grid.current?.update({ origin: [x, y], inward: flow === "inward", interactive, still, speed });
  }, [x, y, flow, interactive, still, speed, color]);
  return <canvas aria-hidden="true" ref={canvas} className={cn("pointer-events-none block size-full", className)} style={{ color }} />;
}

import { createFullscreenProgram } from "./pulse-grid-gl";
import { pulseShader, uniforms } from "./pulse-shader";

export type GridOptions = {
  origin: readonly [number, number];
  inward: boolean;
  still: boolean;
  interactive: boolean;
  speed: number;
};

export function createPulseRenderer(canvas: HTMLCanvasElement) {
  const gl = canvas.getContext("webgl2", { alpha: true, premultipliedAlpha: true, antialias: false });
  if (!gl) return;
  const setup = createFullscreenProgram(gl, pulseShader, uniforms);
  if (!setup) return;
  const u = setup.uniforms;
  const pixel = document.createElement("canvas");
  pixel.width = pixel.height = 1;
  const palette = pixel.getContext("2d", { willReadFrequently: true });
  let lastPalette = "";
  return {
    resize() {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
      const height = Math.max(1, Math.round(canvas.clientHeight * dpr));
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      gl.viewport(0, 0, width, height);
      gl.uniform2f(u.u_size, width / dpr, height / dpr);
      gl.uniform1f(u.u_dpr, dpr);
    },
    refreshPalette() {
      const idle = getComputedStyle(canvas.parentElement!).color;
      const accent = getComputedStyle(canvas).color;
      const key = idle + "/" + accent;
      if (!palette || key === lastPalette) return false;
      lastPalette = key;
      const upload = (location: WebGLUniformLocation | null, color: string) => {
        palette.clearRect(0, 0, 1, 1);
        palette.fillStyle = color;
        palette.fillRect(0, 0, 1, 1);
        const [r, g, b] = palette.getImageData(0, 0, 1, 1).data;
        gl.uniform3f(location, r / 255, g / 255, b / 255);
      };
      upload(u.u_idle, idle);
      upload(u.u_accent, accent);
      return true;
    },
    draw(options: GridOptions, still: boolean, time: number, pointer: readonly [number, number], taps: Float32Array) {
      gl.uniform2f(u.u_origin, ...options.origin);
      gl.uniform1i(u.u_inward, Number(options.inward));
      gl.uniform1i(u.u_still, Number(still));
      gl.uniform1f(u.u_time, time);
      gl.uniform2f(u.u_pointer, ...pointer);
      gl.uniform3fv(u.u_taps, taps);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteBuffer(setup.buffer);
      gl.deleteProgram(setup.program);
    },
  };
}

import { createPulseRenderer, type GridOptions } from "./pulse-renderer";

export function mountPulseGrid(canvas: HTMLCanvasElement) {
  const host = canvas.parentElement;
  if (!host) return;
  let renderer = createPulseRenderer(canvas);
  const reduced = matchMedia("(prefers-reduced-motion: reduce)");
  const theme = matchMedia("(prefers-color-scheme: dark)");
  let options: GridOptions;
  let inView = false;
  let frame = 0;
  let last = 0;
  let time = 0.85;
  let pointer: [number, number] = [-1, -1];
  const taps = new Float32Array(12).fill(-100);
  let nextTap = 0;
  const frozen = () => options.still || reduced.matches;
  const visible = () => inView && !document.hidden;
  const acceptsPointer = () => options?.interactive && visible() && !frozen();
  const clearPointer = () => { pointer = [-1, -1]; };
  const stop = () => { cancelAnimationFrame(frame); frame = 0; };
  const tick = (now: number) => {
    time += Math.min(50, now - last) * options.speed / 1000;
    last = now;
    renderer?.draw(options, false, time, pointer, taps);
    frame = requestAnimationFrame(tick);
  };
  const refresh = () => {
    stop();
    if (!renderer || !options || !visible()) return;
    renderer.resize();
    renderer.refreshPalette();
    if (!acceptsPointer()) { clearPointer(); taps.fill(-100); }
    renderer.draw(options, frozen(), time, pointer, taps);
    if (!frozen()) {
      last = performance.now();
      frame = requestAnimationFrame(tick);
    }
  };
  const paletteChanged = () => {
    if (options && visible() && renderer?.refreshPalette() && frozen()) {
      renderer.draw(options, true, time, pointer, taps);
    }
  };
  const point = (event: PointerEvent): [number, number] | undefined => {
    const box = canvas.getBoundingClientRect();
    const x = event.clientX - box.left;
    const y = event.clientY - box.top;
    if (x >= 0 && y >= 0 && x < box.width && y < box.height) return [x, y];
  };
  const move = (event: PointerEvent) => {
    if (!acceptsPointer() || event.pointerType === "touch") return;
    pointer = point(event) ?? [-1, -1];
  };
  const down = (event: PointerEvent) => {
    if (!acceptsPointer() || event.button !== 0) return;
    const xy = point(event);
    if (!xy) return;
    taps.set([...xy, time], nextTap * 3);
    nextTap = (nextTap + 1) % 4;
  };
  const lost = (event: Event) => { event.preventDefault(); stop(); renderer = undefined; };
  const restored = () => { renderer = createPulseRenderer(canvas); refresh(); };
  const viewer = new IntersectionObserver(([entry]) => { inView = entry.isIntersecting; clearPointer(); refresh(); });
  viewer.observe(canvas);
  const resize = new ResizeObserver(refresh);
  resize.observe(canvas);
  const colors = new MutationObserver(paletteChanged);
  for (let node: HTMLElement | null = canvas; node; node = node.parentElement) {
    colors.observe(node, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
  }
  host.addEventListener("pointermove", move, { passive: true });
  host.addEventListener("pointerleave", clearPointer);
  host.addEventListener("pointerdown", down, { passive: true });
  document.addEventListener("visibilitychange", refresh);
  reduced.addEventListener("change", refresh);
  theme.addEventListener("change", paletteChanged);
  window.addEventListener("resize", refresh);
  canvas.addEventListener("webglcontextlost", lost);
  canvas.addEventListener("webglcontextrestored", restored);
  return {
    update(next: GridOptions) { options = next; refresh(); },
    dispose() {
      stop();
      viewer.disconnect();
      resize.disconnect();
      colors.disconnect();
      host.removeEventListener("pointermove", move);
      host.removeEventListener("pointerleave", clearPointer);
      host.removeEventListener("pointerdown", down);
      document.removeEventListener("visibilitychange", refresh);
      reduced.removeEventListener("change", refresh);
      theme.removeEventListener("change", paletteChanged);
      window.removeEventListener("resize", refresh);
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      renderer?.dispose();
    },
  };
}

export const uniforms = ["u_size", "u_dpr", "u_origin", "u_time", "u_inward", "u_still", "u_pointer", "u_taps", "u_idle", "u_accent"];

export const pulseShader = `#version 300 es
precision highp float;
uniform vec2 u_size;
uniform float u_dpr;
uniform vec2 u_origin;
uniform float u_time;
uniform bool u_inward;
uniform bool u_still;
uniform vec2 u_pointer;
uniform vec3 u_taps[4];
uniform vec3 u_idle;
uniform vec3 u_accent;
out vec4 outColor;

float ring(float distanceFromOrigin, float radius, float width) {
  float delta = (distanceFromOrigin - radius) / width;
  return exp(-delta * delta);
}

void main() {
  vec2 p = vec2(gl_FragCoord.x / u_dpr, u_size.y - gl_FragCoord.y / u_dpr);
  vec2 dotCenter = (floor(p / 24.0) + 0.5) * 24.0;
  vec2 origin = u_origin * u_size;
  float d = distance(dotCenter, origin);
  float reach = length(max(origin, u_size - origin));
  float width = clamp(reach * 0.042, 12.0, 34.0);
  float wave = 0.0;
  if (u_still) {
    // Keep both rings in view on wide, tall and edge-origin surfaces.
    float span = min(u_size.x, u_size.y);
    float inner = ring(d, span * 0.23, max(8.0, span * 0.032));
    float outer = ring(d, span * 0.42, max(8.0, span * 0.032));
    wave = u_inward ? inner + 0.65 * outer : outer + 0.65 * inner;
  } else {
    for (int i = 0; i < 2; i++) {
      float age = mod(u_time + float(i) * 0.38, 4.2);
      float travel = age * reach / 2.8;
      float radius = u_inward ? reach - travel : travel;
      float fade = u_inward ? sin(3.14159 * clamp(age / 2.8, 0.0, 1.0)) : 1.0 - age / 4.2;
      wave += ring(d, radius, width) * fade * (i == 0 ? 1.0 : 0.65);
    }
    for (int i = 0; i < 4; i++) {
      float age = u_time - u_taps[i].z;
      if (age >= 0.0 && age < 2.2) {
        wave += 1.2 * ring(distance(dotCenter, u_taps[i].xy), age * 420.0, 34.0) * (1.0 - age / 2.2);
      }
    }
    if (u_pointer.x >= 0.0) wave += ring(distance(dotCenter, u_pointer), 0.0, 100.0);
  }
  float e = clamp(wave, 0.0, 1.0);
  float radius = 1.15 + 2.3 * e;
  float coverage = 1.0 - smoothstep(radius - 0.65, radius + 0.65, distance(p, dotCenter));
  float alpha = coverage * mix(0.17, 0.94, e);
  outColor = vec4(mix(u_idle, u_accent, smoothstep(0.08, 0.65, e)) * alpha, alpha);
}`;

"use client";

import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, forwardRef, useCallback, useEffect, useRef } from "react";
import { useResizablePanel } from "./resizable-panels-root";
import { clampSize, useIsomorphicLayoutEffect, useResizablePanels } from "./resizable-panels-state";
import { cn } from "@/lib/utils";

type HandleProps = ComponentPropsWithoutRef<"div"> & {
  /** The panel edge the handle sits on: its end (right or bottom) or its start (left or top). */
  side?: "start" | "end";
  /** Pixels moved by an arrow key. */
  step?: number;
  /** Pixels moved by an arrow key with Shift held. */
  largeStep?: number;
};

type Drag = { id: number; start: number; size: number; last: number; element: HTMLDivElement };

/** The draggable edge of a panel. Arrow keys resize it, Home and End go to its limits, and Escape cancels a drag. */
export const ResizableHandle = forwardRef<HTMLDivElement, HandleProps>(function ResizableHandle(
  { side = "end", step = 10, largeStep = 50, className, children, onKeyDown, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onLostPointerCapture, ...props },
  ref,
) {
  const group = useResizablePanels();
  const panel = useResizablePanel();
  const horizontal = group.direction === "horizontal";
  const fixed = panel.max <= panel.min;
  const disabled = group.disabled || panel.collapsed;
  const drag = useRef<Drag | null>(null);
  const latest = useRef(panel);
  useIsomorphicLayoutEffect(() => {
    latest.current = panel;
  });

  /** Whether moving right or down grows the panel. Right-to-left rows mirror the start and end edges. */
  const direction = (element: Element) => (side === "end" ? 1 : -1) * (horizontal && getComputedStyle(element).direction === "rtl" ? -1 : 1);
  const point = (event: PointerEvent) => (horizontal ? event.clientX : event.clientY);

  const finish = useCallback((cancel: boolean) => {
    const active = drag.current;
    if (!active) return;
    drag.current = null;
    if (cancel) latest.current.setSize(active.size);
    else if (active.last !== active.size) latest.current.commit(active.last);
    latest.current.setResizing(false);
    if (active.element.hasPointerCapture?.(active.id)) active.element.releasePointerCapture(active.id);
  }, []);

  useEffect(() => {
    if (!panel.resizing) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      finish(true);
    };
    const onBlur = () => finish(true);
    const cursor = document.body.style.cursor;
    document.body.style.cursor = horizontal ? "col-resize" : "row-resize";
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("blur", onBlur);
    return () => {
      document.body.style.cursor = cursor;
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("blur", onBlur);
    };
  }, [panel.resizing, horizontal, finish]);

  useEffect(() => () => finish(true), [finish]);

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled) return;
    const amount = event.shiftKey ? largeStep : step;
    const keys: Record<string, number> = horizontal ? { ArrowLeft: -amount, ArrowRight: amount } : { ArrowUp: -amount, ArrowDown: amount };
    let next: number;
    if (event.key === "Home") next = panel.min;
    else if (event.key === "End") {
      if (!Number.isFinite(panel.max)) return;
      next = panel.max;
    } else if (keys[event.key] !== undefined) next = clampSize(panel.size + keys[event.key] * direction(event.currentTarget), panel.min, panel.max);
    else return;
    event.preventDefault();
    if (next === panel.size) return;
    panel.setSize(next);
    panel.commit(next);
  };

  return (
    <div
      ref={ref}
      role="separator"
      tabIndex={disabled ? undefined : 0}
      aria-label="Resize panel"
      aria-controls={panel.panelId}
      // The line runs across the direction panels are laid out in.
      aria-orientation={horizontal ? "vertical" : "horizontal"}
      aria-valuenow={panel.size}
      aria-valuemin={panel.min}
      aria-valuemax={Number.isFinite(panel.max) ? panel.max : undefined}
      aria-disabled={disabled || undefined}
      data-slot="resizable-handle"
      data-side={side}
      data-resizing={panel.resizing || undefined}
      hidden={panel.collapsed}
      className={cn(
        "group/handle absolute z-20 touch-none outline-none select-none",
        horizontal ? "inset-y-0 w-2 pointer-coarse:w-8" : "inset-x-0 h-2 pointer-coarse:h-8",
        !disabled && !fixed && (horizontal ? "cursor-col-resize" : "cursor-row-resize"),
        horizontal && (side === "end" ? "end-0 translate-x-1/2 rtl:-translate-x-1/2" : "start-0 -translate-x-1/2 rtl:translate-x-1/2"),
        !horizontal && (side === "end" ? "bottom-0 translate-y-1/2" : "top-0 -translate-y-1/2"),
        className,
      )}
      onKeyDown={handleKeyDown}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.defaultPrevented || event.button !== 0 || disabled || fixed || drag.current) return;
        event.preventDefault();
        event.stopPropagation();
        if (event.pointerType !== "touch") event.currentTarget.focus({ preventScroll: true });
        drag.current = { id: event.pointerId, start: point(event), size: panel.size, last: panel.size, element: event.currentTarget };
        // Touch already has implicit capture on the pressed handle.
        if (event.pointerType !== "touch") event.currentTarget.setPointerCapture?.(event.pointerId);
        panel.setResizing(true);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        const active = drag.current;
        if (!active || active.id !== event.pointerId) return;
        const next = clampSize(active.size + (point(event) - active.start) * direction(event.currentTarget), panel.min, panel.max);
        if (next === active.last) return;
        active.last = next;
        panel.setSize(next);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        if (drag.current?.id === event.pointerId) finish(false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        if (drag.current?.id === event.pointerId) finish(true);
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event);
        finish(true);
      }}
      {...props}
    >
      {children ?? (
        <span
          aria-hidden
          data-slot="resizable-line"
          className={cn(
            "pointer-events-none absolute bg-border transition-colors group-hover/handle:bg-ring group-focus-visible/handle:bg-foreground group-data-resizing/handle:bg-foreground group-aria-disabled/handle:bg-border motion-reduce:transition-none",
            horizontal ? "inset-y-0 left-1/2 w-px -translate-x-1/2" : "inset-x-0 top-1/2 h-px -translate-y-1/2",
          )}
        />
      )}
    </div>
  );
});

"use client";

import { forwardRef, useCallback, useContext, useId, useImperativeHandle, useMemo, useRef, useState, version } from "react";
import {
  type ResizablePanelContextValue,
  type ResizablePanelProps,
  type ResizablePanelsProps,
  ResizablePanelContext,
  ResizablePanelsContext,
  availableSize,
  clampSize,
  useIsomorphicLayoutEffect,
  useResizablePanels,
} from "./resizable-panels-state";
import { cn } from "@/lib/utils";

/** Panels in a row or stack. Give a panel a size to make it resizable; a panel without one fills what is left. */
export const ResizablePanels = forwardRef<HTMLDivElement, ResizablePanelsProps>(function ResizablePanels(
  { direction = "horizontal", minFillSize = 0, disabled = false, motion = true, className, ...props },
  ref,
) {
  const context = useMemo(() => ({ direction, minFillSize, disabled, animated: motion }), [direction, minFillSize, disabled, motion]);
  return (
    <ResizablePanelsContext.Provider value={context}>
      <div ref={ref} data-slot="resizable-panels" data-direction={direction} className={cn("flex size-full min-h-0 min-w-0 overflow-hidden", direction === "vertical" && "flex-col", className)} {...props} />
    </ResizablePanelsContext.Provider>
  );
});

/** One panel. Put a ResizableHandle inside it to resize it from that edge. */
export const ResizablePanel = forwardRef<HTMLDivElement, ResizablePanelProps>(function ResizablePanel(
  { size: sizeProp, defaultSize, minSize = 0, maxSize = Infinity, collapsed = false, onSizeChange, onSizeCommit, onResizingChange, id, className, style, children, ...props },
  ref,
) {
  const group = useResizablePanels();
  const { direction, minFillSize, animated } = group;
  const generatedId = useId();
  const panelId = id ?? generatedId;
  const element = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => element.current as HTMLDivElement);
  const sized = sizeProp !== undefined || defaultSize !== undefined;
  const [inner, setInner] = useState(defaultSize ?? 0);
  const [available, setAvailable] = useState(Infinity);
  const [resizing, setResizingState] = useState(false);
  const stored = sizeProp ?? inner;
  const max = Math.max(minSize, Math.min(maxSize, available));
  // The stored size is kept, so a panel squeezed by a small window returns to it when there is room.
  const size = clampSize(stored, minSize, max);
  const horizontal = direction === "horizontal";

  useIsomorphicLayoutEffect(() => {
    const panel = element.current;
    // Found from the DOM: a parent's ref is not attached yet when this first runs.
    const root = panel?.closest<HTMLElement>("[data-slot=resizable-panels]");
    if (!sized || !panel || !root) return;
    const measure = () => setAvailable(availableSize(panel, root, direction, minFillSize));
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    for (const child of root.children) if (child !== panel) observer.observe(child);
    return () => observer.disconnect();
  }, [sized, direction, minFillSize]);

  const latest = useRef({ controlled: sizeProp !== undefined, onSizeChange, onSizeCommit, onResizingChange });
  useIsomorphicLayoutEffect(() => {
    latest.current = { controlled: sizeProp !== undefined, onSizeChange, onSizeCommit, onResizingChange };
  });
  const setSize = useCallback((next: number) => {
    if (!latest.current.controlled) setInner(next);
    latest.current.onSizeChange?.(next);
  }, []);
  const commit = useCallback((next: number) => latest.current.onSizeCommit?.(next), []);
  const setResizing = useCallback((next: boolean) => {
    setResizingState(next);
    latest.current.onResizingChange?.(next);
  }, []);

  const context: ResizablePanelContextValue = { panelId, size, min: minSize, max, collapsed, resizing, setSize, commit, setResizing };
  const shown = collapsed ? 0 : size;
  // React 18 forwards inert as a string attribute. React 19 treats it as a boolean.
  const inertProps = collapsed ? { inert: version.startsWith("18.") ? "" as unknown as boolean : true, "aria-hidden": true } : {};

  return (
    <ResizablePanelContext.Provider value={context}>
      <div
        ref={element}
        id={panelId}
        data-slot="resizable-panel"
        data-sized={sized || undefined}
        data-collapsed={collapsed || undefined}
        data-resizing={resizing || undefined}
        className={cn(
          "relative min-h-0 min-w-0",
          sized ? "shrink-0" : "flex-1",
          collapsed && "overflow-hidden",
          sized && animated && !resizing && (horizontal ? "transition-[width] duration-200 ease-out motion-reduce:transition-none" : "transition-[height] duration-200 ease-out motion-reduce:transition-none"),
          className,
        )}
        style={sized ? { ...style, [horizontal ? "width" : "height"]: shown } : style}
        {...inertProps}
        {...props}
      >
        {children}
      </div>
    </ResizablePanelContext.Provider>
  );
});

export function useResizablePanel() {
  const context = useContext(ResizablePanelContext);
  if (!context) throw new Error("ResizableHandle must be rendered inside <ResizablePanel>.");
  return context;
}

"use client";

import { type ComponentPropsWithoutRef, createContext, useContext, useEffect, useLayoutEffect } from "react";

export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type ResizablePanelsDirection = "horizontal" | "vertical";

export type ResizablePanelsProps = ComponentPropsWithoutRef<"div"> & {
  /** "horizontal" places panels side by side; "vertical" stacks them. */
  direction?: ResizablePanelsDirection;
  /** The space, in pixels, always left for the panel that fills. */
  minFillSize?: number;
  /** Turns off every handle. */
  disabled?: boolean;
  /** The collapse transition. Reduced motion is always honored. */
  motion?: boolean;
};

export type ResizablePanelProps = ComponentPropsWithoutRef<"div"> & {
  /** The panel's size in pixels, when your app owns it. Leave out both sizes for a panel that fills the remaining space. */
  size?: number;
  /** The starting size in pixels, when the panel keeps its own size. */
  defaultSize?: number;
  minSize?: number;
  maxSize?: number;
  /** Hides the panel and keeps its size for when it returns. */
  collapsed?: boolean;
  /** Called with live sizes while resizing. */
  onSizeChange?: (size: number) => void;
  /** Called once per finished drag or key press, for saving. */
  onSizeCommit?: (size: number) => void;
  /** Reports when a drag starts and ends. */
  onResizingChange?: (resizing: boolean) => void;
};

export type ResizablePanelsContextValue = {
  direction: ResizablePanelsDirection;
  minFillSize: number;
  disabled: boolean;
  animated: boolean;
};

export const ResizablePanelsContext = createContext<ResizablePanelsContextValue | null>(null);

export function useResizablePanels() {
  const context = useContext(ResizablePanelsContext);
  if (!context) throw new Error("ResizablePanel must be rendered inside <ResizablePanels>.");
  return context;
}

export type ResizablePanelContextValue = {
  panelId: string;
  size: number;
  min: number;
  max: number;
  collapsed: boolean;
  resizing: boolean;
  setSize: (size: number) => void;
  commit: (size: number) => void;
  setResizing: (resizing: boolean) => void;
};

export const ResizablePanelContext = createContext<ResizablePanelContextValue | null>(null);

export const clampSize = (size: number, min: number, max: number) => Math.round(Math.max(min, Math.min(Math.max(min, max), size)));

/** The most a panel can take: the group's size minus its sized neighbours and the space kept for the filling panel. */
export function availableSize(panel: HTMLElement, root: HTMLElement, direction: ResizablePanelsDirection, minFillSize: number) {
  const total = direction === "horizontal" ? root.clientWidth : root.clientHeight;
  if (total <= 0) return Infinity;
  const others = [...root.children].filter((child): child is HTMLElement => child !== panel && child instanceof HTMLElement && child.hasAttribute("data-sized"));
  return total - minFillSize - others.reduce((sum, child) => sum + (direction === "horizontal" ? child.offsetWidth : child.offsetHeight), 0);
}

"use client";

export { type ResizablePanelsProps, type ResizablePanelProps, type ResizablePanelsDirection } from "./resizable-panels-state";
export { ResizablePanels, ResizablePanel, useResizablePanel } from "./resizable-panels-root";
export { ResizableHandle } from "./resizable-panels-handle";

export type ResizeRect = { x: number; y: number; width: number; height: number };
export type ResizePoint = { x: number; y: number };
export type ResizeHandleName = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw";

/** The dragged edges, in the rect's units. An axis the handle does not move is left out. */
export type ResizeEdges = { x?: number; y?: number };
export type ResizeSnap = (edges: ResizeEdges, handle: ResizeHandleName) => ResizeEdges;

export type ResizeLimits = {
  minWidth?: number;
  minHeight?: number;
  maxWidth?: number;
  maxHeight?: number;
};

export type ResizeOptions = ResizeLimits & {
  /** Keeps width divided by height at this value. */
  aspectRatio?: number;
  /** Grows both sides equally, so the centre stays put. */
  fromCenter?: boolean;
  /** Places dragged edges on multiples of this value. */
  step?: number;
  /** Moves dragged edges, for example to your alignment guides. Limits still apply afterwards. */
  snap?: ResizeSnap;
};

export const cornerHandles: ResizeHandleName[] = ["nw", "ne", "se", "sw"];
export const edgeHandles: ResizeHandleName[] = ["n", "e", "s", "w"];

/** Which way each handle moves: x is -1 left, 1 right; y is -1 up, 1 down. */
export const handleAxes: Record<ResizeHandleName, readonly [number, number]> = {
  n: [0, -1],
  ne: [1, -1],
  e: [1, 0],
  se: [1, 1],
  s: [0, 1],
  sw: [-1, 1],
  w: [-1, 0],
  nw: [-1, -1],
};

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), Math.max(min, max));

export const sameRect = (a: ResizeRect, b: ResizeRect) => a.x === b.x && a.y === b.y && a.width === b.width && a.height === b.height;

export function resolveHandles(handles: "all" | "corners" | "edges" | ResizeHandleName[]) {
  if (handles === "all") return [...cornerHandles, ...edgeHandles];
  if (handles === "corners") return cornerHandles;
  if (handles === "edges") return edgeHandles;
  return handles;
}

/** The rect after moving a handle by `delta`. It never flips: past the opposite edge it stops at the minimum size. */
export function resizeRect(start: ResizeRect, handle: ResizeHandleName, delta: ResizePoint, options: ResizeOptions = {}): ResizeRect {
  const { minWidth = 1, minHeight = 1, maxWidth = Infinity, maxHeight = Infinity, aspectRatio, fromCenter = false, step, snap } = options;
  const [dirX, dirY] = handleAxes[handle];
  const right = start.x + start.width;
  const bottom = start.y + start.height;
  const centerX = start.x + start.width / 2;
  const centerY = start.y + start.height / 2;
  const onGrid = (value: number) => (step && step > 0 ? Math.round(value / step) * step : value);

  let edges: ResizeEdges = {
    x: dirX ? onGrid((dirX > 0 ? right : start.x) + delta.x) : undefined,
    y: dirY ? onGrid((dirY > 0 ? bottom : start.y) + delta.y) : undefined,
  };
  if (snap) {
    const snapped = snap(edges, handle);
    edges = { x: dirX ? (snapped.x ?? edges.x) : undefined, y: dirY ? (snapped.y ?? edges.y) : undefined };
  }

  const span = (edge: number, dir: number, low: number, high: number, center: number) => (fromCenter ? dir * (edge - center) * 2 : dir * (edge - (dir > 0 ? low : high)));
  let width = edges.x === undefined ? start.width : span(edges.x, dirX, start.x, right, centerX);
  let height = edges.y === undefined ? start.height : span(edges.y, dirY, start.y, bottom, centerY);

  if (aspectRatio && aspectRatio > 0) {
    const change = (value: number, from: number) => (from > 0 ? Math.abs(value / from - 1) : 0);
    // A corner follows whichever axis moved furthest; an edge follows its own axis.
    const widthLeads = dirY === 0 || (dirX !== 0 && change(width, start.width) >= change(height, start.height));
    width = clamp(widthLeads ? width : height * aspectRatio, Math.max(minWidth, minHeight * aspectRatio), Math.min(maxWidth, maxHeight * aspectRatio));
    height = width / aspectRatio;
  } else {
    width = clamp(width, minWidth, maxWidth);
    height = clamp(height, minHeight, maxHeight);
  }

  const place = (dir: number, low: number, high: number, center: number, size: number) => {
    if (fromCenter || dir === 0) return center - size / 2;
    return dir > 0 ? low : high - size;
  };
  return { x: place(dirX, start.x, right, centerX, width), y: place(dirY, start.y, bottom, centerY, height), width, height };
}

