import { AlertCircle, Check, LoaderCircle } from "lucide-react";
import { motion as animated, useReducedMotion } from "motion/react";
import { forwardRef, useEffect, useRef, useState, type ButtonHTMLAttributes, type ReactNode } from "react";
import { cn } from "@/lib/utils";

export type ButtonStatus = "idle" | "loading" | "success" | "error";
const defaultLabels = { idle: "Save changes", loading: "Saving…", success: "Saved", error: "Try again" };
const defaultIcons = {
  idle: null, loading: <LoaderCircle />, success: <Check />, error: <AlertCircle />,
};
const states = Object.keys(defaultLabels) as ButtonStatus[];

export type StatefulButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
  action?: () => Promise<unknown>;
  status?: ButtonStatus;
  defaultStatus?: ButtonStatus;
  labels?: Partial<Record<ButtonStatus, ReactNode>>;
  icons?: Partial<Record<ButtonStatus, ReactNode>>;
  announcements?: Partial<Record<"success" | "error", string>>;
  widthMode?: "stable" | "animated";
  motion?: boolean;
  duration?: number;
  resetAfter?: number | false;
};

export const StatefulButton = forwardRef<HTMLButtonElement, StatefulButtonProps>(function StatefulButton({
  action, status: controlled, defaultStatus = "idle", labels, icons, announcements,
  widthMode = "stable", motion = true, duration = 200, resetAfter = 1800,
  disabled, className, onClick, type = "button", ...props
}, ref) {
  const [local, setLocal] = useState<ButtonStatus>(defaultStatus);
  const status = controlled ?? local;
  const pending = useRef(false);
  const reset = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const mounted = useRef(false);
  const reduced = useReducedMotion();
  const animate = motion && !reduced && duration > 0;
  const visibleLabel = useRef<HTMLSpanElement>(null);
  const [labelWidth, setLabelWidth] = useState<number>();
  useEffect(() => {
    const node = visibleLabel.current;
    if (widthMode !== "animated" || !node || typeof ResizeObserver === "undefined") return;
    const measure = () => setLabelWidth(node.getBoundingClientRect().width);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, [status, widthMode]);

  const busy = status === "loading";
  const label = labels?.[status] ?? defaultLabels[status];
  const message = (status === "success" || status === "error")
    ? announcements?.[status] ?? (typeof label === "string" ? label : defaultLabels[status])
    : "";

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(reset.current);
    };
  }, []);

  function content(state: ButtonStatus) {
    const icon = icons && state in icons ? icons[state] : defaultIcons[state];
    return <>
      {icon && <span aria-hidden="true" className={cn("inline-flex [&>svg]:size-4", state === "loading" && animate && "motion-safe:animate-spin")}
        style={{ animationDuration: `${duration * 4}ms` }}>{icon}</span>}
      {labels?.[state] ?? defaultLabels[state]}
    </>;
  }

  return <>
    <button {...props} ref={ref} type={type} disabled={disabled} data-state={status}
      aria-busy={busy} aria-disabled={busy || disabled || props["aria-disabled"]}
      className={cn("inline-grid h-11 place-items-center overflow-hidden rounded-md bg-primary px-5 text-sm font-semibold text-primary-foreground shadow-[inset_0_1px_0_rgb(255_255_255/0.3),inset_0_-2px_0_rgb(0_0_0/0.2),0_1px_2px_rgb(0_0_0/0.3)] hover:brightness-95 focus-visible:outline focus-visible:outline-1 focus-visible:outline-offset-2 disabled:opacity-50", className)}
      onClick={async event => {
        if (busy || pending.current || props["aria-disabled"] === true || props["aria-disabled"] === "true") {
          event.preventDefault();
          return;
        }
        onClick?.(event);
        if (event.defaultPrevented || !action) return;
        pending.current = true;
        clearTimeout(reset.current);
        setLocal("loading");
        try {
          await action();
          if (mounted.current) {
            setLocal("success");
            if (resetAfter !== false) reset.current = setTimeout(() => setLocal("idle"), resetAfter);
          }
        } catch {
          if (mounted.current) setLocal("error");
        } finally {
          pending.current = false;
        }
      }}>
      <animated.span initial={false} animate={{ width: widthMode === "animated" && animate && labelWidth !== undefined ? labelWidth : "auto" }}
        transition={{ duration: animate ? duration / 1000 : 0 }} className="inline-grid place-items-center">
        {states.map(state => {
          const active = state === status;
          if (!active && widthMode === "animated") return null;
          return <animated.span key={state} ref={active ? visibleLabel : undefined} aria-hidden={!active || undefined}
            className="col-start-1 row-start-1 inline-flex w-max items-center justify-center gap-2 whitespace-nowrap"
            style={{ visibility: active ? "visible" : "hidden" }}
            initial={false} animate={{ opacity: active ? 1 : 0, y: active ? 0 : 3 }}
            transition={{ duration: animate ? duration / 1000 : 0 }}>
            {content(state)}
          </animated.span>;
        })}
      </animated.span>
    </button>
    <span role="status" aria-atomic="true" className="sr-only">{message}</span>
  </>;
});

"use client";

import { CloudUpload } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { UploadRow, type RowRenderer } from "./upload-row";
import { acceptedTypes, useUploadQueue, type UploadAccept, type UploadEntry, type UploadOptions } from "./upload-queue";

export { useUploadQueue, type UploadHandler, type UploadEntry, type UploadAccept } from "./upload-queue";

type ViewProps = {
  accept?: UploadAccept; className?: string; buttonClassName?: string; hint?: string;
  motion?: boolean; disabled?: boolean; renderRow?: RowRenderer;
};
export type UploadDropzoneProps = UploadOptions & ViewProps;

function summary(entries: UploadEntry[]) {
  const counts = { uploaded: 0, uploading: 0, failed: 0, rejected: 0 };
  for (const { status } of entries) counts[status]++;
  const parts: string[] = [];
  if (counts.uploaded) parts.push(`${counts.uploaded} ${counts.uploaded === 1 ? "file" : "files"} uploaded`);
  for (const status of ["uploading", "failed", "rejected"] as const) {
    if (counts[status]) parts.push(`${counts[status]} ${status}`);
  }
  return parts.join(" · ");
}

export function UploadDropzoneView({ entries, addFiles, retry, accept, className, buttonClassName, hint,
  motion = true, disabled, renderRow }: ReturnType<typeof useUploadQueue> & ViewProps) {
  const picker = useRef<HTMLInputElement>(null);
  const browse = useRef<HTMLButtonElement>(null);
  const root = useRef<HTMLElement>(null);
  const dragDepth = useRef(0);
  const [dragging, setDragging] = useState(false);
  const previousFailures = useRef(new Set<number>());
  const hintId = useId();
  const hasRows = entries.length > 0;

  useEffect(() => {
    const failed = entries.filter(row => row.status === "failed");
    const firstNew = failed.find(row => !previousFailures.current.has(row.id));
    previousFailures.current = new Set(failed.map(row => row.id));
    if (firstNew && document.activeElement === browse.current) {
      root.current?.querySelector<HTMLButtonElement>(`[data-retry="${firstNew.id}"]`)?.focus();
    }
  }, [entries]);

  function retryRow(id: number) {
    if (disabled) return;
    browse.current?.focus();
    retry(id);
  }

  return <section ref={root} aria-label="File uploads" className={cn("w-full min-w-0 rounded-xl border border-dashed border-border bg-background p-4 text-foreground",
    dragging && !disabled && "border-primary bg-primary/5", className)}
    onDragEnter={event => {
      if (!event.dataTransfer.types.includes("Files")) return;
      event.preventDefault();
      dragDepth.current++;
      setDragging(true);
    }}
    onDragLeave={event => {
      event.preventDefault();
      dragDepth.current = Math.max(0, dragDepth.current - 1);
      if (!dragDepth.current) setDragging(false);
    }}
    onDragOver={event => {
      if (!event.dataTransfer.types.includes("Files")) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = disabled ? "none" : "copy";
    }}
    onDrop={event => {
      event.preventDefault();
      dragDepth.current = 0;
      setDragging(false);
      if (!disabled) addFiles(event.dataTransfer.files);
    }}>
    <input ref={picker} type="file" hidden multiple disabled={disabled} accept={acceptedTypes(accept).join(",") || undefined}
      onChange={event => {
        if (!disabled && event.target.files) addFiles(event.target.files);
        event.target.value = "";
      }} />
    <div className={cn("flex gap-2", hasRows ? "flex-wrap items-center justify-between" : "flex-col items-center py-4 text-center")}>
      {!hasRows && <><span className="grid size-10 place-items-center rounded-full bg-muted text-muted-foreground">
        <CloudUpload aria-hidden="true" className="size-5" /></span>
        <p className="text-sm font-medium">{dragging ? "Drop to add files" : "Drop files to upload"}</p></>}
      <p role="status" aria-atomic="true" className={cn("text-lg font-semibold leading-tight", !hasRows && "sr-only")}>{summary(entries)}</p>
      <button ref={browse} type="button" disabled={disabled} aria-describedby={hint ? hintId : undefined} onClick={() => picker.current?.click()}
        className={cn("min-h-9 rounded-md bg-primary px-3 text-sm font-medium text-primary-foreground focus-visible:outline focus-visible:outline-1 disabled:opacity-50", buttonClassName)}>
        {hasRows ? "Add more files" : "Browse files"}
      </button>
    </div>
    {hasRows && <ul aria-label="Files" className="mt-3 grid max-h-80 min-w-0 gap-1.5 overflow-y-auto">
      {entries.map(entry => <UploadRow key={entry.id} entry={entry} motion={motion} disabled={disabled} retry={retryRow} renderRow={renderRow} />)}
    </ul>}
    {hint && <p id={hintId} className={cn("text-xs text-muted-foreground", hasRows ? "mt-3" : "mt-2 text-center")}>{hint}</p>}
  </section>;
}

export function UploadDropzone({ upload, maxFiles, ...props }: UploadDropzoneProps) {
  const queue = useUploadQueue({ upload, maxFiles, accept: props.accept });
  return <UploadDropzoneView {...props} {...queue} />;
}

"use client";

import { useEffect, useRef, useState } from "react";

export type UploadHandler = (file: File, onProgress: (fraction: number) => void, signal: AbortSignal) => Promise<void>;
export type UploadAccept = Record<string, readonly string[]>;
export type UploadEntry = {
  id: number;
  name: string;
  size: number;
  status: "uploading" | "uploaded" | "failed" | "rejected";
  progress?: number;
  message?: string;
};
export type UploadOptions = { upload: UploadHandler; accept?: UploadAccept; maxFiles?: number };

export function acceptedTypes(accept?: UploadAccept) {
  return Object.entries(accept ?? {}).flatMap(([mime, extensions]) => [mime, ...extensions])
    .map(token => token.trim().toLowerCase()).filter(Boolean);
}

function accepts(file: File, types: string[]) {
  return !types.length || types.some(type => {
    if (type.startsWith(".")) return file.name.toLowerCase().endsWith(type);
    if (type.endsWith("/*")) return file.type.toLowerCase().startsWith(type.slice(0, -1));
    return file.type.toLowerCase() === type;
  });
}

/** The upload callback supplies the transfer. Only failed files are kept for retry. */
export function useUploadQueue({ upload, accept, maxFiles = Infinity }: UploadOptions) {
  const [entries, setEntries] = useState<UploadEntry[]>([]);
  const nextId = useRef(0);
  const attempts = useRef(new Map<number, AbortController>());
  const failures = useRef(new Map<number, File>());
  useEffect(() => {
    const requests = attempts.current;
    const failed = failures.current;
    return () => {
      for (const controller of requests.values()) controller.abort();
      requests.clear();
      failed.clear();
    };
  }, []);

  function update(id: number, patch: Partial<UploadEntry>) {
    setEntries(rows => rows.map(row => row.id === id ? { ...row, ...patch } : row));
  }

  async function run(id: number, file: File) {
    const controller = new AbortController();
    attempts.current.set(id, controller);
    try {
      await upload(file, fraction => {
        if (attempts.current.get(id) !== controller || !Number.isFinite(fraction)) return;
        update(id, { progress: Math.max(0, Math.min(1, fraction)) });
      }, controller.signal);
      if (!controller.signal.aborted) update(id, { status: "uploaded", progress: 1 });
    } catch (error) {
      if (!controller.signal.aborted) {
        failures.current.set(id, file);
        update(id, { status: "failed", message: error instanceof Error && error.message ? error.message : "Upload failed." });
      }
    } finally {
      attempts.current.delete(id);
    }
  }

  function addFiles(files: Iterable<File>) {
    const types = acceptedTypes(accept);
    const batch: UploadEntry[] = [];
    const pending: { id: number; file: File }[] = [];
    for (const file of files) {
      const id = ++nextId.current;
      let message: string | undefined;
      if (!accepts(file, types)) message = "File type isn’t accepted.";
      else if (pending.length >= maxFiles) message = `Limit is ${maxFiles} per selection.`;
      batch.push({ id, name: file.name, size: file.size, status: message ? "rejected" : "uploading", message });
      if (!message) pending.push({ id, file });
    }
    if (batch.length) setEntries(rows => [...rows, ...batch]);
    for (const { id, file } of pending) void run(id, file);
  }

  function retry(id: number) {
    const file = failures.current.get(id);
    if (!file) return;
    failures.current.delete(id);
    update(id, { status: "uploading", message: undefined, progress: undefined });
    void run(id, file);
  }
  return { entries, addFiles, retry };
}

"use client";

import type { ReactNode } from "react";
import { Check, FileText, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";
import type { UploadEntry } from "./upload-queue";

export type RowRenderer = (entry: UploadEntry, retry: () => void) => ReactNode;

export function UploadRow({ entry, retry, motion, disabled, renderRow }: {
  entry: UploadEntry; retry: (id: number) => void; motion: boolean; disabled?: boolean; renderRow?: RowRenderer;
}) {
  const { id, name, status, progress, message } = entry;
  const percent = progress === undefined ? undefined : Math.round(progress * 100);
  if (renderRow) return <li data-status={status}>{renderRow(entry, () => retry(id))}</li>;
  return <li data-status={status} className="grid gap-1.5 rounded-md bg-border/65 px-3 py-2.5 dark:bg-muted/65">
    <div className="flex min-w-0 items-center gap-2">
      <FileText aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
      <span title={name} className="min-w-0 flex-1 truncate text-sm font-medium">{name}</span>
      {status === "uploaded" && <>
        <Check aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
        <span className="sr-only">Uploaded</span>
      </>}
      {status === "uploading" && <span className="text-xs tabular-nums text-muted-foreground">{percent === undefined ? "Uploading…" : `${percent}%`}</span>}
      {status === "failed" && <button type="button" data-retry={id} disabled={disabled} aria-label={`Retry ${name}`} title="Retry upload" onClick={() => retry(id)}
        className="grid size-8 shrink-0 place-items-center rounded-md hover:bg-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring">
        <RotateCcw aria-hidden="true" className="size-4" />
      </button>}
    </div>
    {message && <p className="break-words text-xs text-destructive">{message}</p>}
    {status === "uploading" && <div role="progressbar" aria-label={`Upload progress for ${name}`}
      aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent}
      className="h-1.5 overflow-hidden rounded-full bg-foreground/10">
      <div className={cn("h-full rounded-full bg-primary",
        percent === undefined && "w-1/3", motion && (percent === undefined ? "motion-safe:animate-pulse" : "motion-safe:transition-[width]"))}
        style={percent !== undefined ? { width: `${percent}%` } : undefined} />
    </div>}
  </li>;
}

"use client";

import { type KeyboardEvent, type PointerEvent as ReactPointerEvent, useEffect, useRef, useState } from "react";
import { useVersionComparison } from "./version-comparison-state";

const clampRatio = (value: number) => Math.round(Math.min(1, Math.max(0, value)) * 1000) / 1000;

/** The Swipe mode divider. Drag it or use the arrow keys. Escape cancels a drag. */
export function VersionComparisonDivider({ stageRef }: { stageRef: { current: HTMLDivElement | null } }) {
  const { divider, disabled, messages, setDivider, onDividerChange, onDividerCommit } = useVersionComparison();
  const stop = useRef<(() => void) | null>(null);
  const [dragging, setDragging] = useState(false);
  useEffect(() => () => stop.current?.(), []);

  const show = (next: number) => {
    setDivider(next);
    onDividerChange?.(next);
  };
  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (disabled || event.button !== 0 || stop.current) return;
    event.currentTarget.dataset.pointerFocus = "";
    const pointerId = event.pointerId;
    const start = divider;
    let last = divider;
    const at = (clientX: number) => {
      const rect = stageRef.current?.getBoundingClientRect();
      return rect?.width ? clampRatio((clientX - rect.left) / rect.width) : last;
    };
    const listening = new AbortController();
    const { signal } = listening;
    const end = () => {
      listening.abort();
      stop.current = null;
      setDragging(false);
    };
    const cancel = () => {
      show(start);
      end();
    };
    window.addEventListener("pointermove", (next) => {
      if (next.pointerId !== pointerId) return;
      last = at(next.clientX);
      show(last);
    }, { signal });
    window.addEventListener("pointerup", (next) => {
      if (next.pointerId !== pointerId) return;
      if (last !== start) onDividerCommit?.(last);
      end();
    }, { signal });
    window.addEventListener("pointercancel", (next) => {
      if (next.pointerId === pointerId) cancel();
    }, { signal });
    window.addEventListener("blur", cancel, { signal });
    window.addEventListener("keydown", (next) => {
      if (next.key !== "Escape") return;
      next.preventDefault();
      next.stopPropagation();
      cancel();
    }, { signal, capture: true });
    stop.current = () => listening.abort();
    setDragging(true);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const amount = event.shiftKey ? 0.1 : 0.01;
    const targets: Record<string, number> = { ArrowLeft: divider - amount, ArrowDown: divider - amount, ArrowRight: divider + amount, ArrowUp: divider + amount, Home: 0, End: 1 };
    const target = targets[event.key];
    if (disabled || target === undefined) return;
    event.preventDefault();
    const next = clampRatio(target);
    if (next === divider) return;
    show(next);
    onDividerCommit?.(next);
  };

  return (
    <>
      <span aria-hidden data-slot="version-comparison-divider-line" className="pointer-events-none absolute inset-y-0 z-[2] w-0.5 -translate-x-1/2 bg-primary" style={{ left: `${divider * 100}%` }} />
      <div
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={messages.divider}
        aria-orientation="horizontal"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(divider * 100)}
        aria-valuetext={`${Math.round(divider * 100)}%`}
        aria-disabled={disabled || undefined}
        data-slot="version-comparison-divider"
        data-dragging={dragging ? "" : undefined}
        className="group/divider absolute inset-y-0 z-[2] grid w-11 -translate-x-1/2 cursor-ew-resize touch-none place-items-center outline-none aria-disabled:cursor-default"
        // At either edge the handle bleeds off the stage with the line, so only half shows.
        style={{ left: `${divider * 100}%` }}
        onPointerDown={onPointerDown}
        onKeyDown={onKeyDown}
        onBlur={(event) => {
          delete event.currentTarget.dataset.pointerFocus;
        }}
      >
        <span aria-hidden className="relative grid size-7 place-items-center rounded-full bg-primary text-primary-foreground transition-transform group-data-dragging/divider:scale-110 group-focus-visible/divider:not-group-data-pointer-focus/divider:ring-2 group-focus-visible/divider:not-group-data-pointer-focus/divider:ring-ring motion-reduce:transition-none">
          <svg viewBox="0 0 16 16" className="size-4" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M6 4.5 2.5 8 6 11.5M10 4.5 13.5 8 10 11.5" />
          </svg>
        </span>
      </div>
    </>
  );
}

"use client";

import { ContextMenu, ContextMenuButton, ContextMenuContent, ContextMenuItem, ContextMenuTarget } from "@/components/ui/context-menu";
import { InlineEdit, InlineEditEditor, InlineEditError, InlineEditInput, InlineEditPreview } from "@/components/ui/inline-edit";
import { type ComparisonSlot, type ComparisonVersion, useVersionComparison } from "./version-comparison-state";
import { cn } from "@/lib/utils";

/** A version's letter and name on the stage, with Rename, Duplicate and Delete in its menu. */
export function VersionComparisonLabel({ version, slot, align = "left" }: { version: ComparisonVersion; slot: ComparisonSlot; align?: "left" | "right" }) {
  const { container, disabled, renamingId, messages, onRename, onDuplicate, onDelete, setRenamingId } = useVersionComparison();
  const hasActions = !!(onRename || onDuplicate || onDelete);
  return (
    <ContextMenu disabled={disabled || !hasActions}>
      <ContextMenuTarget
        data-slot="version-comparison-label"
        className={cn("group/label absolute top-2 z-[1] flex max-w-[calc(100%-5rem)] min-w-0 items-center gap-1 rounded-[5px] bg-background/90 py-0.5 pr-0.5 pl-1.5 text-xs text-foreground", align === "left" ? "left-2" : "right-2")}
      >
        <span className="font-medium">{slot === "a" ? messages.versionA : messages.versionB}</span>
        {onRename ? (
          <InlineEdit label={messages.name} value={version.name} variant="ghost" editing={renamingId === version.id} disabled={disabled} className="min-w-0" validate={(name) => (name.trim() ? null : messages.name)} onEditingChange={(editing) => setRenamingId(editing ? version.id : null)} onSave={(name) => onRename(version.id, name.trim())}>
            <InlineEditPreview className="block min-h-5 max-w-full truncate px-0.5 text-xs text-foreground/70 after:hidden" />
            <InlineEditEditor className="after:hidden">
              <InlineEditInput className="h-5 w-28 px-0.5 text-xs" />
            </InlineEditEditor>
            <InlineEditError className="text-xs" />
          </InlineEdit>
        ) : (
          <span className="min-w-0 truncate text-foreground/70">{version.name}</span>
        )}
        {hasActions && <ContextMenuButton aria-label={messages.actions(version.name)} className="relative size-5 shrink-0 after:absolute after:-inset-3 [&_svg]:size-3.5" />}
      </ContextMenuTarget>
      <ContextMenuContent container={container} positionMethod={container ? "fixed" : undefined}>
        {onRename && <ContextMenuItem onClick={() => setRenamingId(version.id)}>{messages.rename}</ContextMenuItem>}
        {onDuplicate && <ContextMenuItem onClick={() => onDuplicate(version.id)}>{messages.duplicate}</ContextMenuItem>}
        {onDelete && (
          <ContextMenuItem variant="destructive" disabled={version.current} onClick={() => onDelete(version.id)}>
            {messages.delete}
          </ContextMenuItem>
        )}
      </ContextMenuContent>
    </ContextMenu>
  );
}

"use client";

import { forwardRef, useState, useSyncExternalStore } from "react";
import { VersionComparisonChanges, VersionComparisonOpacity, VersionComparisonStage } from "./version-comparison-stage";
import { VersionComparisonToolbar } from "./version-comparison-toolbar";
import { type ComparisonMode, type ComparisonSlot, type VersionComparisonProps, VersionComparisonContext, defaultMessages } from "./version-comparison-state";
import { cn } from "@/lib/utils";

const phoneQuery = "(max-width: 639px)";
const subscribePhone = (listener: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const query = window.matchMedia(phoneQuery);
  query.addEventListener("change", listener);
  return () => query.removeEventListener("change", listener);
};
const readPhone = () => (typeof window.matchMedia === "function" ? window.matchMedia(phoneQuery).matches : false);

/** Puts two design versions next to each other. Your app owns the versions and applies the choice. */
export const VersionComparison = forwardRef<HTMLDivElement, VersionComparisonProps>(function VersionComparison(
  {
    label,
    versions,
    compare,
    onCompareChange,
    renderVersion,
    changes,
    onUse,
    onRename,
    onDuplicate,
    onDelete,
    onRetry,
    defaultMode,
    onDividerChange,
    onDividerCommit,
    onOpacityChange,
    onOpacityCommit,
    aspectRatio = "16 / 10",
    container,
    disabled = false,
    messages: messageOverrides,
    className,
    children,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const phone = useSyncExternalStore(subscribePhone, readPhone, () => false);
  const [chosenMode, setMode] = useState<ComparisonMode | null>(defaultMode ?? null);
  const [divider, setDivider] = useState(0.5);
  const [opacity, setOpacity] = useState(0.5);
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const find = (id: string | null) => versions.find((version) => version.id === id) ?? null;
  const { a, b } = compare;

  const chooseSlot = (slot: ComparisonSlot, id: string) => {
    if (id === (slot === "a" ? a : b)) return;
    if (id === (slot === "a" ? b : a)) onCompareChange({ a: b, b: a });
    else onCompareChange(slot === "a" ? { a: id, b } : { a, b: id });
  };

  return (
    <VersionComparisonContext.Provider
      value={{
        versions,
        compare,
        renderVersion,
        changes,
        onUse,
        onRename,
        onDuplicate,
        onDelete,
        onRetry,
        onDividerChange,
        onDividerCommit,
        onOpacityChange,
        onOpacityCommit,
        container,
        versionA: find(a),
        versionB: find(b),
        mode: chosenMode ?? (phone ? "swipe" : "side"),
        divider,
        opacity,
        aspectRatio,
        disabled,
        renamingId,
        messages,
        setMode,
        setDivider,
        setOpacity,
        setRenamingId,
        chooseSlot,
        swap: () => onCompareChange({ a: b, b: a }),
      }}
    >
      <div ref={ref} role="group" aria-label={label} data-slot="version-comparison" data-disabled={disabled ? "" : undefined} className={cn("@container/versions grid w-full min-w-0 content-start gap-3 text-sm", className)} {...props}>
        {children ?? (
          <>
            <VersionComparisonToolbar />
            <VersionComparisonStage />
            <VersionComparisonOpacity />
            <VersionComparisonChanges />
          </>
        )}
      </div>
    </VersionComparisonContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type CSSProperties, type ReactNode, forwardRef, useRef } from "react";
import { NumberField, NumberFieldLabel, NumberFieldSlider, NumberFieldSliderFill, NumberFieldSliderThumb, NumberFieldValue } from "@/components/ui/number-field";
import { VersionComparisonDivider } from "./version-comparison-divider";
import { VersionComparisonLabel } from "./version-comparison-label";
import { type ComparisonSlot, type ComparisonVersion, useVersionComparison } from "./version-comparison-state";
import { cn } from "@/lib/utils";

function UseButton({ version, align = "right", top = false }: { version: ComparisonVersion | null; align?: "left" | "right"; top?: boolean }) {
  const { disabled, messages, onUse } = useVersionComparison();
  if (!onUse || !version || version.current || (version.status ?? "ready") !== "ready") return null;
  return (
    <button
      type="button"
      aria-label={messages.use(version.name)}
      disabled={disabled}
      className={cn("absolute z-[3] h-7 rounded-[5px] bg-primary px-2.5 text-xs font-medium text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 motion-reduce:transition-none pointer-coarse:h-11 pointer-coarse:px-4", top ? "top-1.5 h-6 px-2" : "bottom-2", align === "left" ? "left-2" : "right-2")}
      onClick={() => onUse(version.id)}
    >
      {messages.useShort}
    </button>
  );
}

function Pane({ version, slot, align = "left", className, style, children }: { version: ComparisonVersion | null; slot: ComparisonSlot; align?: "left" | "right"; className?: string; style?: CSSProperties; children?: ReactNode }) {
  const { renderVersion, onRetry, disabled, messages } = useVersionComparison();
  const status = version?.status ?? "ready";
  const letter = slot === "a" ? messages.versionA : messages.versionB;
  return (
    <div role="group" aria-label={version ? `${letter}: ${version.name}` : letter} aria-busy={status === "loading" || undefined} data-slot="version-comparison-pane" data-version-slot={slot} className={cn("overflow-hidden rounded-md bg-foreground/5", className)} style={style}>
      <div className="absolute inset-0 grid place-items-center">
        {version && status === "ready" && renderVersion(version, { slot, size: "stage" })}
        {status === "loading" && <span role="status" aria-label={messages.loading} className="size-6 animate-spin rounded-full border-2 border-foreground/20 border-t-foreground motion-reduce:animate-none" />}
        {status === "error" && (
          <span className="grid justify-items-center gap-2 px-4 text-center text-muted-foreground">
            {messages.failed}
            {onRetry && version && (
              <button type="button" disabled={disabled} className="h-9 rounded-md bg-foreground/8 px-3 text-foreground outline-none hover:bg-foreground/15 focus-visible:bg-foreground/15 disabled:opacity-40 pointer-coarse:h-11" onClick={() => onRetry(version.id)}>
                {messages.retry}
              </button>
            )}
          </span>
        )}
      </div>
      {version && <VersionComparisonLabel version={version} slot={slot} align={align} />}
      {children}
    </div>
  );
}

/** The two versions, drawn for the current mode. */
export const VersionComparisonStage = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function VersionComparisonStage({ className, style, ...props }, ref) {
  const { versions, versionA, versionB, mode, divider, opacity, aspectRatio, messages } = useVersionComparison();
  const stageRef = useRef<HTMLDivElement | null>(null);
  const ratio = { aspectRatio };
  if (versions.length < 2) {
    return (
      <div ref={ref} data-slot="version-comparison-empty" className={cn("grid place-items-center rounded-md bg-foreground/5 px-4 text-center text-muted-foreground", className)} style={{ ...ratio, ...style }} {...props}>
        {messages.needTwo}
      </div>
    );
  }
  if (mode === "side") {
    return (
      <div ref={ref} data-slot="version-comparison-stage" data-mode={mode} className={cn("grid min-w-0 grid-cols-2 gap-2 @max-md/versions:grid-cols-1", className)} style={style} {...props}>
        <Pane version={versionA} slot="a" className="relative" style={ratio}>
          <UseButton version={versionA} top />
        </Pane>
        <Pane version={versionB} slot="b" className="relative" style={ratio}>
          <UseButton version={versionB} top />
        </Pane>
      </div>
    );
  }
  const top: CSSProperties = mode === "swipe" ? { clipPath: `inset(0 0 0 ${divider * 100}%)` } : { opacity };
  return (
    <div
      ref={(node) => {
        stageRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-slot="version-comparison-stage"
      data-mode={mode}
      className={cn("relative min-w-0 overflow-hidden rounded-md select-none", className)}
      style={{ ...ratio, ...style }}
      {...props}
    >
      <Pane version={versionA} slot="a" className="absolute inset-0" />
      <Pane version={versionB} slot="b" align="right" className="absolute inset-0" style={top} />
      {mode === "swipe" && <VersionComparisonDivider stageRef={stageRef} />}
      {/* Outside the panes, so moving the divider never clips them. */}
      <UseButton version={versionA} align="left" />
      <UseButton version={versionB} />
    </div>
  );
});

/** How strongly B shows over A. It appears in Overlay mode. */
export const VersionComparisonOpacity = forwardRef<HTMLDivElement, Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue">>(function VersionComparisonOpacity({ className, ...props }, ref) {
  const { versions, mode, opacity, disabled, messages, setOpacity, onOpacityChange, onOpacityCommit } = useVersionComparison();
  if (versions.length < 2 || mode !== "overlay") return null;
  return (
    <NumberField
      ref={ref}
      data-slot="version-comparison-opacity"
      label={messages.opacity}
      value={Math.round(opacity * 100)}
      min={0}
      max={100}
      step={1}
      unit="%"
      disabled={disabled}
      className={cn("min-w-0", className)}
      onValueChange={(next) => {
        setOpacity(next / 100);
        onOpacityChange?.(next / 100);
      }}
      onValueCommit={(next) => {
        setOpacity(next / 100);
        onOpacityCommit?.(next / 100);
      }}
      {...props}
    >
      <NumberFieldSlider className="h-9 pointer-coarse:h-11">
        <NumberFieldSliderFill />
        <NumberFieldSliderThumb />
        <NumberFieldLabel />
        <NumberFieldValue />
      </NumberFieldSlider>
    </NumberField>
  );
});

/** What differs between A and B, one row per property. It shows when your app passes changes. */
export const VersionComparisonChanges = forwardRef<HTMLDListElement, ComponentPropsWithoutRef<"dl">>(function VersionComparisonChanges({ className, ...props }, ref) {
  const { changes, messages } = useVersionComparison();
  if (!changes?.length) return null;
  return (
    <dl ref={ref} aria-label={messages.changes} data-slot="version-comparison-changes" className={cn("grid min-w-0 gap-1", className)} {...props}>
      {changes.map((change) => (
        <div key={change.label} className="flex h-9 min-w-0 items-center justify-between gap-3 rounded-md bg-foreground/8 px-2.5 pointer-coarse:h-11">
